package com.bigboldchat;

import com.bigboldchat.chat.FontLayoutService;
import com.bigboldchat.chat.FontMeasurementService;
import com.bigboldchat.chat.InputFontService;
import com.bigboldchat.chatbox.ChatRebuildCoordinator;
import com.bigboldchat.chatbox.ChatboxResizeService;
import com.bigboldchat.config.ChatboxConfigHandler;
import com.bigboldchat.config.FontConfigHandler;
import com.bigboldchat.debug.DebugManager;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.input.ChatboxHotkey;
import com.bigboldchat.layout.PrivateChatLayout;
import com.bigboldchat.overlay.PrivateChatOverlay;

import com.google.inject.Provides;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.CanvasSizeChanged;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostClientTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
		name = "Chat XL",
		description = "Resize the chatbox and its text for improved readability.<br>"
				+ "[A.K.A. BBC - Big Bold Chat]",
		conflicts = {"Chat Resizer", "Resizable Chat"},
		tags = {"1877", "accessibility", "bbc", "big", "bigger", "bold", "chat", "chatbox", "classic", "fixed", "font", "fonts", "large", "magnifier", "magnify", "messages", "modern", "pm", "private", "readability", "resizable", "resize", "resizer", "resizing", "scale", "size", "small", "text", "zoom"},
		enabledByDefault = true
)
public class ChatXL extends Plugin {

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private Configurations config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private DebugManager debugManager;
	@Inject
	private KeyManager keyManager;
	@Inject
	private OverlayManager overlayManager;

	/*
	 * Diagnostics & performance.
	 */
	private PerformanceMetrics performanceMetrics;

	/*
	 * Production services.
	 */
	private FontMeasurementService fontMeasurementService;
	private FontLayoutService fontLayoutService;
	private InputFontService inputFontService;
	private ChatboxResizeService chatboxResizeService;
	private ChatRebuildCoordinator chatRebuildCoordinator;
	private ChatboxHotkey chatboxHotkey;
	private PrivateChatOverlay privateChatOverlay;
	private PrivateChatLayout privateChatLayout;

	/*
	 * Configuration handlers.
	 */
	private ChatboxConfigHandler chatboxConfigHandler;
	private FontConfigHandler fontConfigHandler;

	/**
	 * ================================================================
	 * START-UP & SHUT-DOWN
	 * ================================================================
	 */
	@Override
	protected void startUp() {
		performanceMetrics = debugManager.activate();
		chatboxResizeService = new ChatboxResizeService(client, configManager, overlayManager, performanceMetrics);
		chatboxResizeService.onGameStateChanged(client.getGameState());
		privateChatOverlay = new PrivateChatOverlay();
		privateChatLayout = new PrivateChatLayout(client, config, configManager, privateChatOverlay);
		overlayManager.add(privateChatOverlay);
		chatRebuildCoordinator = new ChatRebuildCoordinator(client, clientThread, config, chatboxResizeService, performanceMetrics);
		chatboxHotkey = new ChatboxHotkey(clientThread, config, chatboxResizeService, keyManager, this::clearChatHistory);
		chatboxHotkey.activate();
		fontMeasurementService = new FontMeasurementService(client, performanceMetrics);
		fontLayoutService = new FontLayoutService(client, config, fontMeasurementService, performanceMetrics);
		inputFontService = new InputFontService(client, config);
		chatboxConfigHandler = new ChatboxConfigHandler(chatRebuildCoordinator);
		fontConfigHandler = new FontConfigHandler(client, clientThread, fontLayoutService, inputFontService, performanceMetrics);
		/*
		 * Refresh retained rows through the active layout pipeline.
		 */
		clientThread.invokeLater(() -> {
			if (chatRebuildCoordinator != null) {
				chatRebuildCoordinator.onStartup();
			}

			if (inputFontService != null) {
				inputFontService.sync();
			}

			debugManager.onLoggedIn();
		});

		log.debug("[Chat XL] Plugin Initiated.");
	}

	@Override
	protected void shutDown() {
		final FontLayoutService shutdownLayoutService = fontLayoutService;
		final InputFontService shutdownInputFontService = inputFontService;
		final ChatboxResizeService shutdownResizeService = chatboxResizeService;
		final PrivateChatOverlay shutdownPrivateChatOverlay = privateChatOverlay;
		final PrivateChatLayout shutdownPrivateChatLayout = privateChatLayout;
		final PerformanceMetrics shutdownPerformanceMetrics = performanceMetrics;
		final boolean uninstalling = debugManager.prepareShutdown();

		/*
		 * Disable PRE / POST and config handling before restoration.
		 */
		if (chatboxConfigHandler != null) {
			chatboxConfigHandler.deactivate();
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.deactivate();
		}

		if (fontConfigHandler != null) {
			fontConfigHandler.deactivate();
		}

		if (chatboxHotkey != null) {
			chatboxHotkey.deactivate();
		}

		fontLayoutService = null;
		inputFontService = null;
		chatboxResizeService = null;
		chatRebuildCoordinator = null;
		chatboxHotkey = null;
		privateChatOverlay = null;
		privateChatLayout = null;
		fontMeasurementService = null;
		chatboxConfigHandler = null;
		fontConfigHandler = null;

		if (shutdownPrivateChatOverlay != null) {
			overlayManager.remove(shutdownPrivateChatOverlay);
		}

		debugManager.deactivate();

		if (shutdownPerformanceMetrics != null) {
			shutdownPerformanceMetrics.recordRefreshChat(PerformanceMetrics.RefreshReason.SHUTDOWN);
		}

		// Restore native presentation on the client thread.
		clientThread.invokeLater(() -> {
			if (shutdownPrivateChatLayout != null) {
				shutdownPrivateChatLayout.restoreNative();
			}

			final ChatboxResizeService.ScrollBaseline scrollBaseline = shutdownResizeService != null
					? shutdownResizeService.captureScrollBaseline()
					: null;

			if (shutdownResizeService != null) {
				shutdownResizeService.restoreNativeSize();
			}

			if (shutdownLayoutService != null) {
				shutdownLayoutService.restoreNativePresentation();
				shutdownLayoutService.reset();
			}

			if (shutdownInputFontService != null) {
				shutdownInputFontService.restoreNativePresentation();
			}

			client.refreshChat();

			if (shutdownResizeService != null) {
				shutdownResizeService.restoreScrollBaseline(scrollBaseline);
			}

			debugManager.finishShutdown(uninstalling);

			if (shutdownPerformanceMetrics != null) {
				shutdownPerformanceMetrics.reportNow();
			}
		});

		performanceMetrics = null;

		log.debug("[Chat XL] Plugin Terminated.");
	}

	/**
	 * ================================================================
	 * GAME STATE
	 * ================================================================
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event == null) {
			return;
		}

		if (chatboxResizeService != null) {
			chatboxResizeService.onGameStateChanged(event.getGameState());
		}

		if (event.getGameState() != GameState.LOGGED_IN) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onLoggedIn();
		}

		debugManager.onLoggedIn();
	}

	/**
	 * ================================================================
	 * CANVAS SIZE
	 * ================================================================
	 */
	@Subscribe
	public void onCanvasSizeChanged(CanvasSizeChanged event) {
		if (event == null) {
			return;
		}

		if (chatboxResizeService != null) {
			chatboxResizeService.onCanvasSizeChanged();
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onCanvasSizeChanged();
		}
	}

	/**
	 * ================================================================
	 * INTERFACE LIFECYCLE
	 * ================================================================
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event == null) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onInterfaceChanged();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		if (event == null) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onInterfaceChanged();
		}
	}

	/**
	 * ================================================================
	 * CHAT CONTROLS
	 * ================================================================
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event == null || chatboxResizeService == null) {
			return;
		}

		if (!chatboxResizeService.onChatControlClicked(event.getWidget())) {
			return;
		}

		clientThread.invokeLater(() -> {
			if (chatboxResizeService != null) {
				chatboxResizeService.finishChatControlClick();
			}
		});
	}

	/**
	 * ================================================================
	 * CHAT COMMANDS
	 * ================================================================
	 */
	@Subscribe
	public void onCommandExecuted(CommandExecuted event) {
		if (event == null) {
			return;
		}

		final String command = event.getCommand();
		if ("clear".equalsIgnoreCase(command) || "cls".equalsIgnoreCase(command)) {
			clientThread.invokeLater(this::clearChatHistory);
			return;
		}

		debugManager.onCommandExecuted(event);
	}

	private void clearChatHistory() {
		boolean removed = false;

		for (ChatMessageType messageType : ChatMessageType.values()) {
			final ChatLineBuffer lineBuffer = client.getChatLineMap().get(messageType.getType());
			if (lineBuffer == null) {
				continue;
			}

			final MessageNode[] lines = lineBuffer.getLines().clone();

			for (MessageNode line : lines) {
				if (line == null) {
					continue;
				}

				lineBuffer.removeMessageNode(line);
				removed = true;
			}
		}

		if (removed) {
			client.refreshChat();
		}
	}

	/**
	 * ================================================================
	 * CONFIGURATION
	 * ================================================================
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		debugManager.onConfigChanged(event);

		if (chatboxResizeService != null && chatboxResizeService.isInventoryOverlayReset(event)) {
			chatboxResizeService.guardInventoryOverlayReset();
			clientThread.invokeLater(() -> {
				if (chatboxResizeService != null) {
					chatboxResizeService.reconcileInventoryOverlayReset(config.chatboxWidth(), config.chatboxHeight());
				}
			});
		}

		if (privateChatLayout != null) {
			privateChatLayout.onConfigChanged(event);
		}

		if (chatboxConfigHandler != null && chatboxConfigHandler.onConfigChanged(event)) {
			return;
		}

		if (fontConfigHandler != null) {
			fontConfigHandler.onConfigChanged(event);
		}
	}

	/**
	 * ================================================================
	 * CONFIGURATION PROVIDER
	 * ================================================================
	 */
	@Provides
	Configurations provideConfig(ConfigManager configManager) {
		return configManager.getConfig(Configurations.class);
	}

	/**
	 * ================================================================
	 * CHAT CONSTRUCTION
	 * ================================================================
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		debugManager.onChatboxPre(event);

		if (chatboxResizeService != null) {
			chatboxResizeService.onScriptPreFired(event, config.chatboxWidth(), config.chatboxHeight());
		}

		debugManager.onFontPre(event);

		if (fontLayoutService == null) {
			return;
		}

		final boolean metricsEnabled = performanceMetrics != null && performanceMetrics.isEnabled();

		final long started = metricsEnabled
				? System.nanoTime()
				: 0L;

		fontLayoutService.onScriptPreFired(event);

		if (metricsEnabled && event != null) {
			performanceMetrics.recordPre(event.getScriptId(), System.nanoTime() - started);
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		debugManager.onChatboxPost(event);

		if (fontLayoutService != null) {
			final boolean metricsEnabled = performanceMetrics != null && performanceMetrics.isEnabled();

			final long started = metricsEnabled
					? System.nanoTime()
					: 0L;

			fontLayoutService.onScriptPostFired(event);

			if (metricsEnabled && event != null) {
				performanceMetrics.recordPost(event.getScriptId(), System.nanoTime() - started);
			}
		}

		if (inputFontService != null) {
			inputFontService.onScriptPostFired(event);
		}

		if (chatboxResizeService != null) {
			chatboxResizeService.onScriptPostFired(event, config.chatboxWidth(), config.chatboxHeight());
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onScriptPostFired(event);
		}

		if (privateChatLayout != null) {
			privateChatLayout.onScriptPostFired(event);
		}

		debugManager.onFontPost(event);
		debugManager.reportPerformance();
	}

	/**
	 * ================================================================
	 * RENDER LIFECYCLE
	 * ================================================================
	 */
	@Subscribe
	public void onPostClientTick(PostClientTick event) {
		if (chatboxResizeService != null) {
			chatboxResizeService.reconcilePostLoginGeometry(config.chatboxWidth(), config.chatboxHeight());
		}

		if (privateChatLayout != null) {
			privateChatLayout.reconcileAfterClientTick();
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event) {
		boolean widthChanged = false;
		boolean heightChanged = false;

		if (privateChatLayout != null) {
			/*
			 * Resolve split-PM placement before retained chat geometry is refreshed.
			 */
			final PrivateChatLayout.Result privateResult = privateChatLayout.sync();
			widthChanged |= privateResult.isWidthChanged();
		}

		if (chatboxResizeService != null) {
			chatboxResizeService.reconcileBeforeRender(config.chatboxWidth(), config.chatboxHeight());

			final ChatboxResizeService.LiveRefresh refresh = chatboxResizeService.consumeLiveRefresh();
			if (refresh != null) {
				widthChanged |= refresh.isWidthChanged();
				heightChanged |= refresh.isHeightChanged();
			}
		}

		if (chatRebuildCoordinator != null && (widthChanged || heightChanged)) {
			/*
			 * Coalesce chatbox and split-PM geometry changes into one retained-chat refresh.
			 */
			chatRebuildCoordinator.refreshLiveGeometry(widthChanged, heightChanged);
		}
	}
}

package com.bigboldchat;

import com.bigboldchat.config.ChatFont;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("bigboldchat")
public interface Configurations extends Config {
	/**
	 *  CHAT BOX
	 */
	@ConfigSection(
			name = "Chatbox",
			description = "Modify the Chatbox in game layouts.",
			position = 0
	)
	String chatBoxSection = "chatBox";

	@ConfigItem(
			keyName = "chatFont",
			name = "Chat Font",
			description = "Font used for chatbox and private-message text.",
			position = 0,
			section = chatBoxSection
	)
	default ChatFont chatFont() {
		return ChatFont.PLAIN_12;
	}

	@ConfigItem(
			keyName = "inputFont",
			name = "Input Font",
			description = "Font used for text typed into the chatbox.",
			position = 1,
			section = chatBoxSection
	)
	default ChatFont inputFont() {
		return ChatFont.PLAIN_12;
	}

	@Range(min = 200, max = 8192)
	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "chatboxWidth",
			name = "Chatbox Width",
			description = "Width of the chatbox.",
			position = 2,
			section = chatBoxSection
	)
	default int chatboxWidth() {
		return 519;
	}

	@Range(min = 100, max = 8192)
	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "chatboxHeight",
			name = "Chatbox Height",
			description = "Height of the chatbox.",
			position = 3,
			section = chatBoxSection
	)
	default int chatboxHeight() {
		return 165;
	}

	@Range(min = 200, max = 8192)
	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "splitPmWidth",
			name = "Split-PM Width",
			description = "Maximum width of split private chat. Follows the live chatbox width until overridden.",
			position = 4,
			section = chatBoxSection
	)
	default int splitPmWidth() {
		/*
		 * Keep the visible default synchronized with Chatbox Width. ConfigManager
		 * supplies a stored split-PM value instead once the user explicitly
		 * overrides this item; resetting it returns to inherited live width.
		 */
		return chatboxWidth();
	}

	@ConfigItem(
			keyName = "hideChatboxButtons",
			name = "Hide Chatbox Buttons",
			description = "Hide the chatbox button row.",
			position = 5,
			section = chatBoxSection
	)
	default boolean hideChatboxButtons() {
		return false;
	}

	@ConfigItem(
			keyName = "hideChatboxHotkey",
			name = "Hide Chatbox Hotkey",
			description = "Toggle the chatbox body between hidden and visible.",
			position = 6,
			section = chatBoxSection
	)
	default Keybind hideChatboxHotkey() {
		return new Keybind(KeyEvent.VK_C, InputEvent.ALT_DOWN_MASK);
	}

	@ConfigItem(
			keyName = "clearChatHotkey",
			name = "Clear Chat Hotkey",
			description = "Clear all chat messages.<br>You can also type ::clear or ::cls.",
			position = 7,
			section = chatBoxSection
	)
	default Keybind clearChatHotkey() {
		return new Keybind(KeyEvent.VK_X, InputEvent.ALT_DOWN_MASK);
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.debug.PerformanceMetrics;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import net.runelite.client.util.Text;

/**
 * Normalizes chat text for semantic comparison and font measurement.
 */
public final class ChatTextNormalizer {
	private static final Pattern LINE_BREAK_PATTERN = Pattern.compile("<br\\s*/?>", Pattern.CASE_INSENSITIVE);
	private static final Pattern IMAGE_PATTERN = Pattern.compile("<img=(\\d+)>", Pattern.CASE_INSENSITIVE);
	private static final Pattern AT_PATTERN = Pattern.compile("<at>", Pattern.CASE_INSENSITIVE);

	// Optional performance instrumentation; null when unavailable.
	private final PerformanceMetrics performanceMetrics;

	public ChatTextNormalizer() {
		this(null);
	}

	public ChatTextNormalizer(PerformanceMetrics performanceMetrics) {
		this.performanceMetrics = performanceMetrics;
	}

	String normalizeSemantic(String text) {
		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		try {
			if (text == null) {
				return null;
			}

			/*
			 * Most chat text contains no markup.
			 */
			if (text.indexOf('<') < 0) {
				final String normalized = text.indexOf('\u00A0') >= 0
						? text.replace('\u00A0', ' ')
						: text;

				return normalized.trim();
			}

			final String withLineBreaks = LINE_BREAK_PATTERN.matcher(text).replaceAll("\n");
			final String withVisibleAtCharacters = AT_PATTERN.matcher(withLineBreaks).replaceAll("@");
			final String semantic = Text.removeTags(withVisibleAtCharacters).replace('\u00A0', ' ').trim();
			if (!semantic.isEmpty()) {
				return semantic;
			}

			// Keep image-only messages identifiable after markup is removed.
			return extractImages(withVisibleAtCharacters);
		} finally {
			if (performanceMetrics != null && performanceMetrics.isEnabled()) {
				performanceMetrics.recordNormalization(System.nanoTime() - started);
			}
		}
	}

	String measureSemantic(String text) {
		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		try {
			if (text == null) {
				return null;
			}

			/*
			 * Keep inline image markup for font measurement.
			 */
			if (text.indexOf('<') < 0) {
				final String normalized = text.indexOf('\u00A0') >= 0
						? text.replace('\u00A0', ' ')
						: text;

				return normalized.trim();
			}

			final String withLineBreaks = LINE_BREAK_PATTERN.matcher(text).replaceAll("\n");
			final String withVisibleAtCharacters = AT_PATTERN.matcher(withLineBreaks).replaceAll("@");
			return withVisibleAtCharacters.replace('\u00A0', ' ').trim();
		} finally {
			if (performanceMetrics != null && performanceMetrics.isEnabled()) {
				performanceMetrics.recordNormalization(
						System.nanoTime()
								- started);
			}
		}
	}

	String renderText(String text) {
		if (text == null || text.indexOf('<') < 0) {
			return text;
		}

		return AT_PATTERN.matcher(text).replaceAll("@");
	}

	/*
	 * HELPERS
	 */

	private String extractImages(String text) {
		if (text == null || text.isEmpty()) {
			return "";
		}

		final Matcher matcher = IMAGE_PATTERN.matcher(text);
		final StringBuilder images = new StringBuilder();
		while (matcher.find()) {
			images.append("<img=").append(matcher.group(1)).append('>');
		}

		return images.toString();
	}
}

package com.bigboldchat.chat;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

import com.bigboldchat.chatbox.ChatboxGeometry;

import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;

/**
 * Adapts mounted dialogue and prompt geometry to ChatXL's effective size.
 */
public final class DialoguePrompts {
	private static final int MIN_SIDE_TEXT_WIDTH = 160;
	private static final int MIN_OPTION_ROW_GAP = 4;
	private static final int MIN_DIALOGUE_GAP = 4;
	private static final int MIN_CONTENT_PADDING = 4;
	private static final int OPTION_OUTER_PADDING = 4;
	private static final int OPTION_GLYPH_PADDING = 4;
	private static final int OPTION_GAP_DIVISOR = 4;
	private static final int DIALOGUE_LINE_GAP = 0;
	private static final int STACK_PADDING = 10;
	private static final int STACK_GAP = 12;
	private static final int SPRITE_SIDE_TEXT_X = 96;
	private static final int SPRITE_ITEM_PADDING = 16;
	private static final int SPRITE_STACK_PADDING = 10;
	private static final int SPRITE_STACK_GAP = 12;

	private final Client client;

	private OptionsState optionsState;
	private PortraitState npcState;
	private PortraitState playerState;
	private SpriteState spriteState;

	public DialoguePrompts(Client client) {
		this.client = client;
	}

	public Result apply(int effectiveWidth, int effectiveBodyHeight) {
		if (effectiveWidth <= 0 || effectiveBodyHeight <= 0) {
			return reset();
		}

		final MutableResult result = new MutableResult();
		applyOptions(effectiveWidth, effectiveBodyHeight, result);
		npcState = applyPortrait(effectiveWidth, effectiveBodyHeight, false, npcState, result,
				InterfaceID.ChatLeft.UNIVERSE,
				InterfaceID.ChatLeft.SAFEZONE,
				InterfaceID.ChatLeft.HEAD,
				InterfaceID.ChatLeft.CONTENT,
				InterfaceID.ChatLeft.NAME,
				InterfaceID.ChatLeft.CONTINUE,
				InterfaceID.ChatLeft.TEXT);
		playerState = applyPortrait(effectiveWidth, effectiveBodyHeight, true, playerState, result,
				InterfaceID.ChatRight.UNIVERSE,
				InterfaceID.ChatRight.SAFEZONE,
				InterfaceID.ChatRight.HEAD,
				InterfaceID.ChatRight.CONTENT,
				InterfaceID.ChatRight.NAME,
				InterfaceID.ChatRight.CONTINUE,
				InterfaceID.ChatRight.TEXT);
		spriteState = applySprite(effectiveWidth, effectiveBodyHeight, spriteState, result);
		return result.build();
	}

	public Result reset() {
		final MutableResult result = new MutableResult();
		restoreOptions(result);
		npcState = restorePortrait(npcState, result);
		playerState = restorePortrait(playerState, result);
		spriteState = restoreSprite(spriteState, result);
		return result.build();
	}

