	private NativeWidgetState nativeState(Widget widget) {
		return nativeWidgetStates.computeIfAbsent(widget, ignored -> new NativeWidgetState());
	}

	private boolean sameText(String left, String right) {
		return left == null
				? right == null
				: left.equals(right);
	}

	private void recordWidgetMutation() {
		if (performanceMetrics != null) {
			performanceMetrics.recordWidgetMutation();
		}
	}

	void revalidateWidgetIfChanged(Widget widget, boolean changed) {
		if (widget == null || !changed) {
			return;
		}

		widget.revalidate();

		if (performanceMetrics != null) {
			performanceMetrics.recordRevalidate();
		}
	}

	/*
	 * ================================================================
	 * ROW CORRELATION
	 * ================================================================
	 */

	List<Widget> collectRow(Widget lineWidget, Surface surface) {
		if (lineWidget == null || surface == null) {
			return Collections.emptyList();
		}

		final RowCorrelationIndex rowIndex = rowIndexes.computeIfAbsent(
				surface, key ->
						new RowCorrelationIndex(client, key, performanceMetrics));

		final List<Widget> result = rowIndex.findRow(lineWidget);

		if (performanceMetrics != null) {
			performanceMetrics.recordRowSearches(result.size());
		}

		return result;
	}

	private void observeWidgetFromSurfaceScan(Surface surface, Widget root, Widget widget) {
		if (surface == null || root == null || widget == null) {
			return;
		}

		final RowCorrelationIndex rowIndex = rowIndexes.get(surface);
		if (rowIndex != null) {
			rowIndex.observeSurfaceWidget(root, widget);
		}
	}

	private void notifyIndexedWidgetGeometryChanged(Widget widget, int previousOriginalY, int previousRelativeY) {
		if (widget == null || rowIndexes.isEmpty()) {
			return;
		}

		for (RowCorrelationIndex rowIndex : rowIndexes.values()) {
			if (rowIndex != null) {
				rowIndex.onWidgetGeometryChangedByChatXl(widget, previousOriginalY, previousRelativeY);
			}
		}
	}

	private boolean containsIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return false;
		}

		for (Widget widget : widgets) {
			if (widget == target) {
				return true;
			}
		}

		return false;
	}

	private void removeIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return;
		}

		for (int i = widgets.size() - 1; i >= 0; i--) {
			if (widgets.get(i) == target) {
				widgets.remove(i);
			}
		}
	}

	private Widget matchRow(List<Widget> rowWidgets, String targetText, Widget excludedWidget) {
		if (rowWidgets == null || rowWidgets.isEmpty() || targetText == null) {
			return null;
		}

		Widget match = null;
		int matches = 0;

		for (Widget widget : rowWidgets) {
			if (widget == null || widget == excludedWidget) {
				continue;
			}

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || !semantic.equalsIgnoreCase(targetText)) {
				continue;
			}

			match = widget;
			matches++;

			if (matches > 1) {
				return null;
			}
		}

		return matches == 1
				? match
				: null;
	}

	private Widget matchEmptyBodyRow(List<Widget> rowWidgets, int nativeBodyX) {
		if (rowWidgets == null || rowWidgets.isEmpty()) {
			return null;
		}

		Widget match = null;
		int matches = 0;

		for (Widget widget : rowWidgets) {
			if (widget == null || widget.getOriginalX() != nativeBodyX) {
				continue;
			}

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || !semantic.isEmpty()) {
				continue;
			}

			match = widget;
			matches++;

			if (matches > 1) {
				return null;
			}
		}

		return matches == 1
				? match
				: null;
	}

	/*
	 * ================================================================
	 * BODY CORRELATION
	 * ================================================================
	 */

	Widget findTargetWidgetForLine(
			String targetText,
			Widget lineWidget,
			Surface surface,
			List<Widget> rowWidgets,
			FallbackCorrelationContext fallbackContext) {
		if (targetText == null || lineWidget == null || surface == null || fallbackContext == null) {
			return null;
		}

		final Widget rowMatch = matchRow(rowWidgets, targetText, null);
		if (rowMatch != null) {
			return rowMatch;
		}

		final List<Widget> matches = fallbackContext.findMatches(targetText);
		if (matches.isEmpty()) {
			return null;
		}

		/*
		 * Strongest match:
		 *
		 * same OriginalY + same RelativeY.
		 */
		for (Widget widget : matches) {
			if (widget.getOriginalY() == lineWidget.getOriginalY()
					&& widget.getRelativeY() == lineWidget.getRelativeY()) {
				return widget;
			}
		}

		/*
		 * Next strongest:
		 *
		 * unique OriginalY.
		 */
		Widget originalYMatch = null;
		int originalYMatches = 0;
		for (Widget widget : matches) {
			if (widget.getOriginalY() == lineWidget.getOriginalY()) {
				originalYMatch = widget;
				originalYMatches++;
			}
		}

		if (originalYMatches == 1) {
			return originalYMatch;
		}

		/*
		 * Next:
		 *
		 * unique RelativeY.
		 */
		Widget relativeYMatch = null;
		int relativeYMatches = 0;
		for (Widget widget : matches) {
			if (widget.getRelativeY() == lineWidget.getRelativeY()) {
				relativeYMatch = widget;
				relativeYMatches++;
			}
		}

		if (relativeYMatches == 1) {
			return relativeYMatch;
		}

		/*
		 * Final conservative fallback:
		 *
		 * exactly one semantic match on the entire surface.
		 */
		return matches.size() == 1
				? matches.get(0)
				: null;
	}

	/*
	 * ================================================================
	 * PREFIX CORRELATION
	 * ================================================================
	 */

	private List<Widget> findPrefixWidgetsForLine(
			List<String> rawPrefixComponents,
			Widget lineWidget,
			Surface surface,
			Widget bodyWidget,
			List<Widget> rowWidgets,
			FallbackCorrelationContext fallbackContext) {
		if (rawPrefixComponents == null
				|| rawPrefixComponents.isEmpty()
				|| lineWidget == null
				|| surface == null
				|| bodyWidget == null
				|| fallbackContext == null) {
			return Collections.emptyList();
		}

		final List<Widget> result = new ArrayList<>();

		for (String rawPrefix : rawPrefixComponents) {
			final String targetText = textNormalizer.normalizeSemantic(rawPrefix);
			if (targetText == null || targetText.isEmpty()) {
				continue;
			}

			final Widget rowMatch = matchRow(rowWidgets, targetText, bodyWidget);
			if (rowMatch != null && !containsIdentity(result, rowMatch)) {
				result.add(rowMatch);
				continue;
			}

			final List<Widget> matches = fallbackContext.findMatches(targetText);
			if (matches.isEmpty()) {
				continue;
			}

			Widget selected = null;

			/*
			 * Prefer the exact body row.
			 */
			for (Widget candidate : matches) {
				if (candidate == bodyWidget || containsIdentity(result, candidate)) {
					continue;
				}

				if (candidate.getOriginalY() == bodyWidget.getOriginalY()
						&& candidate.getRelativeY() == bodyWidget.getRelativeY()) {
					if (selected != null) {
						selected = null;
						break;
					}

					selected = candidate;
				}
			}

			if (selected == null) {
				/*
				 * Then prefer a unique OriginalY match.
				 */
				int originalYMatches = 0;

				for (Widget candidate : matches) {
					if (candidate == bodyWidget || containsIdentity(result, candidate)) {
						continue;
					}

					if (candidate.getOriginalY() == bodyWidget.getOriginalY()) {
						selected = candidate;

						originalYMatches++;
					}
				}

				if (originalYMatches != 1) {
					selected = null;
				}
			}

			if (selected == null) {
				/*
				 * Then prefer a unique RelativeY match.
				 */
				int relativeYMatches = 0;

				for (Widget candidate : matches) {
					if (candidate == bodyWidget || containsIdentity(result, candidate)) {
						continue;
					}

					if (candidate.getRelativeY() == bodyWidget.getRelativeY()) {
						selected = candidate;
						relativeYMatches++;
					}
				}

				if (relativeYMatches != 1) {
					selected = null;
				}
			}

			if (selected == null) {
				/*
				 * Final conservative fallback:
				 *
				 * exactly one remaining semantic match.
				 */
				Widget onlyRemaining = null;

				int remaining = 0;

				for (Widget candidate : matches) {
					if (candidate == bodyWidget || containsIdentity(result, candidate)) {
						continue;
					}

					onlyRemaining = candidate;
					remaining++;
				}

				if (remaining == 1) {
					selected = onlyRemaining;
				}
			}

			if (selected != null && !containsIdentity(result, selected)) {
				result.add(selected);
			}
		}

		return result;
	}

	/*
	 * ================================================================
	 * RANK ICON CORRELATION
	 * ================================================================
	 */

	Widget findRankIconWidget(
			FontMeasurementService.ChannelPrefixLayout nativeLayout,
			Widget rowAnchor,
			List<Widget> rowWidgets) {
		if (nativeLayout == null || rowAnchor == null || nativeLayout.rankIconSpriteId < 0) {
			return null;
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRankSearch();
		}

		/*
		 * First inspect the already-collected row.
		 *
		 * This remains the common path. The diagnostic counters below classify
		 * why this strict row-first lookup failed without changing its matching
		 * criteria.
		 */
		final Widget rowMatch = findRankIconWidgetInRow(nativeLayout, rowAnchor, rowWidgets);
		if (rowMatch != null) {
			return rowMatch;
		}

		final Widget root = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		if (root == null) {
			if (performanceMetrics != null) {
				performanceMetrics.recordRankFallback();
				performanceMetrics.recordRankFallbackMiss();
			}

			return null;
		}

		/*
		 * Retry a missed rank lookup across the row index's shallow scan domain:
		 * root plus immediate dynamic/static/nested children.
		 */
		final Widget shallowMatch = findRankIconWidgetShallow(
				root,
				nativeLayout.rankIconSpriteId,
				nativeLayout.rankIconX,
				rowAnchor.getOriginalY(),
				rowAnchor.getRelativeY());

		if (shallowMatch != null) {
			if (performanceMetrics != null) {
				performanceMetrics.recordRankShallowRecovery();
			}

			observeWidgetFromSurfaceScan(Surface.CHATBOX, root, shallowMatch);

			return shallowMatch;
		}

		/*
		 * Preserve the recursive tree search as the final correctness fallback.
		 * RankFallback therefore continues to mean that the full-tree path was
		 * actually required.
		 */
		if (performanceMetrics != null) {
			performanceMetrics.recordRankFallback();
		}

		final Widget fallbackMatch = findRankIconWidgetRecursive(
				root,
				nativeLayout.rankIconSpriteId,
				nativeLayout.rankIconX,
				rowAnchor.getOriginalY(),
				rowAnchor.getRelativeY());

		if (performanceMetrics != null) {
			if (fallbackMatch != null) {
				performanceMetrics.recordRankFallbackHit();
			} else {
				performanceMetrics.recordRankFallbackMiss();
			}
		}

		/*
		 * Add a recursively found rank widget to the persistent row index.
		 */
		if (fallbackMatch != null) {
			observeWidgetFromSurfaceScan(Surface.CHATBOX, root, fallbackMatch);
		}

		return fallbackMatch;
	}

	private Widget findRankIconWidgetInRow(
			FontMeasurementService.ChannelPrefixLayout nativeLayout,
			Widget rowAnchor,
			List<Widget> rowWidgets) {
		boolean spriteMatched = false;
		boolean xMatched = false;

		if (rowWidgets == null || rowWidgets.isEmpty()) {
			if (performanceMetrics != null) {
				performanceMetrics.recordRankRowNoSprite();
			}

			return null;
		}

		for (Widget widget : rowWidgets) {
			if (widget == null) {
				continue;
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordRankNodesExamined(1);
			}

			if (widget.getSpriteId() != nativeLayout.rankIconSpriteId) {
				continue;
			}

			spriteMatched = true;

			if (widget.getOriginalX() != nativeLayout.rankIconX) {
				continue;
			}

			xMatched = true;

			if (widget.getOriginalY() != rowAnchor.getOriginalY()
					&& widget.getRelativeY() != rowAnchor.getRelativeY()) {
				continue;
			}

			return widget;
		}

		if (performanceMetrics != null) {
			if (!spriteMatched) {
				performanceMetrics.recordRankRowNoSprite();
			} else if (!xMatched) {
				performanceMetrics.recordRankRowXMismatch();
			} else {
				performanceMetrics.recordRankRowYMismatch();
			}
		}

		return null;
	}

	private Widget findRankIconWidgetShallow(
			Widget root,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (root == null) {
			return null;
		}

		Widget match = findRankIconWidgetCandidate(root, spriteId, originalX, originalY, relativeY);
		if (match != null) {
			return match;
		}

		match = findRankIconWidgetInShallowArray(root.getDynamicChildren(), spriteId, originalX, originalY, relativeY);
		if (match != null) {
			return match;
		}

		match = findRankIconWidgetInShallowArray(root.getStaticChildren(), spriteId, originalX, originalY, relativeY);
		if (match != null) {
			return match;
		}

		return findRankIconWidgetInShallowArray(root.getNestedChildren(), spriteId, originalX, originalY, relativeY);
	}

	private Widget findRankIconWidgetInShallowArray(
			Widget[] widgets,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (widgets == null) {
			return null;
		}

		for (Widget widget : widgets) {
			final Widget match = findRankIconWidgetCandidate(widget, spriteId, originalX, originalY, relativeY);
			if (match != null) {
				return match;
			}
		}

		return null;
	}

	private Widget findRankIconWidgetCandidate(
			Widget widget,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (widget == null) {
			return null;
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRankNodesExamined(1);
		}

		return widget.getSpriteId() == spriteId
				&& widget.getOriginalX() == originalX
				&& (widget.getOriginalY() == originalY
				|| widget.getRelativeY() == relativeY)
				? widget
				: null;
	}

	private Widget findRankIconWidgetRecursive(
			Widget widget,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (widget == null) {
			return null;
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRankNodesExamined(1);
		}

		if (widget.getSpriteId()
				== spriteId
				&& widget.getOriginalX()
				== originalX
				&& (widget.getOriginalY() == originalY || widget.getRelativeY() == relativeY)) {
			return widget;
		}

		final Widget[] dynamicChildren = widget.getDynamicChildren();
		if (dynamicChildren != null) {
			for (Widget child : dynamicChildren) {
				final Widget result = findRankIconWidgetRecursive(child, spriteId, originalX, originalY, relativeY);
				if (result != null) {
					return result;
				}
			}
		}

		final Widget[] staticChildren = widget.getStaticChildren();
		if (staticChildren != null) {
			for (Widget child : staticChildren) {
				final Widget result = findRankIconWidgetRecursive(child, spriteId, originalX, originalY, relativeY);
				if (result != null) {
					return result;
				}
			}
		}

		final Widget[] nestedChildren = widget.getNestedChildren();
		if (nestedChildren != null) {
			for (Widget child : nestedChildren) {
				final Widget result = findRankIconWidgetRecursive(child, spriteId, originalX, originalY, relativeY);
				if (result != null) {
					return result;
				}
			}
		}

		return null;
	}

	/*
	 * ================================================================
	 * FALLBACK CORRELATION
	 * ================================================================
	 */

	final class FallbackCorrelationContext {
		private final Surface surface;

		private Map<String, List<Widget>> widgetsBySemantic;

		FallbackCorrelationContext(Surface surface) {
			this.surface = surface;
		}

		List<Widget> findMatches(String targetText) {
			if (targetText == null || targetText.isEmpty() || surface == null) {
				return Collections.emptyList();
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordFallbackSearch();
			}

			if (widgetsBySemantic == null) {
				buildIndex();

				if (performanceMetrics != null) {
					performanceMetrics.recordFallbackBuild();
				}
			} else if (performanceMetrics != null) {
				performanceMetrics.recordFallbackReuse();
			}

			final List<Widget> matches = widgetsBySemantic.get(semanticKey(targetText));
			return matches != null
					? matches
					: Collections.emptyList();
		}

		private void buildIndex() {
			widgetsBySemantic = new HashMap<>();

			final Widget root = surface == Surface.SPLIT_PRIVATE
					? client.getWidget(InterfaceID.PM_CHAT, 0)
					: client.getWidget(InterfaceID.Chatbox.SCROLLAREA);

			if (root == null) {
				return;
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordSurfaceSearch();
			}

			indexWidget(root, root);
			indexWidgets(root, root.getDynamicChildren());
			indexWidgets(root, root.getStaticChildren());
			indexWidgets(root, root.getNestedChildren());
		}

		private void indexWidgets(Widget root, Widget[] widgets) {
			if (widgets == null) {
				return;
			}

			for (Widget widget : widgets) {
				indexWidget(root, widget);
			}
		}

		private void indexWidget(Widget root, Widget widget) {
			if (widget == null) {
				return;
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordWidgetsExamined(1);
			}

			/*
			 * A complete fallback scan has already paid the enumeration cost.
			 * Teach the persistent row index about every widget encountered,
			 * including textless sprite widgets such as channel rank icons.
			 */
			observeWidgetFromSurfaceScan(surface, root, widget);

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || semantic.isEmpty()) {
				return;
			}

			widgetsBySemantic.computeIfAbsent(semanticKey(semantic), ignored -> new ArrayList<>()).add(widget);
		}

		private String semanticKey(String text) {
			return text.toLowerCase(Locale.ROOT);
		}
	}

	/*
	 * ================================================================
	 * SURFACE
	 * ================================================================
	 */

	private Surface determineSurface(int parentWidgetId) {
		return WidgetUtil.componentToInterface(parentWidgetId) == InterfaceID.PM_CHAT
				? Surface.SPLIT_PRIVATE
				: Surface.CHATBOX;
	}

	/*
	 * ================================================================
	 * LIFECYCLE
	 * ================================================================
	 */

	@SuppressWarnings("deprecation")
	public void restoreNativePresentation() {
		if (nativeWidgetStates.isEmpty()) {
			return;
		}

		for (Map.Entry<Widget, NativeWidgetState> entry : nativeWidgetStates.entrySet()) {
			final Widget widget = entry.getKey();
			final NativeWidgetState state = entry.getValue();
			if (widget == null || state == null) {
				continue;
			}

			boolean changed = false;

			/*
			 * Restore a field only when it still equals Chat XL's last-applied value.
			 */
			if (state.fontIdCaptured
					&& widget.getFontId()
					== state.appliedFontId
					&& widget.getFontId()
					!= state.nativeFontId) {
				widget.setFontId(state.nativeFontId);
				changed = true;
			}

			if (state.lineHeightCaptured
					&& widget.getLineHeight()
					== state.appliedLineHeight
					&& widget.getLineHeight()
					!= state.nativeLineHeight) {
				widget.setLineHeight(state.nativeLineHeight);
				changed = true;
			}

			if (state.yTextAlignmentCaptured
					&& widget.getYTextAlignment()
					== state.appliedYTextAlignment
					&& widget.getYTextAlignment()
					!= state.nativeYTextAlignment) {
				widget.setYTextAlignment(state.nativeYTextAlignment);
				changed = true;
			}

			if (state.textCaptured
					&& sameText(widget.getText(), state.appliedText)
					&& !sameText(widget.getText(), state.nativeText)) {
				widget.setText(state.nativeText);
				changed = true;
			}

			if (state.originalXCaptured
					&& widget.getOriginalX()
					== state.appliedOriginalX
					&& widget.getOriginalX()
					!= state.nativeOriginalX) {
				widget.setOriginalX(state.nativeOriginalX);
				changed = true;
			}

			if (state.originalYCaptured
					&& widget.getOriginalY()
					== state.appliedOriginalY
					&& widget.getOriginalY()
					!= state.nativeOriginalY) {
				widget.setOriginalY(state.nativeOriginalY);
				changed = true;
			}

			if (state.relativeYCaptured
					&& widget.getRelativeY()
					== state.appliedRelativeY
					&& widget.getRelativeY()
					!= state.nativeRelativeY) {
				widget.setRelativeY(state.nativeRelativeY);
				changed = true;
			}

			if (state.originalWidthCaptured
					&& widget.getOriginalWidth()
					== state.appliedOriginalWidth
					&& widget.getOriginalWidth()
					!= state.nativeOriginalWidth) {
				widget.setOriginalWidth(state.nativeOriginalWidth);
				changed = true;
			}

			if (state.originalHeightCaptured
					&& widget.getOriginalHeight()
					== state.appliedOriginalHeight
					&& widget.getOriginalHeight()
					!= state.nativeOriginalHeight) {
				widget.setOriginalHeight(state.nativeOriginalHeight);
				changed = true;
			}

			if (changed) {
				widget.revalidate();
			}
		}

		nativeWidgetStates.clear();
	}

	public void reset() {
		pending = null;
		pendingFontProfile = null;
		pendingYOffsets.clear();
		rowIndexes.clear();
	}

	/*
	 * Native and last-applied presentation values captured per field
	 * for one Widget identity.
	 */
	private static final class NativeWidgetState {
		private boolean fontIdCaptured;
		private int nativeFontId;
		private int appliedFontId;

		private boolean lineHeightCaptured;
		private int nativeLineHeight;
		private int appliedLineHeight;

		private boolean yTextAlignmentCaptured;
		private int nativeYTextAlignment;
		private int appliedYTextAlignment;

		private boolean textCaptured;
		private String nativeText;
		private String appliedText;

		private boolean originalXCaptured;
		private int nativeOriginalX;
		private int appliedOriginalX;

		private boolean originalYCaptured;
		private int nativeOriginalY;
		private int appliedOriginalY;

		private boolean relativeYCaptured;
		private int nativeRelativeY;
		private int appliedRelativeY;

		private boolean originalWidthCaptured;
		private int nativeOriginalWidth;
		private int appliedOriginalWidth;

		private boolean originalHeightCaptured;
		private int nativeOriginalHeight;
		private int appliedOriginalHeight;
	}

	/*
	 * Immutable configured font/profile pair.
	 */
	private static final class ActiveFontState {
		private final ChatFont chatFont;
		private final ChatFontProfile fontProfile;

		private ActiveFontState(ChatFont chatFont, ChatFontProfile fontProfile) {
			this.chatFont = chatFont;
			this.fontProfile = fontProfile;
		}
	}

	/*
	 * One delayed component-specific Y correction.
	 *
	 * Text corrections retain expected semantic text.
	 * Sprite corrections retain an expected sprite ID.
	 *
	 * Exactly one guard is populated for each instance.
	 */
	private static final class PendingYOffset {
		private final String expectedSemanticText;
		private final int expectedSpriteId;
		private final int yOffset;

		private PendingYOffset(String expectedSemanticText, int expectedSpriteId, int yOffset) {
			this.expectedSemanticText = expectedSemanticText;
			this.expectedSpriteId = expectedSpriteId;
			this.yOffset = yOffset;
		}

		private static PendingYOffset forText(String expectedSemanticText, int yOffset) {
			return new PendingYOffset(expectedSemanticText, -1, yOffset);
		}

		private static PendingYOffset forSprite(int expectedSpriteId, int yOffset) {
			return new PendingYOffset(null, expectedSpriteId, yOffset);
		}

		private boolean matches(Widget widget, ChatTextNormalizer textNormalizer) {
			if (widget == null) {
				return false;
			}

			if (expectedSpriteId >= 0) {
				return widget.getSpriteId() == expectedSpriteId;
			}

			if (expectedSemanticText == null) {
				return false;
			}

			final String currentSemanticText = textNormalizer.normalizeSemantic(widget.getText());
			return currentSemanticText != null && currentSemanticText.equalsIgnoreCase(expectedSemanticText);
		}
	}

	enum Surface {
		CHATBOX,
		SPLIT_PRIVATE
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.config.ChatFont;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.fonts.ChatFontProfile;
import com.bigboldchat.fonts.ChatFontRegistry;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;

/**
 * Measures chat text, wrapping, row allocation, and presentation geometry.
 *
 * Produces ConstructionMeasurement values consumed by FontLayoutService.
 * This service does not mutate widgets or script stacks.
 */
public final class FontMeasurementService {
	static final int GAME_BODY_SCRIPT = 199;
	static final int CHAT_BODY_SCRIPT = 203;
	static final int CHANNEL_BODY_SCRIPT = 4483;

	/*
	 * Native Script 4483 rank-icon geometry:
	 *      [channel] +1px [icon] +1px [username]:
	 */
	private static final int RANK_ICON_GAP = 1;

	/*
	 * Native OS separation between:
	 *      [username] -> [message body]
	 */
	private static final int BODY_GAP = 3;

	/*
	 * Separation between text and scrollbar.
	 */
	private static final int SCROLLBAR_PADDING = 3;

	private final Client client;
	private final ChatTextNormalizer textNormalizer;

	// Optional performance instrumentation; null when disabled.
	private final PerformanceMetrics performanceMetrics;

	/*
	 * Cache resolved fonts for the current plugin session.
	 * Failed resolutions are retried on the next request.
	 */
	private final Map<Integer, FontTypeFace> fontCache = new HashMap<>();

	public FontMeasurementService(Client client) {
		this(client, new ChatTextNormalizer(), null);
	}

	public FontMeasurementService(Client client, PerformanceMetrics performanceMetrics) {
		this(client, new ChatTextNormalizer(performanceMetrics), performanceMetrics);
	}

	public FontMeasurementService(
			Client client,
			ChatTextNormalizer textNormalizer,
			PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.textNormalizer = textNormalizer != null
				? textNormalizer
				: new ChatTextNormalizer(performanceMetrics);
		this.performanceMetrics = performanceMetrics;
	}

	boolean supportsScript(int scriptId) {
		return scriptId == GAME_BODY_SCRIPT || scriptId == CHAT_BODY_SCRIPT || scriptId == CHANNEL_BODY_SCRIPT;
	}

	ConstructionMeasurement measure(int scriptId, ChatFont selectedChatFont, ChatFontProfile fontProfile) {
		if (!supportsScript(scriptId) || selectedChatFont == null || fontProfile == null) {
			return null;
		}

		final Object[] objectStack = client.getObjectStack();
		final int objectStackSize = client.getObjectStackSize();

		final int bodyIndex = findBodyIndex(objectStack, objectStackSize);
		if (bodyIndex < 0) {
			return null;
		}

		final String rawBody = (String) objectStack[bodyIndex];
		final String semanticBody = textNormalizer.normalizeSemantic(rawBody);
		if (semanticBody == null) {
			return null;
		}

		final String visibleRawBodyText = textNormalizer.renderText(rawBody);
		final String selectedRawBodyText = FontGlyphCorrections.apply(selectedChatFont, visibleRawBodyText);

		// Preserve inline images while measuring wrapping.
		final String measurementBody = textNormalizer.measureSemantic(rawBody);
		final String selectedMeasurementBody = textNormalizer.measureSemantic(selectedRawBodyText);
		if (measurementBody == null || selectedMeasurementBody == null) {
			return null;
		}

		final int[] intStack = client.getIntStack();
		final int intStackSize = client.getIntStackSize();
		if (intStack == null || intStackSize < 11 || intStackSize > intStack.length) {
			return null;
		}

		/*
		 * Common trailing Script 199 / 203 / 4483 construction payload:
		 *
		 * [0]  row / order
		 * [1]  line widget
		 * [2]  parent widget
		 * [3]  right boundary
		 * [4]  left boundary
		 * [5]  vertical / line-height construction input
		 * [6]  row Y
		 * [7]  unknown - preserve native
		 * [8]  sender / prefix width
		 * [9]  color
		 * [10] shadow
		 */
		final int rowValueIndex = intStackSize - 11;
		final int lineWidgetIndex = intStackSize - 10;
		final int parentWidgetIndex = intStackSize - 9;
		final int rightBoundaryIndex = intStackSize - 8;
		final int leftBoundaryIndex = intStackSize - 7;
		final int verticalValueIndex = intStackSize - 6;
		final int rowYIndex = intStackSize - 5;
		final int argument7Index = intStackSize - 4;
		final int senderWidthIndex = intStackSize - 3;
		final int colorIndex = intStackSize - 2;
		final int shadowIndex = intStackSize - 1;
		final int lineWidgetId = intStack[lineWidgetIndex];
		final int parentWidgetId = intStack[parentWidgetIndex];
		final int rightBoundary = intStack[rightBoundaryIndex];
		final int leftBoundary = intStack[leftBoundaryIndex];
		final int nativeLineHeight = intStack[verticalValueIndex];
		final int nativeRowY = intStack[rowYIndex];
		final int nativeArgument7 = intStack[argument7Index];
		final int nativeSenderWidth = intStack[senderWidthIndex];

		if (nativeLineHeight <= 0) {
			return null;
		}

		final Widget lineWidget = client.getWidget(lineWidgetId);
		if (lineWidget == null) {
			return null;
		}

		final FontTypeFace nativeFont = resolveFont(FontID.PLAIN_12);
		final FontTypeFace selectedFont = resolveFont(selectedChatFont.getFontId());
		final ChatFontProfile nativeFontProfile = ChatFontRegistry.get(ChatFont.PLAIN_12);
		if (nativeFont == null || selectedFont == null || nativeFontProfile == null) {
			return null;
		}

		final List<String> rawPrefixComponents = scriptId == GAME_BODY_SCRIPT
				? new ArrayList<>()
				: findPrefixComponents(objectStack, bodyIndex);

		/*
		 * Script 199 is the ordinary prefix-less GAME / system-message
		 * constructor.
		 *
		 * Script 203 requires a textual prefix.
		 *
		 * Script 4483 can legitimately provide empty title / sender
		 * components for Clan / Guest Clan system messages.
		 */
		if (scriptId == CHAT_BODY_SCRIPT && rawPrefixComponents.isEmpty()) {
			return null;
		}

		final int lineX = lineWidget.getOriginalX();

		int nativePrefixWidth = 0;
		int selectedPrefixLayoutWidth = 0;

		ChannelPrefixLayout nativeChannelLayout = null;
		ChannelPrefixLayout selectedChannelLayout = null;

		int nativeBodyX;
		int selectedBodyX;

		/*
		 * Script 203 keeps its native/raw prefix for correlation while the
		 * selected presentation may use a separately spaced raw prefix.
		 *
		 * This is primarily used by Friends Chat, where the rank icon is inline
		 * markup inside the same prefix widget as the channel name and username.
		 */
		String selectedRawPrefixText = null;

		if (scriptId == GAME_BODY_SCRIPT) {
			/*
			 * Script 199 is prefix-less and uses the full construction span.
			 * Preserve its native horizontal geometry.
			 */
			nativeBodyX = leftBoundary;
			selectedBodyX = leftBoundary;
		} else if (scriptId == CHAT_BODY_SCRIPT) {
			final String rawPrefix = rawPrefixComponents.get(rawPrefixComponents.size() - 1);

			// Measure native geometry from the unmodified prefix.
			nativePrefixWidth = nativeFont.getTextWidth(normalizeRawForMeasurement(rawPrefix));

			/*
			 * Keep the raw Friends Chat prefix for correlation and build a separate
			 * rendered prefix with configured inline-icon spacing.
			 */
			selectedRawPrefixText = isFriendsChatPrefix(rawPrefix)
					? applyInlineIconUsernameSpacing(rawPrefix, fontProfile.getFriendsChatPlayerIconSpacing(), '\u00A0')
					: rawPrefix;

			selectedRawPrefixText = FontGlyphCorrections.apply(selectedChatFont, selectedRawPrefixText);

			selectedPrefixLayoutWidth = selectedFont.getTextWidth(normalizeRawForMeasurement(selectedRawPrefixText));

			nativeBodyX = lineX + nativePrefixWidth + BODY_GAP;
			selectedBodyX = lineX + selectedPrefixLayoutWidth + BODY_GAP;
		} else {
			nativeChannelLayout = measureChannelPrefixLayout(nativeFont, rawPrefixComponents, intStack, intStackSize,
					lineX, null, 0, 0, nativeFontProfile.getAccountBuildIconPadding(), 0);

			selectedChannelLayout = measureChannelPrefixLayout(selectedFont, rawPrefixComponents, intStack, intStackSize,
					lineX, selectedChatFont, fontProfile.getRankIconRightAdjustment(), fontProfile.getRankIconSizeAdjustment(),
					fontProfile.getAccountBuildIconPadding(), fontProfile.getChannelAccountBuildIconSpacing());

			if (nativeChannelLayout == null || selectedChannelLayout == null) {
				return null;
			}

			nativeBodyX = nativeChannelLayout.bodyX;
			selectedBodyX = selectedChannelLayout.bodyX;
		}

		final boolean splitPrivate = isSplitPrivate(parentWidgetId);
		final int rightPadding = splitPrivate
				? 0
				: SCROLLBAR_PADDING;
		final int selectedRightBoundary = splitPrivate
				? splitPrivateRightBoundary(leftBoundary, rightBoundary)
				: rightBoundary;
		final int nativeBodyWidth = rightBoundary - nativeBodyX;
		final int selectedBodyWidth = selectedRightBoundary - selectedBodyX - rightPadding;
		if (nativeBodyWidth <= 0 || selectedBodyWidth <= 0) {
			return null;
		}

		final int nativeLines = calculateWrappedLineCount(nativeFont, measurementBody, nativeBodyWidth);
		final int selectedLines = calculateWrappedLineCount(selectedFont, selectedMeasurementBody, selectedBodyWidth);
		if (nativeLines <= 0 || selectedLines <= 0) {
			return null;
		}

		// Apply the selected profile's line-height adjustment.
		final int lineHeightAdjustment = fontProfile.getLineHeightAdjustment();
		final int selectedLineHeight = Math.max(1, nativeLineHeight + lineHeightAdjustment);

		final int rowYOffset = fontProfile.getRowYOffset();

		// Apply PRIVATE_CHAT_GAP to Split Private's bottom-relative row Y.
		final int privateChatGap = isSplitPrivate(parentWidgetId)
				? fontProfile.getPrivateChatGap()
				: 0;

		final int selectedRowY = nativeRowY + rowYOffset + privateChatGap;

		// Compensate construction height for native and selected wrapped-line counts.
		final int desiredHeight = selectedLines * selectedLineHeight;
		final int injectedValue = ceilDiv(desiredHeight, nativeLines);
		if (injectedValue <= 0) {
			return null;
		}

		final int allocatedHeight = nativeLines * injectedValue;
		final ConstructionMeasurement measurement = new ConstructionMeasurement();

		measurement.scriptId = scriptId;
		measurement.semanticBody = semanticBody;
		measurement.selectedRawBodyText = selectedRawBodyText;
		measurement.selectedChatFont = selectedChatFont;
		measurement.selectedFontId = selectedChatFont.getFontId();
		measurement.rawPrefixComponents = new ArrayList<>(rawPrefixComponents);
		// Script 203 keeps rendered raw prefix separately from native raw components used for correlation.
		measurement.selectedRawPrefixText = selectedRawPrefixText;
		measurement.rowValueIndex = rowValueIndex;
		measurement.verticalValueIndex = verticalValueIndex;
		measurement.rowYIndex = rowYIndex;
		measurement.argument7Index = argument7Index;
		measurement.senderWidthIndex = senderWidthIndex;
		measurement.lineWidgetId = lineWidgetId;
		measurement.parentWidgetId = parentWidgetId;
		measurement.leftBoundary = leftBoundary;
		measurement.rightBoundary = rightBoundary;
		measurement.lineX = lineX;
		measurement.nativeLineHeight = nativeLineHeight;
		measurement.lineHeightAdjustment = lineHeightAdjustment;
		measurement.selectedLineHeight = selectedLineHeight;
		measurement.nativeRowY = nativeRowY;
		measurement.rowYOffset = rowYOffset;
		measurement.selectedRowY = selectedRowY;
		measurement.channelTextYOffset = fontProfile.getChannelTextYOffset();
		measurement.rankIconRightAdjustment = fontProfile.getRankIconRightAdjustment();
		measurement.rankIconSizeAdjustment = fontProfile.getRankIconSizeAdjustment();
		measurement.rankIconYOffset = fontProfile.getChannelRankIconYOffset();
		measurement.accountBuildIconPadding = fontProfile.getAccountBuildIconPadding();
		measurement.nativeArgument7 = nativeArgument7;
		measurement.nativeSenderWidth = nativeSenderWidth;
		measurement.nativeColor = intStack[colorIndex];
		measurement.nativeShadow = intStack[shadowIndex];
		measurement.nativePrefixWidth = nativePrefixWidth;
		measurement.selectedPrefixLayoutWidth = selectedPrefixLayoutWidth;
		measurement.nativeChannelLayout = nativeChannelLayout;
		measurement.selectedChannelLayout = selectedChannelLayout;
		measurement.nativeBodyX = nativeBodyX;
		measurement.nativeBodyWidth = nativeBodyWidth;
		measurement.selectedBodyX = selectedBodyX;
		measurement.selectedBodyWidth = selectedBodyWidth;
		measurement.nativeLines = nativeLines;
		measurement.selectedLines = selectedLines;
		measurement.desiredHeight = desiredHeight;
		measurement.injectedValue = injectedValue;
		measurement.allocatedHeight = allocatedHeight;

		return measurement;
	}

	/**
	 * ================================================================
	 * PRIVATE CHAT
	 * ================================================================
	 */
	private boolean isSplitPrivate(int parentWidgetId) {
		return WidgetUtil.componentToInterface(parentWidgetId) == InterfaceID.PM_CHAT;
	}

	private int splitPrivateRightBoundary(int leftBoundary, int nativeRightBoundary) {
		final Widget pmHost = activeSplitPrivateHost();
		if (pmHost == null || pmHost.getWidth() <= 0) {
			return nativeRightBoundary;
		}

		/*
		 * REBUILDPMBOX continues to expose RuneScape's native construction
		 * boundary even when ChatXL has constrained the movable PM host. Measure
		 * selected wrapping against the host's effective width while preserving
		 * the native boundary above for native-line compensation and correlation.
		 */
		return leftBoundary + pmHost.getWidth();
	}

	private Widget activeSplitPrivateHost() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.PM_CONTAINER);
		}
		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return client.getWidget(InterfaceID.ToplevelPreEoc.PM_CONTAINER);
		}
		return null;
	}

	/**
	 * ================================================================
	 * CHANNEL / RANK-ICON MEASUREMENT
	 * ================================================================
	 */
	private ChannelPrefixLayout measureChannelPrefixLayout(FontTypeFace font, List<String> rawPrefixComponents,
			int[] intStack, int intStackSize, int lineX, ChatFont glyphFont, int rankIconRightAdjustment,
			int rankIconSizeAdjustment, int accountBuildIconPadding, int inlineIconUsernameSpacing) {
		if (font == null || rawPrefixComponents == null || intStack == null) {
			return null;
		}

		final ChannelPrefixLayout layout = new ChannelPrefixLayout();

		layout.titleX = lineX;

		final String rawTitleText = rawPrefixComponents.size() > 0
				? rawPrefixComponents.get(0)
				: "";

		layout.titleText = textNormalizer.normalizeSemantic(rawTitleText);

		layout.renderedTitleText = FontGlyphCorrections.apply(glyphFont, rawTitleText);

		final String rawSenderText = rawPrefixComponents.size() > 1
				? rawPrefixComponents.get(1)
				: "";

		/*
		 * Preserve the native sender semantic for correlation.
		 */
		layout.senderText = textNormalizer.normalizeSemantic(rawSenderText);

		/*
		 * The rendered sender may contain additional visible spacing after the
		 * final inline account/build icon.
		 *
		 * Example:
		 *
		 *     native:   <img=2>Username:
		 *     selected: <img=2> Username:
		 */
		layout.renderedSenderText = applyInlineIconUsernameSpacing(rawSenderText, inlineIconUsernameSpacing, ' ');

		layout.renderedSenderText = FontGlyphCorrections.apply(glyphFont, layout.renderedSenderText);

		if (layout.titleText == null) {
			layout.titleText = "";
		}

		if (layout.senderText == null) {
			layout.senderText = "";
		}

		layout.hasTitle = !layout.titleText.isEmpty();
		layout.hasSender = !layout.senderText.isEmpty();

		if (layout.hasTitle) {
			layout.titleWidth = font.getTextWidth(normalizeRawForMeasurement(layout.renderedTitleText));
		}

		if (layout.hasSender) {
			layout.senderWidth = font.getTextWidth(normalizeRawForMeasurement(layout.renderedSenderText));
		}

		/*
		 * Read optional rank sprite ID, width, and height
		 * immediately before the common Script-4483 payload.
		 */
		final int commonPayloadStart = intStackSize - 11;
		if (layout.hasSender && commonPayloadStart >= 3) {
			final int spriteIdCandidate = intStack[commonPayloadStart - 3];
			final int widthCandidate = intStack[commonPayloadStart - 2];
			final int heightCandidate = intStack[commonPayloadStart - 1];
			if (spriteIdCandidate >= 0
					&& widthCandidate > 0
					&& widthCandidate <= 32
					&& heightCandidate > 0
					&& heightCandidate <= 32) {
				layout.rankIconSpriteId = spriteIdCandidate;
				layout.rankIconWidth = Math.max(1, widthCandidate + rankIconSizeAdjustment);
				layout.rankIconHeight = Math.max(1, heightCandidate + rankIconSizeAdjustment);
			}
		}

		/*
		 * Inline account/build icons are measured as part of sender text.
		 *
		 * CHANNEL_ACCOUNT_BUILD_ICON_SPACING controls icon-to-name spacing.
		 * ACCOUNT_BUILD_ICON_PADDING reserves additional sender layout width.
		 */
		if (layout.hasSender && hasAccountBuildIcon(rawSenderText)) {
			layout.senderWidth += accountBuildIconPadding;
		}

		int cursor = lineX;

		if (layout.hasTitle) {
			cursor += layout.titleWidth;
		}

		if (layout.hasSender) {
			if (layout.rankIconWidth > 0) {
				/*
				 * Native:
				 *
				 * title -> 1px -> icon -> 1px -> sender
				 */
				if (layout.hasTitle) {
					cursor += RANK_ICON_GAP;
				}

				layout.rankIconX = cursor;
				cursor += layout.rankIconWidth;
				cursor += RANK_ICON_GAP;

				/*
				 * Enforce minimum spacing after the final inline image before the username.
				 *
				 * The caller supplies the spacing character. Existing whitespace counts
				 * toward the minimum, and consecutive inline images are not separated.
				 */
				cursor += rankIconRightAdjustment;
			} else if (layout.hasTitle) {
				cursor += BODY_GAP;
			}

			layout.senderX = cursor;
			cursor += layout.senderWidth;
			cursor += BODY_GAP;
		} else if (layout.hasTitle) {
			cursor += BODY_GAP; // Title-only Clan / Guest Clan system message.
		}

		layout.bodyX = cursor; // If both title and sender are empty, the body naturally begins at lineX.
		return layout;
	}

	/**
	 * ================================================================
	 * FONT RESOLUTION
	 * ================================================================
	 */

	private FontTypeFace resolveFont(int fontId) {
		final FontTypeFace cachedFont = fontCache.get(fontId);
		if (cachedFont != null) {
			if (performanceMetrics != null) {
				performanceMetrics.recordFontCacheHit();
			}

			return cachedFont;
		}

		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		try {
			final Widget probe = client.getWidget(InterfaceID.Chatbox.INPUT);
			if (probe == null) {
				return null;
			}

			final int originalFontId = probe.getFontId();
			final FontTypeFace resolvedFont;

			try {
				probe.setFontId(fontId);

				resolvedFont = probe.getFont();
			} finally {
				probe.setFontId(originalFontId);
			}

			if (resolvedFont != null) {
				fontCache.put(fontId, resolvedFont);
			}

			return resolvedFont;
		} finally {
			if (performanceMetrics != null && performanceMetrics.isEnabled()) {
				performanceMetrics.recordFontCacheMiss(System.nanoTime() - started);
			}
		}
	}

	/**
	 * ================================================================
	 * OBJECT-STACK EXTRACTION
	 * ================================================================
	 */
	private int findBodyIndex(Object[] stack, int size) {
		if (stack == null || size <= 0) {
			return -1;
		}

		final int safeSize = Math.min(size, stack.length);
		for (int i = safeSize - 1; i >= 0; i--) {
			if (stack[i] instanceof String && !((String) stack[i]).isEmpty()) {
				return i;
			}
		}

		return -1;
	}

	private List<String> findPrefixComponents(Object[] stack, int bodyIndex) {
		final List<String> result = new ArrayList<>();
		if (stack == null || bodyIndex < 0) {
			return result;
		}

		final int safeSize = Math.min(bodyIndex, stack.length);
		for (int i = 0; i < safeSize; i++) {
			final Object value = stack[i];
			if (value instanceof String) {
				result.add((String) value);
			}
		}

		return result;
	}

	private boolean hasAccountBuildIcon(String rawSenderText) {
		if (rawSenderText == null || rawSenderText.isEmpty()) {
			return false;
		}

		return rawSenderText.toLowerCase(Locale.ROOT).contains("<img=");
	}

	/*
	 * Add visible spacing between the final inline image tag and the
	 * username that follows it.
	 *
	 * The caller supplies the actual spacing character because Chat XL uses
	 * different spacing characters for the two supported inline-icon cases:
	 *
	 *     Friends Chat player/rank icon:
	 *         \u00A0  non-breaking space
	 *
	 *     Clan / Guest Clan account-build icon:
	 *         \u0020  normal space
	 *
	 * If multiple inline images occur before the username, only the final
	 * image receives the username gap:
	 *
	 *     <img=67><img=2>PlayerName:
	 *
	 * becomes:
	 *
	 *     <img=67><img=2> PlayerName:
	 *
	 * rather than inserting spacing between the consecutive icons.
	 *
	 * Existing whitespace immediately after the final image counts toward
	 * the configured minimum, which keeps repeated processing idempotent.
	 */
	private String applyInlineIconUsernameSpacing(String rawText, int spacing, char spacingCharacter) {
		if (rawText == null || rawText.isEmpty() || spacing <= 0) {
			return rawText;
		}

		final String lower = rawText.toLowerCase(Locale.ROOT);
		final int imageStart = lower.lastIndexOf("<img=");
		if (imageStart < 0) {
			return rawText;
		}

		final int imageEnd = rawText.indexOf('>', imageStart);
		if (imageEnd < 0 || imageEnd >= rawText.length() - 1) {
			return rawText;
		}

		int existingSpacing = 0;
		for (int i = imageEnd + 1; i < rawText.length(); i++) {
			final char ch = rawText.charAt(i);
			if (ch == ' ' || ch == '\u00A0' || ch == '\t') {
				existingSpacing++;
				continue;
			}

			break;
		}

		final int spacingToAdd = Math.max(0, spacing - existingSpacing);
		if (spacingToAdd == 0) {
			return rawText;
		}

		final StringBuilder gap = new StringBuilder(spacingToAdd);
		for (int i = 0; i < spacingToAdd; i++) {
			gap.append(spacingCharacter);
		}

		return rawText.substring(0, imageEnd + 1) + gap + rawText.substring(imageEnd + 1);
	}

	/*
	 * Script 203 is used by several chat surfaces.
	 *
	 * Friends Chat is identified by its bracketed combined prefix:
	 *
	 *     [Friends Chat] <img=rank>Username:
	 */
	private boolean isFriendsChatPrefix(String rawPrefix) {
		final String semanticPrefix = textNormalizer.normalizeSemantic(rawPrefix);
		if (semanticPrefix == null || semanticPrefix.length() < 3 || semanticPrefix.charAt(0) != '[') {
			return false;
		}

		final int closingBracket = semanticPrefix.indexOf(']');
		return closingBracket > 0 && closingBracket < semanticPrefix.length() - 1;
	}

	/**
	 * ================================================================
	 * TEXT NORMALIZATION
	 * ================================================================
	 */

	private String normalizeRawForMeasurement(String text) {
		if (text == null) {
			return "";
		}

		return text.replace('\u00A0', ' ');
	}

	/**
	 * ================================================================
	 * WRAPPING / HEIGHT
	 * ================================================================
	 */
	private int calculateWrappedLineCount(FontTypeFace font, String text, int maxWidth) {
		if (font == null || maxWidth <= 0 || text == null || text.isEmpty()) {
			return 1;
		}

		final String normalized = text
				.replace("\r\n", "\n")
				.replace('\r', '\n');
		final String[] explicitLines = normalized.split("\n", -1);
		int totalLines = 0;

		for (String explicitLine : explicitLines) {
			totalLines += calculateSingleParagraphLines(font, explicitLine, maxWidth);
		}

		return Math.max(1, totalLines);
	}

	int calculateSingleParagraphLines(FontTypeFace font, String text, int maxWidth) {
		if (text == null || text.isEmpty()) {
			return 1;
		}

		if (font.getTextWidth(text) <= maxWidth) {
			return 1;
		}

		final String trimmed = text.trim();
		if (trimmed.isEmpty()) {
			return 1;
		}

		final String[] words = trimmed.split("\\s+");
		int lines = 1;
		String currentLine = "";

		for (String word : words) {
			if (word.isEmpty()) {
				continue;
			}

			/*
			 * Don't hard-wrap one uninterrupted token character by character.
			 * This applies uniformly to letters, digits, punctuation, and symbols.
			 */
			if (font.getTextWidth(word) > maxWidth) {
				if (!currentLine.isEmpty()) {
					lines++;
				}

				currentLine = word;
				continue;
			}

			if (currentLine.isEmpty()) {
				currentLine = word;
				continue;
			}

			final String candidate = currentLine + " " + word;
			if (font.getTextWidth(candidate) <= maxWidth) {
				currentLine = candidate;
			} else {
				lines++;
				currentLine = word;
			}
		}

		return Math.max(1, lines);
	}

	private int ceilDiv(int numerator, int denominator) {
		if (denominator <= 0) {
			return numerator;
		}

		return (numerator + denominator - 1) / denominator;
	}

	/**
	 * ================================================================
	 * RESULT TYPES
	 * ================================================================
	 */
	static final class ChannelPrefixLayout {
		String titleText = ""; // Native semantic title used for correlation.
		String renderedTitleText = ""; // Exact title text rendered after correlation.
		String senderText = ""; // Native semantic sender used for correlation.
		String renderedSenderText = ""; // Exact selected raw sender markup rendered after correlation.

		boolean hasTitle;
		boolean hasSender;

		int titleX;
		int titleWidth;
		int rankIconSpriteId = -1;
		int rankIconX = -1;
		int rankIconWidth;
		int rankIconHeight;
		int senderX;
		int senderWidth;
		int bodyX;
	}

	static final class ConstructionMeasurement {
		int scriptId;

		String semanticBody; // Native semantic body used for correlation.
		String selectedRawBodyText; // Exact selected raw body rendered after correlation.

		ChatFont selectedChatFont;
		int selectedFontId;

		List<String> rawPrefixComponents;
		String selectedRawPrefixText; // Exact selected raw Script-203 prefix rendered in POST.

		int rowValueIndex;
		int verticalValueIndex;
		int rowYIndex;
		int argument7Index;
		int senderWidthIndex;
		int lineWidgetId;
		int parentWidgetId;
		int leftBoundary;
		int rightBoundary;
		int lineX;
		int nativeLineHeight;
		int lineHeightAdjustment;
		int selectedLineHeight;
		int nativeRowY;
		int rowYOffset;
		int selectedRowY;
		int channelTextYOffset;
		int rankIconRightAdjustment;
		int rankIconSizeAdjustment;
		int rankIconYOffset;
		int accountBuildIconPadding;
		int nativeArgument7;
		int nativeSenderWidth;
		int nativeColor;
		int nativeShadow;
		int nativePrefixWidth;
		int selectedPrefixLayoutWidth;

		ChannelPrefixLayout nativeChannelLayout;
		ChannelPrefixLayout selectedChannelLayout;

		int nativeBodyX;
		int nativeBodyWidth;
		int selectedBodyX;
		int selectedBodyWidth;
		int nativeLines;
		int selectedLines;
		int desiredHeight;
		int injectedValue;
		int allocatedHeight;
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.Configurations;
import com.bigboldchat.config.ChatFont;
import com.bigboldchat.fonts.ChatFontProfile;
import com.bigboldchat.fonts.ChatFontRegistry;

import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetTextAlignment;

/**
 * Applies the selected font and geometry to the chat input widget.
 */
public final class InputFontService {
	private final Client client;
	private final Configurations config;
	private final BandState bandState = new BandState();

	private InputState inputState;

	public InputFontService(Client client, Configurations config) {
		this.client = client;
		this.config = config;
	}

	public void onScriptPostFired(ScriptPostFired event) {
		if (event == null) {
			return;
		}

		final int scriptId = event.getScriptId();
		if (scriptId == ScriptID.CHAT_TEXT_INPUT_REBUILD || scriptId == ScriptID.CHAT_PROMPT_INIT || scriptId == ScriptID.UPDATE_SCROLLBAR) {
			sync();
		}
	}

	public void sync() {
		final Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
		if (input == null) {
			return;
		}

		final Widget chatDisplay = client.getWidget(InterfaceID.Chatbox.CHATDISPLAY);
		final Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		final Widget scrollbar = client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR);
		final Widget[] separators = separatorChildren(chatDisplay);

		captureInput(input);
		captureBand(scrollArea, scrollbar, separators);

		final ChatFont configuredFont = config != null
				? config.inputFont()
				: null;
		final ChatFont selectedFont = configuredFont != null
				? configuredFont
				: ChatFont.PLAIN_12;
		final ChatFontProfile profile = ChatFontRegistry.get(selectedFont);
		final int targetHeight = Math.max(1, inputState.nativeHeight + profile.getLineHeightAdjustment() + profile.getInputHeightAdjustment());
		final int targetY = inputState.nativeY + profile.getInputYOffset();
		final String targetText = FontGlyphCorrections.apply(selectedFont, inputState.nativeText);

		applyInput(input, selectedFont, targetHeight, targetY, targetText);

		final int inputTopDelta = inputTopDelta(inputState, targetHeight, targetY);
		applyBand(scrollArea, scrollbar, inputTopDelta);
	}

	public void restoreNativePresentation() {
		final Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
		if (inputState != null && input == inputState.widget) {
			restoreInput(input);
		}

		final Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		final Widget scrollbar = client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR);
		restoreBand(scrollArea, scrollbar);

		inputState = null;
		bandState.clear();
	}

	private void applyInput(Widget input, ChatFont selectedFont, int targetHeight, int targetY, String targetText) {
		boolean layoutChanged = false;

		if (input.getFontId() != selectedFont.getFontId()) {
			input.setFontId(selectedFont.getFontId());
			layoutChanged = true;
		}

		if (input.getLineHeight() != 0) {
			input.setLineHeight(0);
			layoutChanged = true;
		}

		if (input.getOriginalHeight() != targetHeight) {
			input.setOriginalHeight(targetHeight);
			layoutChanged = true;
		}

		if (input.getOriginalY() != targetY) {
			input.setOriginalY(targetY);
			layoutChanged = true;
		}

		if (targetText != null && !targetText.equals(input.getText())) {
			input.setText(targetText);
		}

		final int targetAlignment = targetInputAlignment(input, selectedFont, targetText);
		if (input.getXTextAlignment() != targetAlignment) {
			input.setXTextAlignment(targetAlignment);
		}

		if (layoutChanged) {
			input.revalidate();
		}

		inputState.appliedFontId = selectedFont.getFontId();
		inputState.appliedLineHeight = 0;
		inputState.appliedHeight = targetHeight;
		inputState.appliedY = targetY;
		inputState.appliedXTextAlignment = targetAlignment;
		inputState.appliedText = targetText;
	}

	private int targetInputAlignment(Widget input, ChatFont selectedFont, String targetText) {
		final int nativeAlignment = inputState.nativeXTextAlignment;
		if (selectedFont == ChatFont.PLAIN_12
				|| nativeAlignment != WidgetTextAlignment.LEFT && nativeAlignment != WidgetTextAlignment.RIGHT
				|| targetText == null || input.getWidth() <= 0) {
			return nativeAlignment;
		}

		final FontTypeFace font = input.getFont();
		if (font == null) {
			return nativeAlignment;
		}

		return font.getTextWidth(targetText) > input.getWidth()
				? WidgetTextAlignment.RIGHT
				: WidgetTextAlignment.LEFT;
	}

	private void applyBand(Widget scrollArea, Widget scrollbar, int inputTopDelta) {
		if (scrollArea != null && bandState.scrollArea == scrollArea) {
			final int targetHeight = Math.max(0, bandState.nativeScrollHeight - inputTopDelta);
			if (scrollArea.getOriginalHeight() != targetHeight) {
				scrollArea.setOriginalHeight(targetHeight);
				scrollArea.revalidate();
			}
			bandState.appliedScrollHeight = targetHeight;
		}

		if (scrollbar != null && bandState.scrollbar == scrollbar) {
			final int targetHeight = Math.max(0, bandState.nativeScrollbarHeight - inputTopDelta);
			if (scrollbar.getOriginalHeight() != targetHeight) {
				scrollbar.setOriginalHeight(targetHeight);
			}
			revalidateScrollbar(scrollbar);
			bandState.appliedScrollbarHeight = targetHeight;
		}

		for (SeparatorState separatorState : bandState.separators) {
			final Widget separator = separatorState.widget;
			final int targetY = offsetOriginalY(separatorState.nativeY, separatorState.yPositionMode, inputTopDelta);
			if (separator.getOriginalY() != targetY) {
				separator.setOriginalY(targetY);
				separator.revalidate();
			}
			separatorState.appliedY = targetY;
		}
	}

	private void restoreInput(Widget input) {
		boolean layoutChanged = false;

		if (input.getFontId() != inputState.nativeFontId) {
			input.setFontId(inputState.nativeFontId);
			layoutChanged = true;
		}
		if (input.getLineHeight() != inputState.nativeLineHeight) {
			input.setLineHeight(inputState.nativeLineHeight);
			layoutChanged = true;
		}
		if (input.getOriginalHeight() != inputState.nativeHeight) {
			input.setOriginalHeight(inputState.nativeHeight);
			layoutChanged = true;
		}
		if (input.getOriginalY() != inputState.nativeY) {
			input.setOriginalY(inputState.nativeY);
			layoutChanged = true;
		}
		if (input.getXTextAlignment() != inputState.nativeXTextAlignment) {
			input.setXTextAlignment(inputState.nativeXTextAlignment);
		}
		if (inputState.nativeText != null && !inputState.nativeText.equals(input.getText())) {
			input.setText(inputState.nativeText);
		}
		if (layoutChanged) {
			input.revalidate();
		}
	}

	private void restoreBand(Widget scrollArea, Widget scrollbar) {
		if (scrollArea != null && scrollArea == bandState.scrollArea && scrollArea.getOriginalHeight() != bandState.nativeScrollHeight) {
			scrollArea.setOriginalHeight(bandState.nativeScrollHeight);
			scrollArea.revalidate();
		}

		if (scrollbar != null && scrollbar == bandState.scrollbar) {
			if (scrollbar.getOriginalHeight() != bandState.nativeScrollbarHeight) {
				scrollbar.setOriginalHeight(bandState.nativeScrollbarHeight);
			}
			revalidateScrollbar(scrollbar);
		}

		for (SeparatorState separatorState : bandState.separators) {
			final Widget separator = separatorState.widget;
			if (separator.getOriginalY() != separatorState.nativeY) {
				separator.setOriginalY(separatorState.nativeY);
				separator.revalidate();
			}
		}
	}

	private void captureInput(Widget input) {
		if (inputState == null || input != inputState.widget) {
			inputState = InputState.capture(input);
			return;
		}

		if (inputState.appliedFontId == null || input.getFontId() != inputState.appliedFontId) {
			inputState.nativeFontId = input.getFontId();
		}
		if (inputState.appliedLineHeight == null || input.getLineHeight() != inputState.appliedLineHeight) {
			inputState.nativeLineHeight = input.getLineHeight();
		}
		if (inputState.appliedHeight == null || input.getOriginalHeight() != inputState.appliedHeight) {
			inputState.nativeHeight = input.getOriginalHeight();
		}
		if (inputState.appliedY == null || input.getOriginalY() != inputState.appliedY) {
			inputState.nativeY = input.getOriginalY();
		}
		if (inputState.appliedXTextAlignment == null || input.getXTextAlignment() != inputState.appliedXTextAlignment) {
			inputState.nativeXTextAlignment = input.getXTextAlignment();
		}

		inputState.yPositionMode = input.getYPositionMode();

		final String currentText = input.getText();
		if (inputState.appliedText == null || !equals(currentText, inputState.appliedText)) {
			inputState.nativeText = currentText;
		}
	}

	private void captureBand(Widget scrollArea, Widget scrollbar, Widget[] separators) {
		if (scrollArea == null) {
			bandState.scrollArea = null;
			bandState.appliedScrollHeight = null;
		} else if (scrollArea != bandState.scrollArea) {
			bandState.scrollArea = scrollArea;
			bandState.nativeScrollHeight = scrollArea.getOriginalHeight();
			bandState.appliedScrollHeight = null;
		} else if (bandState.appliedScrollHeight == null || scrollArea.getOriginalHeight() != bandState.appliedScrollHeight) {
			bandState.nativeScrollHeight = scrollArea.getOriginalHeight();
		}

		if (scrollbar == null) {
			bandState.scrollbar = null;
			bandState.appliedScrollbarHeight = null;
		} else if (scrollbar != bandState.scrollbar) {
			bandState.scrollbar = scrollbar;
			bandState.nativeScrollbarHeight = scrollbar.getOriginalHeight();
			bandState.appliedScrollbarHeight = null;
		} else if (bandState.appliedScrollbarHeight == null || scrollbar.getOriginalHeight() != bandState.appliedScrollbarHeight) {
			bandState.nativeScrollbarHeight = scrollbar.getOriginalHeight();
		}

		final SeparatorState[] previousSeparators = bandState.separators;
		final SeparatorState[] nextSeparators = new SeparatorState[separators.length];
		for (int i = 0; i < separators.length; i++) {
			final Widget separator = separators[i];
			SeparatorState separatorState = findSeparatorState(previousSeparators, separator);
			if (separatorState == null) {
				separatorState = SeparatorState.capture(separator);
			} else {
				if (separatorState.appliedY == null || separator.getOriginalY() != separatorState.appliedY) {
					separatorState.nativeY = separator.getOriginalY();
				}
				separatorState.yPositionMode = separator.getYPositionMode();
			}
			nextSeparators[i] = separatorState;
		}
		bandState.separators = nextSeparators;
	}

	private static int inputTopDelta(InputState state, int targetHeight, int targetY) {
		final int heightDelta = targetHeight - state.nativeHeight;
		final int yDelta = targetY - state.nativeY;

		if (state.yPositionMode == WidgetPositionMode.ABSOLUTE_BOTTOM) {
			return -heightDelta - yDelta;
		}
		if (state.yPositionMode == WidgetPositionMode.ABSOLUTE_CENTER) {
			return -(heightDelta / 2) + yDelta;
		}
		return yDelta;
	}

	private static int offsetOriginalY(int originalY, int yPositionMode, int relativeDelta) {
		return yPositionMode == WidgetPositionMode.ABSOLUTE_BOTTOM
				? originalY - relativeDelta
				: originalY + relativeDelta;
	}

	private static void revalidateScrollbar(Widget scrollbar) {
		scrollbar.revalidate();
		scrollbar.revalidateScroll();

		final Widget[] children = scrollbar.getDynamicChildren();
		if (children == null) {
			return;
		}

		for (Widget child : children) {
			if (child != null) {
				child.revalidate();
			}
		}
	}

	private static Widget[] separatorChildren(Widget widget) {
		if (widget == null) {
			return new Widget[0];
		}

		final Widget[] children = widget.getDynamicChildren();
		if (children == null || children.length == 0) {
			return new Widget[0];
		}

		final Widget[] candidates = new Widget[21];
		int count = 0;
		if (children[0] != null) {
			candidates[count++] = children[0];
		}

		for (int i = 1; i <= 39 && i < children.length; i += 2) {
			if (children[i] != null) {
				candidates[count++] = children[i];
			}
		}

		final Widget[] separators = new Widget[count];
		System.arraycopy(candidates, 0, separators, 0, count);
		return separators;
	}

	private static SeparatorState findSeparatorState(SeparatorState[] states, Widget widget) {
		for (SeparatorState state : states) {
			if (state.widget == widget) {
				return state;
			}
		}
		return null;
	}

	private static boolean equals(String first, String second) {
		return first == null
				? second == null
				: first.equals(second);
	}

	private static final class InputState {
		private Widget widget;
		private int nativeFontId;
		private int nativeLineHeight;
		private int nativeHeight;
		private int nativeY;
		private int nativeXTextAlignment;
		private int yPositionMode;
		private String nativeText;
		private Integer appliedFontId;
		private Integer appliedLineHeight;
		private Integer appliedHeight;
		private Integer appliedY;
		private Integer appliedXTextAlignment;
		private String appliedText;

		private static InputState capture(Widget input) {
			final InputState state = new InputState();
			state.widget = input;
			state.nativeFontId = input.getFontId();
			state.nativeLineHeight = input.getLineHeight();
			state.nativeHeight = input.getOriginalHeight();
			state.nativeY = input.getOriginalY();
			state.nativeXTextAlignment = input.getXTextAlignment();
			state.yPositionMode = input.getYPositionMode();
			state.nativeText = input.getText();
			return state;
		}
	}

	private static final class SeparatorState {
		private Widget widget;
		private int nativeY;
		private int yPositionMode;
		private Integer appliedY;

		private static SeparatorState capture(Widget separator) {
			final SeparatorState state = new SeparatorState();
			state.widget = separator;
			state.nativeY = separator.getOriginalY();
			state.yPositionMode = separator.getYPositionMode();
			return state;
		}
	}

	private static final class BandState {
		private Widget scrollArea;
		private Widget scrollbar;
		private SeparatorState[] separators = new SeparatorState[0];
		private int nativeScrollHeight;
		private int nativeScrollbarHeight;
		private Integer appliedScrollHeight;
		private Integer appliedScrollbarHeight;

		private void clear() {
			scrollArea = null;
			scrollbar = null;
			separators = new SeparatorState[0];
			nativeScrollHeight = 0;
			nativeScrollbarHeight = 0;
			appliedScrollHeight = null;
			appliedScrollbarHeight = null;
		}
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.chat.FontLayoutService.Surface;
import com.bigboldchat.debug.PerformanceMetrics;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Persistent shallow row index for one chat surface.
 *
 * Indexes the root and immediate dynamic/static/nested children by RowKey,
 * supports local repair, and watches Chat XL-adjusted widgets for row changes.
 */
final class RowCorrelationIndex {
	private final Client client;
	private final Surface surface;
	private final PerformanceMetrics performanceMetrics;

	private Widget indexedRoot;

	private Map<RowKey, List<Widget>> widgetsByRow;
	private IdentityHashMap<Widget, RowKey> rowByWidget;

	private final IdentityHashMap<Widget, WatchedRowMove> watchedMoves = new IdentityHashMap<>();
	private final Map<RowKey, List<Widget>> watchedWidgetsByPreviousRow = new HashMap<>();

	RowCorrelationIndex(Client client, Surface surface, PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.surface = surface;
		this.performanceMetrics = performanceMetrics;
	}

	List<Widget> findRow(Widget lineWidget) {
		if (lineWidget == null || surface == null) {
			return Collections.emptyList();
		}

		final Widget root = surface == Surface.SPLIT_PRIVATE
				? client.getWidget(InterfaceID.PM_CHAT, 0)
				: client.getWidget(InterfaceID.Chatbox.SCROLLAREA);

		if (root == null) {
			clear();
			return Collections.emptyList();
		}

		final RowKey targetRow = RowKey.of(lineWidget);

		boolean rebuilt = false;
		boolean repaired = false;

		if (widgetsByRow == null || rowByWidget == null || indexedRoot != root) {
			build(root);
			rebuilt = true;
		} else {
			repaired |= repairWatchedWidgetsForRow(targetRow); // Repair watched widgets that returned to this row.

			final RowKey indexedAnchorRow = rowByWidget.get(lineWidget);
			if (indexedAnchorRow == null) {
				/*
				 * A new line-widget object appeared after the last index
				 * build. We cannot discover its sibling candidates without
				 * enumerating the surface once.
				 */
				build(root);
				rebuilt = true;
			} else if (!indexedAnchorRow.equals(targetRow)) {
				// Re-key the moved anchor row and its known siblings.
				repaired |= repairRow(indexedAnchorRow);
			}
		}

		if (!rebuilt) {
			/*
			 * Validate only the requested bucket. Outgoing recycled
			 * candidates are moved to their current row without touching
			 * unrelated rows or walking the complete surface.
			 */
			repaired |= repairRow(targetRow);
		}

		List<Widget> candidates = widgetsByRow.get(targetRow);

		/*
		 * The exact line widget must be present in its requested bucket.
		 * If not, local knowledge is insufficient and one complete build
		 * remains the conservative correctness fallback.
		 */
		if (!rebuilt && !containsIdentity(candidates, lineWidget)) {
			build(root);
			rebuilt = true;
			candidates = widgetsByRow.get(targetRow);
		}

		if (performanceMetrics != null) {
			if (rebuilt) {
				performanceMetrics.recordRowIndexBuild();
			} else if (repaired) {
				performanceMetrics.recordRowIndexRepair();
			} else {
				performanceMetrics.recordRowIndexReuse();
			}
		}

		return candidates != null
				? candidates
				: Collections.emptyList();
	}

	private boolean repairRow(RowKey indexedRow) {
		if (indexedRow == null || widgetsByRow == null || rowByWidget == null) {
			return false;
		}

		final List<Widget> indexedWidgets = widgetsByRow.get(indexedRow);
		if (indexedWidgets == null || indexedWidgets.isEmpty()) {
			return false;
		}

		final List<Widget> snapshot = new ArrayList<>(indexedWidgets);

		boolean repaired = false;

		for (Widget widget : snapshot) {
			if (widget == null) {
				continue;
			}

			recordRowWidgetExamined();

			final RowKey currentRow = RowKey.of(widget);
			final RowKey recordedRow = rowByWidget.get(widget);
			if (recordedRow == null) {
				/*
				 * This should not occur for a healthy index. Keep the
				 * reverse mapping internally consistent without a scan.
				 */
				rowByWidget.put(widget, currentRow);

				if (!indexedRow.equals(currentRow)) {
					removeWidgetFromRow(widget, indexedRow);
					addWidgetToRow(widget, currentRow);
					repaired = true;
				}

				continue;
			}

			if (!recordedRow.equals(currentRow)) {
				moveIndexedWidget(widget, recordedRow, currentRow);
				reconcileWatchedMoveAfterExternalGeometryChange(widget, currentRow);
				repaired = true;
			}
		}

		return repaired;
	}

	private boolean repairWatchedWidgetsForRow(RowKey requestedRow) {
		if (requestedRow == null || rowByWidget == null) {
			return false;
		}

		final List<Widget> watchedWidgets = watchedWidgetsByPreviousRow.get(requestedRow);
		if (watchedWidgets == null || watchedWidgets.isEmpty()) {
			return false;
		}

		final List<Widget> snapshot = new ArrayList<>(watchedWidgets);

		boolean repaired = false;

		for (Widget widget : snapshot) {
			if (widget == null) {
				continue;
			}

			final WatchedRowMove watchedMove = watchedMoves.get(widget);
			if (watchedMove == null || !requestedRow.equals(watchedMove.previousRow)) {
				removeWatchedMove(widget);
				continue;
			}

			final RowKey recordedRow = rowByWidget.get(widget);
			if (recordedRow == null) {
				removeWatchedMove(widget);
				continue;
			}

			recordRowWidgetExamined();

			final RowKey currentRow = RowKey.of(widget);
			if (!recordedRow.equals(currentRow)) {
				moveIndexedWidget(widget, recordedRow, currentRow);
				repaired = true;
			}

			// Stop watching once the widget leaves the Chat XL-adjusted row.
			if (!watchedMove.adjustedRow.equals(currentRow)) {
				removeWatchedMove(widget);
			}
		}

		return repaired;
	}

	void observeSurfaceWidget(Widget root, Widget widget) {
		if (root == null
				|| widget == null
				|| indexedRoot != root
				|| widgetsByRow == null
				|| rowByWidget == null) {
			return;
		}

		final RowKey currentRow = RowKey.of(widget);
		final RowKey recordedRow = rowByWidget.get(widget);
		if (recordedRow == null) {
			addWidgetToRow(widget, currentRow);
			rowByWidget.put(widget, currentRow);
			return;
		}

		if (!recordedRow.equals(currentRow)) {
			moveIndexedWidget(widget, recordedRow, currentRow);
			reconcileWatchedMoveAfterExternalGeometryChange(widget, currentRow);
		}
	}

	void onWidgetGeometryChangedByChatXl(Widget widget, int previousOriginalY, int previousRelativeY) {
		if (widget == null || rowByWidget == null) {
			return;
		}

		final RowKey previousRow = new RowKey(previousOriginalY, previousRelativeY);
		final RowKey recordedRow = rowByWidget.get(widget);
		if (recordedRow == null) {
			return;
		}

		final RowKey adjustedRow = RowKey.of(widget);
		if (!recordedRow.equals(adjustedRow)) {
			moveIndexedWidget(widget, recordedRow, adjustedRow);
		}

		if (!previousRow.equals(adjustedRow)) {
			watchMove(widget, previousRow, adjustedRow);
		}
	}

	private void moveIndexedWidget(Widget widget, RowKey oldRow, RowKey newRow) {
		if (widget == null || newRow == null || rowByWidget == null || widgetsByRow == null) {
			return;
		}

		if (oldRow != null) {
			removeWidgetFromRow(widget, oldRow);
		}

		addWidgetToRow(widget, newRow);
		rowByWidget.put(widget, newRow);
	}

	private void addWidgetToRow(Widget widget, RowKey row) {
		if (widget == null || row == null || widgetsByRow == null) {
			return;
		}

		final List<Widget> widgets = widgetsByRow.computeIfAbsent(row, ignored -> new ArrayList<>());
		if (!containsIdentity(widgets, widget)) {
			widgets.add(widget);
		}
	}

	private void removeWidgetFromRow(Widget widget, RowKey row) {
		if (widget == null || row == null || widgetsByRow == null) {
			return;
		}

		final List<Widget> widgets = widgetsByRow.get(row);
		if (widgets == null) {
			return;
		}

		removeIdentity(widgets, widget);

		if (widgets.isEmpty()) {
			widgetsByRow.remove(row);
		}
	}

	private void watchMove(Widget widget, RowKey previousRow, RowKey adjustedRow) {
		if (widget == null || previousRow == null || adjustedRow == null) {
			return;
		}

		removeWatchedMove(widget);
		watchedMoves.put(widget, new WatchedRowMove(previousRow, adjustedRow));

		final List<Widget> watchedWidgets = watchedWidgetsByPreviousRow.computeIfAbsent(
				previousRow, ignored -> new ArrayList<>());
		if (!containsIdentity(watchedWidgets, widget)) {
			watchedWidgets.add(widget);
		}
	}

	private void reconcileWatchedMoveAfterExternalGeometryChange(Widget widget, RowKey currentRow) {
		final WatchedRowMove watchedMove = watchedMoves.get(widget);
		if (watchedMove == null || currentRow == null) {
			return;
		}

		if (!watchedMove.adjustedRow.equals(currentRow)) {
			removeWatchedMove(widget);
		}
	}

	private void removeWatchedMove(Widget widget) {
		if (widget == null) {
			return;
		}

		final WatchedRowMove watchedMove = watchedMoves.remove(widget);
		if (watchedMove == null) {
			return;
		}

		final List<Widget> watchedWidgets = watchedWidgetsByPreviousRow.get(watchedMove.previousRow);
		if (watchedWidgets == null) {
			return;
		}

		removeIdentity(watchedWidgets, widget);

		if (watchedWidgets.isEmpty()) {
			watchedWidgetsByPreviousRow.remove(watchedMove.previousRow);
		}
	}

	private void build(Widget root) {
		indexedRoot = root;
		widgetsByRow = new HashMap<>();
		rowByWidget = new IdentityHashMap<>();

		indexWidget(root);
		indexWidgets(root.getDynamicChildren());
		indexWidgets(root.getStaticChildren());
		indexWidgets(root.getNestedChildren());
		pruneWatchedMovesAfterBuild();
	}

	private void indexWidgets(Widget[] widgets) {
		if (widgets == null) {
			return;
		}

		for (Widget widget : widgets) {
			indexWidget(widget);
		}
	}

	private void indexWidget(Widget widget) {
		if (widget == null) {
			return;
		}

		recordRowWidgetExamined();

		final RowKey row = RowKey.of(widget);
		addWidgetToRow(widget, row);
		rowByWidget.put(widget, row);
	}

	private void pruneWatchedMovesAfterBuild() {
		if (watchedMoves.isEmpty() || rowByWidget == null) {
			return;
		}

		final List<Widget> watchedWidgets = new ArrayList<>(watchedMoves.keySet());

		for (Widget widget : watchedWidgets) {
			final WatchedRowMove watchedMove = watchedMoves.get(widget);
			final RowKey indexedRow = rowByWidget.get(widget);
			if (watchedMove == null || indexedRow == null || !watchedMove.adjustedRow.equals(indexedRow)) {
				removeWatchedMove(widget);
			}
		}
	}

	private void clear() {
		indexedRoot = null;
		widgetsByRow = null;
		rowByWidget = null;

		watchedMoves.clear();
		watchedWidgetsByPreviousRow.clear();
	}

	private void recordRowWidgetExamined() {
		if (performanceMetrics != null) {
			performanceMetrics.recordWidgetsExamined(1);
		}
	}

	private boolean containsIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return false;
		}

		for (Widget widget : widgets) {
			if (widget == target) {
				return true;
			}
		}

		return false;
	}

	private void removeIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return;
		}

		for (int i = widgets.size() - 1; i >= 0; i--) {
			if (widgets.get(i) == target) {
				widgets.remove(i);
			}
		}
	}

	private static final class WatchedRowMove {
		private final RowKey previousRow;
		private final RowKey adjustedRow;

		private WatchedRowMove(RowKey previousRow, RowKey adjustedRow) {
			this.previousRow = previousRow;
			this.adjustedRow = adjustedRow;
		}
	}

	private static final class RowKey {
		private final int originalY;
		private final int relativeY;

		private RowKey(int originalY, int relativeY) {
			this.originalY = originalY;
			this.relativeY = relativeY;
		}

		private static RowKey of(Widget widget) {
			return new RowKey(widget.getOriginalY(), widget.getRelativeY());
		}

		@Override
		public boolean equals(Object other) {
			if (this == other) {
				return true;
			}

			if (!(other instanceof RowKey)) {
				return false;
			}

			final RowKey rowKey = (RowKey) other;
			return originalY == rowKey.originalY && relativeY == rowKey.relativeY;
		}

		@Override
		public int hashCode() {
			int result = originalY;
			result = 31 * result + relativeY;

			return result;
		}
	}
}

package com.bigboldchat.chatbox;

import com.bigboldchat.Configurations;
import com.bigboldchat.debug.PerformanceMetrics;

import net.runelite.api.Client;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.client.callback.ClientThread;

/**
 * Coalesces chatbox geometry commits and native chat rebuilds.
 */
public final class ChatRebuildCoordinator {
	private final Client client;
	private final ClientThread clientThread;
	private final Configurations config;
	private final ChatboxResizeService resizeService;
	private final PerformanceMetrics performanceMetrics;

	private volatile boolean active = true;
	private boolean commitQueued;
	private boolean boundsChanged;
	private boolean pendingWidthRefresh;
	private boolean pendingHeightRefresh;
	private boolean forceRefreshAfterCommit;
	private boolean forceRefreshTracksVisibility;
	private PerformanceMetrics.RefreshReason forceRefreshReason;
	private boolean refreshQueued;
	private boolean refreshWidthChanged;
	private boolean refreshHeightChanged;
	private boolean refreshForced;
	private boolean refreshTracksVisibility;
	private PerformanceMetrics.RefreshReason refreshReason;
	private ChatboxResizeService.ScrollBaseline refreshScrollBaseline;
	private boolean visibilityRefreshPending;
	private PerformanceMetrics.RefreshReason visibilityRefreshReason;
	private boolean refreshing;
	private int committedWidth;
	private int committedHeight;

	public ChatRebuildCoordinator(
			Client client,
			ClientThread clientThread,
			Configurations config,
			ChatboxResizeService resizeService,
			PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.resizeService = resizeService;
		this.performanceMetrics = performanceMetrics;
		this.committedWidth = config.chatboxWidth();
		this.committedHeight = config.chatboxHeight();
	}

	public void onStartup() {
		applyConfiguredSize(PerformanceMetrics.RefreshReason.STARTUP, true);
	}

	public void onLoggedIn() {
		applyConfiguredSize(PerformanceMetrics.RefreshReason.OTHER, true);
	}

	public void onConfiguredSizeChanged() {
		if (!active) {
			return;
		}

		queueCommit(false, false, false);
	}

	public void onButtonsChanged() {
		if (!active) {
			return;
		}

		queueCommit(true, false, false);
	}

	public void onCanvasSizeChanged() {
		if (!active) {
			return;
		}

		queueCommit(true, false, false);
	}

	public void onInterfaceChanged() {
		if (!active) {
			return;
		}

		queueCommit(true, false, false);
	}

	public void onLayoutChanged(ChatboxResizeService.ResizeResult result) {
		if (!active || refreshing || result == null || !result.isApplied()
				|| !result.isWidthChanged() && !result.isHeightChanged()) {
			return;
		}

		/*
		 * Script-driven layout changes apply geometry synchronously so the
		 * native relayout sees it. Reapply once after that script stack settles,
		 * then refresh presentation against the stable effective dimensions.
		 */
		queueCommit(true, result.isWidthChanged(), result.isHeightChanged());
	}

	public void refreshLiveGeometry(boolean widthChanged, boolean heightChanged) {
		if (!active || refreshing || resizeService == null || !widthChanged && !heightChanged) {
			return;
		}

		final ChatboxResizeService.ScrollBaseline scrollBaseline = resizeService.captureScrollBaseline();

		/*
		 * Live geometry is already authoritative. Rebuild retained rows only;
		 * sending this path through the geometry commit queue previously made
		 * ChatXL fight RuneScape's native relayout and caused visible oscillation.
		 * The same rebuild now serves chatbox and independently-sized split-PM
		 * width changes, so callers coalesce both reasons before reaching here.
		 */
		refreshing = true;
		try {
			if (performanceMetrics != null) {
				/*
				 * A single rebuild may satisfy both axes. Classify it as a width refresh
				 * when wrapping is involved, otherwise as a height-only refresh.
				 */
				final PerformanceMetrics.RefreshReason reason = widthChanged
						? PerformanceMetrics.RefreshReason.WIDTH_CHANGED
						: PerformanceMetrics.RefreshReason.HEIGHT_CHANGED;

				performanceMetrics.recordRefreshChat(reason);
			}

			client.refreshChat();
			resizeService.restoreRebuildScroll(scrollBaseline);
		} finally {
			refreshing = false;
		}
	}

	public void onScriptPostFired(ScriptPostFired event) {
		if (!active || event == null || event.getScriptId() != ChatboxResizeService.CHAT_VISIBILITY
				|| resizeService == null || resizeService.isChatHidden()) {
			return;
		}

		final PerformanceMetrics.RefreshReason reason;
		synchronized (this) {
			if (!visibilityRefreshPending) {
				return;
			}

			visibilityRefreshPending = false;
			reason = visibilityRefreshReason;
			visibilityRefreshReason = null;
		}

		queueForcedCommit(reason, false);
	}

	public synchronized void deactivate() {
		active = false;
		commitQueued = false;
		boundsChanged = false;
		pendingWidthRefresh = false;
		pendingHeightRefresh = false;
		forceRefreshAfterCommit = false;
		forceRefreshTracksVisibility = false;
		forceRefreshReason = null;
		refreshQueued = false;
		refreshWidthChanged = false;
		refreshHeightChanged = false;
		refreshForced = false;
		refreshTracksVisibility = false;
		refreshReason = null;
		refreshScrollBaseline = null;
		visibilityRefreshPending = false;
		visibilityRefreshReason = null;
	}

	private void applyConfiguredSize(PerformanceMetrics.RefreshReason reason, boolean trackVisibility) {
		if (!active || resizeService == null || config == null) {
			return;
		}

		resizeService.setChatboxButtonsHidden(config.hideChatboxButtons());

		final int width = config.chatboxWidth();
		final int height = config.chatboxHeight();
		final ChatboxResizeService.ScrollBaseline scrollBaseline = resizeService.captureScrollBaseline();
		final ChatboxResizeService.ResizeResult result = resizeService.applySize(width, height);
		if (result != null && result.isApplied()) {
			committedWidth = width;
			committedHeight = height;
		} else if (resizeService.getLayout() != ChatboxLayout.FIXED) {
			queueForcedCommit(reason, trackVisibility);
		}

		/*
		 * Retained rows need one native rebuild even when
		 * configured  geometry already matches the mounted chatbox.
		 */
		queueRefresh(
				result != null && result.isWidthChanged(),
				result != null && result.isHeightChanged(),
				true, reason, trackVisibility, scrollBaseline);
	}

	private synchronized void queueCommit(boolean boundsChanged, boolean widthRefresh, boolean heightRefresh) {
		if (!active) {
			return;
		}

		this.boundsChanged |= boundsChanged;
		pendingWidthRefresh |= widthRefresh;
		pendingHeightRefresh |= heightRefresh;
		if (commitQueued) {
			return;
		}

		commitQueued = true;
		clientThread.invokeLater(this::drainCommit);
	}

	private synchronized void queueForcedCommit(PerformanceMetrics.RefreshReason reason, boolean trackVisibility) {
		if (!active) {
			return;
		}

		boundsChanged = true;
		forceRefreshAfterCommit = true;
		forceRefreshTracksVisibility |= trackVisibility;
		if (reason != null) {
			forceRefreshReason = reason;
		}

		if (commitQueued) {
			return;
		}

		commitQueued = true;
		clientThread.invokeLater(this::drainCommit);
	}

	private void drainCommit() {
		final boolean reapplyBounds;
		final boolean widthRefresh;
		final boolean heightRefresh;
		final boolean forceRefresh;
		final boolean trackVisibility;
		final PerformanceMetrics.RefreshReason forcedReason;
		synchronized (this) {
			commitQueued = false;
			reapplyBounds = boundsChanged;
			widthRefresh = pendingWidthRefresh;
			heightRefresh = pendingHeightRefresh;
			forceRefresh = forceRefreshAfterCommit;
			trackVisibility = forceRefreshTracksVisibility;
			forcedReason = forceRefreshReason;
			boundsChanged = false;
			pendingWidthRefresh = false;
			pendingHeightRefresh = false;
		}

		if (!active || resizeService == null || config == null) {
			return;
		}

		resizeService.setChatboxButtonsHidden(config.hideChatboxButtons());

		final int width = config.chatboxWidth();
		final int height = config.chatboxHeight();
		final boolean widthChanged = width != committedWidth;
		final boolean heightChanged = height != committedHeight;
		if (!widthChanged
				&& !heightChanged
				&& !reapplyBounds
				&& !widthRefresh
				&& !heightRefresh
				&& !forceRefresh) {
			return;
		}

		final ChatboxResizeService.ScrollBaseline scrollBaseline = resizeService.captureScrollBaseline();
		final ChatboxResizeService.ResizeResult result = resizeService.applySize(width, height);
		if (result == null || !result.isApplied()) {
			if (resizeService.getLayout() == ChatboxLayout.FIXED) {
				clearForcedCommit();
			}
			return;
		}

		committedWidth = width;
		committedHeight = height;

		if (forceRefresh) {
			clearForcedCommit();
		}

		queueRefresh(
				widthRefresh || result.isWidthChanged(),
				heightRefresh || result.isHeightChanged(),
				forceRefresh, forcedReason, trackVisibility, scrollBaseline);
	}

	private synchronized void clearForcedCommit() {
		forceRefreshAfterCommit = false;
		forceRefreshTracksVisibility = false;
		forceRefreshReason = null;
	}

	private synchronized void queueRefresh(
			boolean widthChanged, boolean heightChanged, boolean forced, PerformanceMetrics.RefreshReason reason,
			boolean trackVisibility, ChatboxResizeService.ScrollBaseline scrollBaseline) {
		if (!active || (!forced && !widthChanged && !heightChanged)) {
			return;
		}

		refreshWidthChanged |= widthChanged;
		refreshHeightChanged |= heightChanged;
		refreshForced |= forced;
		refreshTracksVisibility |= trackVisibility;
		if (reason != null) {
			refreshReason = reason;
		}

		if (refreshScrollBaseline == null) {
			refreshScrollBaseline = scrollBaseline;
		}

		if (refreshQueued) {
			return;
		}

		refreshQueued = true;
		clientThread.invokeLater(this::drainRefresh);
	}

	private void drainRefresh() {
		final boolean widthChanged;
		final boolean heightChanged;
		final boolean forced;
		final boolean trackVisibility;
		final PerformanceMetrics.RefreshReason explicitReason;
		final ChatboxResizeService.ScrollBaseline scrollBaseline;
		synchronized (this) {
			refreshQueued = false;
			widthChanged = refreshWidthChanged;
			heightChanged = refreshHeightChanged;
			forced = refreshForced;
			trackVisibility = refreshTracksVisibility;
			explicitReason = refreshReason;
			scrollBaseline = refreshScrollBaseline;
			refreshWidthChanged = false;
			refreshHeightChanged = false;
			refreshForced = false;
			refreshTracksVisibility = false;
			refreshReason = null;
			refreshScrollBaseline = null;
		}

		if (!active || (!forced && !widthChanged && !heightChanged)) {
			return;
		}

		refreshing = true;
		try {
			if (performanceMetrics != null) {
				performanceMetrics.recordRefreshChat(resolveRefreshReason(widthChanged, heightChanged, explicitReason));
			}

			client.refreshChat();
			resizeService.restoreRebuildScroll(scrollBaseline);

			if (trackVisibility) {
				rememberVisibilityRefresh(explicitReason);
			}
		} finally {
			refreshing = false;
		}
	}

	private PerformanceMetrics.RefreshReason resolveRefreshReason(boolean widthChanged, boolean heightChanged,
			PerformanceMetrics.RefreshReason explicitReason) {
		if (explicitReason != null) {
			return explicitReason;
		}

		if (widthChanged) {
			return PerformanceMetrics.RefreshReason.WIDTH_CHANGED;
		}

		return heightChanged
				? PerformanceMetrics.RefreshReason.HEIGHT_CHANGED
				: PerformanceMetrics.RefreshReason.OTHER;
	}

	private synchronized void rememberVisibilityRefresh(PerformanceMetrics.RefreshReason reason) {
		if (resizeService == null || !resizeService.isChatHidden()) {
			visibilityRefreshPending = false;
			visibilityRefreshReason = null;
			return;
		}

		visibilityRefreshPending = true;
		visibilityRefreshReason = reason;
	}

}

package com.bigboldchat.chatbox;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;

/**
 * Owns resizable chatbox background and frame geometry.
 *
 * Opaque chat stretches the parchment while preserving its baked bevel.
 * Transparent chat redistributes its gradient bands across the chat body.
 */
final class ChatboxBackgroundService {
	private static final int BAKED_BORDER = 8;
	private static final int CORNER_BLEED_TRIM = 1;
	private static final int CORNER_SIZE = 32;
	private static final int BORDER_OFFSET = 12;

	private static final int[] BORDER_SPRITES = {
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_TOP_LEFT,
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_TOP_RIGHT,
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_BOTTOM_LEFT,
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_BOTTOM_RIGHT,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_TOP,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_LEFT,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_BOTTOM,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_RIGHT
	};

	private final Client client;

	private Widget[] borderPieces;
	private Widget trimmedBackground;
	private Widget zoomedBody;
	private int zoomedBodyOriginalWidth;
	private int zoomedBodyOriginalHeight;
	private int zoomedBodyWidthMode;
	private int zoomedBodyHeightMode;
	private boolean zoomedBodySpriteTiling;

	ChatboxBackgroundService(Client client) {
		this.client = client;
	}

	boolean isOpaque() {
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
		return background != null && isParchment(getBackgroundBody(background));
	}

	/*
	 * ================================================================
	 * BACKGROUND
	 * ================================================================
	 */

	Result apply(Widget chatArea, int width, int bodyHeight) {
		final Result result = new Result();
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
		if (background == null) {
			result.add(syncFrame(chatArea, null));
			return result;
		}

		final Widget body = getBackgroundBody(background);
		if (isParchment(body)) {
			result.add(zoomParchment(body, width, bodyHeight));
			result.add(trimBackground(background));
			result.add(syncFrame(chatArea, body));
			return result;
		}

		result.add(restoreZoom(body));
		result.add(restoreTrim(background));
		result.add(stackGradientBands(background, bodyHeight));
		result.add(removeFrame(chatArea));

		return result;
	}

	Result restore(Widget chatArea) {
		final Result result = new Result();
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
		final Widget body = background != null
				? getBackgroundBody(background)
				: null;

		result.add(removeFrame(chatArea));

		if (background == null) {
			trimmedBackground = null;
			zoomedBody = null;
			return result;
		}

		result.add(restoreTrim(background));
		result.add(restoreZoom(body));

		if (!isParchment(body)) {
			result.add(stackGradientBands(background, ChatboxGeometry.NATIVE_BODY_HEIGHT));
		}

		return result;
	}

	private Result zoomParchment(Widget body, int targetWidth, int targetHeight) {
		final Result result = new Result();
		final int overscanX = bevelOverscan(targetWidth, ChatboxGeometry.NATIVE_WIDTH);
		final int overscanY = bevelOverscan(targetHeight, ChatboxGeometry.NATIVE_BODY_HEIGHT);
		final int width = targetWidth + overscanX * 2;
		final int height = targetHeight + overscanY * 2;
		final int x = body.getOriginalX() - overscanX;
		final int y = body.getOriginalY() - overscanY;
		boolean changed = false;

		if (zoomedBody != body) {
			rememberZoomState(body);
		}

		if (body.getOriginalWidth() != width || body.getOriginalHeight() != height
				|| body.getWidthMode() != WidgetSizeMode.ABSOLUTE || body.getHeightMode() != WidgetSizeMode.ABSOLUTE) {
			body.setSize(width, height, WidgetSizeMode.ABSOLUTE, WidgetSizeMode.ABSOLUTE);
			result.mutations++;
			changed = true;
		}

		if (body.getRelativeX() != x || body.getRelativeY() != y) {
			body.setForcedPosition(x, y);
			result.mutations++;
			changed = true;
		}

		if (body.getSpriteTiling()) {
			body.setSpriteTiling(false);
			result.mutations++;
			changed = true;
		}

		if (changed) {
			body.revalidate();
			result.revalidates++;
		}

		return result;
	}

	private Result trimBackground(Widget background) {
		final Result result = new Result();
		boolean changed = false;

		if (background.getOriginalWidth() != CORNER_BLEED_TRIM || background.getOriginalHeight() != CORNER_BLEED_TRIM) {
			background.setSize(CORNER_BLEED_TRIM, CORNER_BLEED_TRIM);
			result.mutations++;
			changed = true;
		}

		if (background.getRelativeX() != 0 || background.getRelativeY() != CORNER_BLEED_TRIM) {
			background.setForcedPosition(0, CORNER_BLEED_TRIM);
			result.mutations++;
			changed = true;
		}

		if (changed) {
			background.revalidate();
			result.revalidates++;
		}

		trimmedBackground = background;
		return result;
	}

	private Result restoreTrim(Widget background) {
		final Result result = new Result();

		if (trimmedBackground != background) {
			trimmedBackground = null;
			return result;
		}

		background.setSize(0, 0);
		background.setForcedPosition(-1, -1);
		background.revalidate();

		result.mutations += 2;
		result.revalidates++;
		trimmedBackground = null;

		return result;
	}

	private Result restoreZoom(Widget currentBody) {
		final Result result = new Result();

		if (zoomedBody == null) {
			return result;
		}

		if (zoomedBody != currentBody) {
			clearZoomState();
			return result;
		}

		zoomedBody.setSize(zoomedBodyOriginalWidth, zoomedBodyOriginalHeight, zoomedBodyWidthMode, zoomedBodyHeightMode);
		zoomedBody.setForcedPosition(-1, -1);
		zoomedBody.setSpriteTiling(zoomedBodySpriteTiling);
		zoomedBody.revalidate();

		result.mutations += 3;
		result.revalidates++;
		clearZoomState();

		return result;
	}

	private void rememberZoomState(Widget body) {
		zoomedBody = body;
		zoomedBodyOriginalWidth = body.getOriginalWidth();
		zoomedBodyOriginalHeight = body.getOriginalHeight();
		zoomedBodyWidthMode = body.getWidthMode();
		zoomedBodyHeightMode = body.getHeightMode();
		zoomedBodySpriteTiling = body.getSpriteTiling();
	}

	private void clearZoomState() {
		zoomedBody = null;
	}

	private Result stackGradientBands(Widget background, int targetHeight) {
		final Result result = new Result();
		final Widget[] bands = background.getDynamicChildren();
		if (bands == null
				|| bands.length == 0
				|| background.getHeight() != targetHeight
				|| targetHeight < bands.length) {
			return result;
		}

		final int bandHeight = targetHeight / bands.length;

		for (int i = 0; i < bands.length; i++) {
			final Widget band = bands[i];
			if (band == null || band.getHeightMode() != WidgetSizeMode.ABSOLUTE) {
				continue;
			}

			final int y = bandHeight * i;
			final int height = i == bands.length - 1
					? targetHeight - y
					: bandHeight;

			boolean changed = false;

			if (band.getOriginalY() != y) {
				band.setOriginalY(y);
				result.mutations++;
				changed = true;
			}

			if (band.getOriginalHeight() != height) {
				band.setOriginalHeight(height);
				result.mutations++;
				changed = true;
			}

			if (changed) {
				band.revalidate();
				result.revalidates++;
			}
		}

		return result;
	}

	private static int bevelOverscan(int target, int nativeSize) {
		final int denominator = nativeSize - 2 * BAKED_BORDER;
		if (denominator <= 0) {
			return BAKED_BORDER;
		}

		return (BAKED_BORDER * target + denominator - 1) / denominator;
	}

	private static Widget getBackgroundBody(Widget background) {
		final Widget[] dynamic = background.getDynamicChildren();

		return dynamic != null && dynamic.length > 0
				? dynamic[0]
				: null;
	}

	private static boolean isParchment(Widget body) {
		return body != null && body.getType() == WidgetType.GRAPHIC;
	}

	/*
	 * ================================================================
	 * FRAME
	 * ================================================================
	 */

	private Result syncFrame(Widget chatArea, Widget parchment) {
		final Result result = new Result();

		if (chatArea == null) {
			borderPieces = null;
			return result;
		}

		if (parchment == null) {
			result.add(syncFrameVisibility(true));
			return result;
		}

		if (!framePresent(chatArea)) {
			result.add(removeFrame(chatArea));
			result.add(createFrame(chatArea));
		}

		if (borderPieces == null) {
			return result;
		}

		final int width = chatArea.getWidth();
		final int height = chatArea.getHeight();
		final int innerWidth = Math.max(0, width - 2 * CORNER_SIZE);
		final int innerHeight = Math.max(0, height - 2 * CORNER_SIZE);

		final int[][] rectangles = {
				{0, 0, CORNER_SIZE, CORNER_SIZE},
				{width - CORNER_SIZE, 0, CORNER_SIZE, CORNER_SIZE},
				{0, height - CORNER_SIZE, CORNER_SIZE, CORNER_SIZE},
				{width - CORNER_SIZE, height - CORNER_SIZE, CORNER_SIZE, CORNER_SIZE},
				{CORNER_SIZE, -BORDER_OFFSET - 1, innerWidth, CORNER_SIZE},
				{-BORDER_OFFSET - 1, CORNER_SIZE, CORNER_SIZE, innerHeight},
				{CORNER_SIZE, height - CORNER_SIZE + BORDER_OFFSET, innerWidth, CORNER_SIZE},
				{width - CORNER_SIZE + BORDER_OFFSET, CORNER_SIZE, CORNER_SIZE, innerHeight}
		};

		for (int i = 0; i < borderPieces.length; i++) {
			final Widget piece = borderPieces[i];
			final int[] rectangle = rectangles[i];
			boolean changed = false;

			if (piece.getOriginalX() != rectangle[0]) {
				piece.setOriginalX(rectangle[0]);
				result.mutations++;
				changed = true;
			}

			if (piece.getOriginalY() != rectangle[1]) {
				piece.setOriginalY(rectangle[1]);
				result.mutations++;
				changed = true;
			}

			if (piece.getOriginalWidth() != rectangle[2] || piece.getOriginalHeight() != rectangle[3]) {
				piece.setSize(rectangle[2], rectangle[3]);
				result.mutations++;
				changed = true;
			}

			if (changed) {
				piece.revalidate();
				result.revalidates++;
			}
		}

		result.add(syncFrameVisibility(parchment.isSelfHidden()));
		return result;
	}

	private Result createFrame(Widget chatArea) {
		final Result result = new Result();

		borderPieces = new Widget[BORDER_SPRITES.length];

		for (int i = 0; i < BORDER_SPRITES.length; i++) {
			final Widget piece = chatArea.createChild(-1, WidgetType.GRAPHIC);

			piece.setSpriteId(BORDER_SPRITES[i]);
			piece.setSpriteTiling(true);
			borderPieces[i] = piece;
			result.mutations++;
		}

		return result;
	}

	private Result removeFrame(Widget chatArea) {
		final Result result = new Result();

		if (borderPieces == null) {
			return result;
		}

		final Widget[] children = chatArea != null
				? chatArea.getChildren()
				: null;

		if (children != null) {
			for (Widget piece : borderPieces) {
				if (piece == null) {
					continue;
				}

				final int index = piece.getIndex();
				if (index >= 0 && index < children.length && children[index] == piece) {
					children[index] = null;
					result.mutations++;
				}
			}
		}

		borderPieces = null;
		return result;
	}

	private Result syncFrameVisibility(boolean hidden) {
		final Result result = new Result();

		if (borderPieces == null) {
			return result;
		}

		for (Widget piece : borderPieces) {
			if (piece != null && piece.isSelfHidden() != hidden) {
				piece.setHidden(hidden);
				result.mutations++;
			}
		}

		return result;
	}

	private boolean framePresent(Widget chatArea) {
		if (borderPieces == null) {
			return false;
		}

		final Widget[] children = chatArea.getChildren();
		if (children == null) {
			return false;
		}

		for (Widget piece : borderPieces) {
			if (piece == null) {
				return false;
			}

			final int index = piece.getIndex();
			if (index < 0 || index >= children.length || children[index] != piece) {
				return false;
			}
		}

		return true;
	}

	static final class Result {
		private int mutations;
		private int revalidates;

		int getMutations() {
			return mutations;
		}

		int getRevalidates() {
			return revalidates;
		}

		private void add(Result other) {
			if (other == null) {
				return;
			}

			mutations += other.mutations;
			revalidates += other.revalidates;
		}
	}
}

package com.bigboldchat.chatbox;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;

/**
 * Owns chat control/tab bar geometry and visibility.
 */
public final class ChatboxControlsLayout {
	private static final int TAB_NATIVE_WIDTH = 56;

	private static final int[] TAB_NATIVE_X = {
			458,
			396,
			334,
			272,
			210,
			148,
			86
	};

	private static final int[] TAB_COMPONENTS = {
			InterfaceID.Chatbox.CHAT_ALL,
			InterfaceID.Chatbox.CHAT_GAME,
			InterfaceID.Chatbox.CHAT_PUBLIC,
			InterfaceID.Chatbox.CHAT_PRIVATE,
			InterfaceID.Chatbox.CHAT_FRIENDSCHAT,
			InterfaceID.Chatbox.CHAT_CLAN,
			InterfaceID.Chatbox.CHAT_TRADE
	};

	private final Client client;

	private Widget hiddenControls;
	private boolean nativeControlsHidden;

	public ChatboxControlsLayout(Client client) {
		this.client = client;
	}

	/**
	 * Apply the control bar width and native-width tab positions.
	 *
	 * @return number of widget fields mutated
	 */
	int apply(int width) {
		int mutations = 0;

		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		final Widget background = client.getWidget(InterfaceID.Chatbox.CONTROLS_BACKGROUND_GRAPHIC);

		if (controls != null && controls.getOriginalWidth() != width) {
			controls.setOriginalWidth(width);
			mutations++;
		}

		if (background != null && background.getOriginalWidth() != width) {
			background.setOriginalWidth(width);
			mutations++;
		}

		final Widget[] tabs = getReadyTabs();
		if (tabs == null) {
			return mutations;
		}

		final int widthDelta = width - ChatboxGeometry.NATIVE_WIDTH;
		final int tabCount = tabs.length;

		for (int i = 0; i < tabCount; i++) {
			final Widget tab = tabs[i];
			final int targetX = spreadX(i, widthDelta, tabCount);

			if (tab.getOriginalWidth() != TAB_NATIVE_WIDTH) {
				tab.setOriginalWidth(TAB_NATIVE_WIDTH);
				mutations++;
			}

			if (tab.getOriginalX() != targetX) {
				tab.setOriginalX(targetX);
				mutations++;
			}
		}

		return mutations;
	}

	int syncHidden(boolean hidden) {
		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		if (controls == null) {
			return 0;
		}

		if (!hidden) {
			return restoreHidden(controls);
		}

		if (hiddenControls != controls) {
			hiddenControls = controls;
			nativeControlsHidden = controls.isSelfHidden();
		}

		if (controls.isSelfHidden()) {
			return 0;
		}

		controls.setHidden(true);
		return 1;
	}

	int restoreHidden() {
		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		return restoreHidden(controls);
	}

	int restoreNative() {
		return apply(ChatboxGeometry.NATIVE_WIDTH);
	}

	boolean matches(int width) {
		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		final Widget background = client.getWidget(InterfaceID.Chatbox.CONTROLS_BACKGROUND_GRAPHIC);

		if (controls != null && controls.getWidth() != width) {
			return false;
		}

		if (background != null && background.getWidth() != width) {
			return false;
		}

		final Widget[] tabs = getReadyTabs();
		if (tabs == null) {
			return true;
		}

		final int widthDelta = width - ChatboxGeometry.NATIVE_WIDTH;
		final int tabCount = tabs.length;

		for (int i = 0; i < tabCount; i++) {
			final Widget tab = tabs[i];
			if (tab.getOriginalWidth() != TAB_NATIVE_WIDTH || tab.getOriginalX() != spreadX(i, widthDelta, tabCount)) {
				return false;
			}
		}

		return true;
	}

	private int restoreHidden(Widget controls) {
		if (hiddenControls == null) {
			return 0;
		}

		if (controls != hiddenControls) {
			hiddenControls = null;
			return 0;
		}

		int mutations = 0;
		if (controls.isSelfHidden() != nativeControlsHidden) {
			controls.setHidden(nativeControlsHidden);
			mutations++;
		}

		hiddenControls = null;
		return mutations;
	}

	private Widget[] getReadyTabs() {
		final Widget[] tabs = new Widget[TAB_COMPONENTS.length];

		for (int i = 0; i < TAB_COMPONENTS.length; i++) {
			final Widget tab = client.getWidget(TAB_COMPONENTS[i]);
			if (tab == null || tab.getXPositionMode() != WidgetPositionMode.ABSOLUTE_RIGHT) {
				return null;
			}

			tabs[i] = tab;
		}

		return tabs;
	}

	private static int spreadX(int index, int widthDelta, int tabCount) {
		return TAB_NATIVE_X[index] + widthDelta * (tabCount - index) / tabCount;
	}
}

package com.bigboldchat.chatbox;

/**
 * Native chatbox geometry shared by resize and restore paths.
 *
 * The resizable chat slot includes the 23-pixel
 * control/tab band beneath the 142-pixel chat body.
 */
public final class ChatboxGeometry {
	public static final int NATIVE_WIDTH = 519;
	public static final int NATIVE_BODY_HEIGHT = 142;
	public static final int NATIVE_SLOT_HEIGHT = 165;
	public static final int NATIVE_TAB_HEIGHT = NATIVE_SLOT_HEIGHT - NATIVE_BODY_HEIGHT;

	private ChatboxGeometry() {
		/*
		 * CHATBOX GEOMETRY
		 */
	}

	public static int bodyHeight(int slotHeight) {
		return Math.max(0, slotHeight - NATIVE_TAB_HEIGHT);
	}

	public static int bodyHeight(int slotHeight, boolean buttonsHidden) {
		return buttonsHidden
				? Math.max(0, slotHeight)
				: bodyHeight(slotHeight);
	}
}

