		resizeApply.record(elapsedNanos);
		resizeApplies++;

		if (!widthChanged && !heightChanged) {
			resizeNoops++;
		}

		if (widthChanged) {
			resizeWidthChanges++;
		}

		if (heightChanged) {
			resizeHeightChanges++;
