package com.bigboldchat.input;

import com.bigboldchat.Configurations;
import com.bigboldchat.chatbox.ChatboxResizeService;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.HotkeyListener;

/**
 * Owns the chatbox hotkey lifecycle.
 */
public final class ChatboxHotkey {
	private final ClientThread clientThread;
	private final ChatboxResizeService resizeService;
	private final KeyManager keyManager;
	private final Runnable clearChat;
	private final HotkeyListener visibilityHotkeyListener;
	private final HotkeyListener clearHotkeyListener;

	private volatile boolean active;

	public ChatboxHotkey(
			ClientThread clientThread,
			Configurations config,
			ChatboxResizeService resizeService,
			KeyManager keyManager,
			Runnable clearChat) {
		this.clientThread = clientThread;
		this.resizeService = resizeService;
		this.keyManager = keyManager;
		this.clearChat = clearChat;
		this.visibilityHotkeyListener = new HotkeyListener(config::hideChatboxHotkey) {
			@Override
			public void hotkeyPressed() {
				if (!active) {
					return;
				}

				clientThread.invokeLater(() -> {
					if (active) {
						resizeService.toggleChatPresentation();
					}
				});
			}
		};

		/*
		 * Route the hotkey through the same clear action used by ::clear / ::cls so
		 * keyboard and command behavior cannot drift apart.
		 */
		this.clearHotkeyListener = new HotkeyListener(config::clearChatHotkey) {
			@Override
			public void hotkeyPressed() {
				if (!active) {
					return;
				}

				clientThread.invokeLater(() -> {
					if (active) {
						ChatboxHotkey.this.clearChat.run();
					}
				});
			}
		};
	}

	public void activate() {
		if (active) {
			return;
		}

		active = true;
		keyManager.registerKeyListener(visibilityHotkeyListener);
		keyManager.registerKeyListener(clearHotkeyListener);
	}

	public void deactivate() {
		if (!active) {
			return;
		}

		active = false;
		keyManager.unregisterKeyListener(visibilityHotkeyListener);
		keyManager.unregisterKeyListener(clearHotkeyListener);
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import com.bigboldchat.chatbox.ChatboxGeometry;
import com.bigboldchat.chatbox.ChatboxPlacement;

import net.runelite.api.Client;

/**
 * Resolves configured chatbox geometry against visible interface bounds.
 */
public final class ChatboxBounds {
	private static final int MIN_WIDTH = 200;
	private static final int MIN_HEIGHT = 100;

	private static final int COLLIDE_LEFT = 1;
	private static final int COLLIDE_RIGHT = 1 << 1;
	private static final int COLLIDE_TOP = 1 << 2;
	private static final int COLLIDE_BOTTOM = 1 << 3;

	private static final int COLLIDE_HORIZONTAL = COLLIDE_LEFT | COLLIDE_RIGHT;
	private static final int COLLIDE_VERTICAL = COLLIDE_TOP | COLLIDE_BOTTOM;
	private static final int COLLIDE_ALL = COLLIDE_HORIZONTAL | COLLIDE_VERTICAL;

	private ChatboxBounds() {
		/*
		 * CHATBOX BOUNDS
		 */
	}

	/**
	 * ================================================================
	 * RESOLUTION
	 * ================================================================
	 */
	public static Result resolve(Client client, ChatboxPlacement.State placement, boolean buttonsHidden) {
		return resolve(client, placement, buttonsHidden, new Tracker(), null);
	}

	public static Result resolve(Client client, ChatboxPlacement.State placement, boolean buttonsHidden, Tracker tracker) {
		return resolve(client, placement, buttonsHidden, tracker, null);
	}

	public static Result resolve(Client client, ChatboxPlacement.State placement, boolean buttonsHidden, Tracker tracker,
			InterfaceBounds.Overrides overrides) {
		if (client == null || placement == null) {
			return Result.unbounded(0, 0);
		}

		final Rectangle desiredBounds = placement.getDesiredBounds();
		if (!placement.isBounded()) {
			return Result.unbounded(desiredBounds.width, desiredBounds.height);
		}

		final InterfaceBounds interfaces = InterfaceBounds.capture(client, overrides);
		final Tracker activeTracker = tracker != null ? tracker : new Tracker();
		final Resolution resolution = activeTracker.resolve(desiredBounds, interfaces.getCanvas(), interfaces.getIdentifiedObstacles());
		final Rectangle effectiveBounds = resolution.bounds;
		final Rectangle presentationBounds = new Rectangle(effectiveBounds.x, effectiveBounds.y, effectiveBounds.width,
				ChatboxGeometry.bodyHeight(effectiveBounds.height, buttonsHidden));

		return new Result(desiredBounds, effectiveBounds, interfaces.intersectsForeground(presentationBounds));
	}

	private static boolean fits(Rectangle candidate, Rectangle canvas, List<InterfaceBounds.Obstacle> obstacles) {
		if (!canvas.contains(candidate)) {
			return false;
		}

		for (InterfaceBounds.Obstacle obstacle : obstacles) {
			if (candidate.intersects(obstacle.getBounds())) {
				return false;
			}
		}

		return true;
	}

	/**
	 * ================================================================
	 * COLLISION TRACKING
	 * ================================================================
	 */
	public static final class Tracker {
		private final Map<InterfaceBounds.ObstacleKey, Contact> contacts = new EnumMap<>(InterfaceBounds.ObstacleKey.class);

		private Rectangle previousDesired;

		public void reset() {
			contacts.clear();
			previousDesired = null;
		}

		private Resolution resolve(Rectangle desired, Rectangle canvas, List<InterfaceBounds.Obstacle> obstacles) {
			int left = desired.x;
			int top = desired.y;
			int right = desired.x + desired.width;
			int bottom = desired.y + desired.height;
			int collisionMask = 0;

			/*
			 * Canvas collisions constrain only the crossed edge.
			 */
			if (left < canvas.x) {
				left = canvas.x;
				collisionMask |= COLLIDE_LEFT;
			}
			if (right > canvas.x + canvas.width) {
				right = canvas.x + canvas.width;
				collisionMask |= COLLIDE_RIGHT;
			}
			if (top < canvas.y) {
				top = canvas.y;
				collisionMask |= COLLIDE_TOP;
			}
			if (bottom > canvas.y + canvas.height) {
				bottom = canvas.y + canvas.height;
				collisionMask |= COLLIDE_BOTTOM;
			}

			final Set<InterfaceBounds.ObstacleKey> seen = EnumSet.noneOf(InterfaceBounds.ObstacleKey.class);
			for (InterfaceBounds.Obstacle obstacle : obstacles) {
				final InterfaceBounds.ObstacleKey key = obstacle.getKey();
				final Rectangle bounds = obstacle.getBounds();
				seen.add(key);

				final Contact contact = contacts.computeIfAbsent(key, ignored -> new Contact());
				if (!desired.intersects(bounds)) {
					contact.collisionMask = 0;
					contact.previousBounds = new Rectangle(bounds);
					continue;
				}

				if (contact.collisionMask == 0) {
					contact.collisionMask = detectEntrySides(previousDesired, contact.previousBounds, desired, bounds);
				}

				collisionMask |= contact.collisionMask;
				if ((contact.collisionMask & COLLIDE_LEFT) != 0) {
					left = Math.max(left, bounds.x + bounds.width);
				}
				if ((contact.collisionMask & COLLIDE_RIGHT) != 0) {
					right = Math.min(right, bounds.x);
				}
				if ((contact.collisionMask & COLLIDE_TOP) != 0) {
					top = Math.max(top, bounds.y + bounds.height);
				}
				if ((contact.collisionMask & COLLIDE_BOTTOM) != 0) {
					bottom = Math.min(bottom, bounds.y);
				}

				contact.previousBounds = new Rectangle(bounds);
			}

			contacts.keySet().removeIf(key -> !seen.contains(key));
			previousDesired = new Rectangle(desired);

			final Axis horizontal = enforceMinimum(desired.x, desired.x + desired.width, left, right, MIN_WIDTH,
					collisionMask & COLLIDE_HORIZONTAL, COLLIDE_LEFT, COLLIDE_RIGHT);
			final Axis vertical = enforceMinimum(desired.y, desired.y + desired.height, top, bottom, MIN_HEIGHT,
					collisionMask & COLLIDE_VERTICAL, COLLIDE_TOP, COLLIDE_BOTTOM);
			final Rectangle trackedBounds = new Rectangle(horizontal.start, vertical.start,
					Math.max(0, horizontal.end - horizontal.start), Math.max(0, vertical.end - vertical.start));

			return preferSingleEdge(desired, canvas, obstacles, new Resolution(trackedBounds, collisionMask));
		}
	}

	/**
	 * ================================================================
	 * COLLISION HELPERS
	 * ================================================================
	 */
	/*
	 * Prefer one detected edge when it clears every current obstacle and preserves more usable area.
	 */
	private static Resolution preferSingleEdge(Rectangle desired, Rectangle canvas, List<InterfaceBounds.Obstacle> obstacles, Resolution tracked) {
		if (desired == null || canvas == null || tracked == null || !canvas.contains(desired) || tracked.collisionMask == 0) {
			return tracked;
		}

		Rectangle bestBounds = tracked.bounds;
		int bestMask = tracked.collisionMask;
		long bestArea = area(bestBounds);

		final int[] sides = {COLLIDE_LEFT, COLLIDE_RIGHT, COLLIDE_TOP, COLLIDE_BOTTOM};
		for (int side : sides) {
			if ((tracked.collisionMask & side) == 0) {
				continue;
			}

			final Rectangle candidate = singleEdgeCandidate(desired, obstacles, side);
			if (candidate == null || candidate.width < MIN_WIDTH || candidate.height < MIN_HEIGHT || !fits(candidate, canvas, obstacles)) {
				continue;
			}

			final long candidateArea = area(candidate);
			if (candidateArea > bestArea) {
				bestBounds = candidate;
				bestMask = side;
				bestArea = candidateArea;
			}
		}

		return bestBounds == tracked.bounds ? tracked : new Resolution(bestBounds, bestMask);
	}

	private static Rectangle singleEdgeCandidate(Rectangle desired, List<InterfaceBounds.Obstacle> obstacles, int side) {
		int left = desired.x;
		int top = desired.y;
		int right = desired.x + desired.width;
		int bottom = desired.y + desired.height;
		boolean intersects = false;

		for (InterfaceBounds.Obstacle obstacle : obstacles) {
			final Rectangle bounds = obstacle.getBounds();
			if (!desired.intersects(bounds)) {
				continue;
			}

			intersects = true;
			if (side == COLLIDE_LEFT) {
				left = Math.max(left, bounds.x + bounds.width);
			} else if (side == COLLIDE_RIGHT) {
				right = Math.min(right, bounds.x);
			} else if (side == COLLIDE_TOP) {
				top = Math.max(top, bounds.y + bounds.height);
			} else if (side == COLLIDE_BOTTOM) {
				bottom = Math.min(bottom, bounds.y);
			}
		}

		if (!intersects || right <= left || bottom <= top) {
			return null;
		}

		return new Rectangle(left, top, right - left, bottom - top);
	}

	private static long area(Rectangle bounds) {
		return bounds != null ? (long) Math.max(0, bounds.width) * Math.max(0, bounds.height) : 0L;
	}

	private static int detectEntrySides(Rectangle previousDesired, Rectangle previousObstacle, Rectangle desired, Rectangle obstacle) {
		int collisionMask = 0;

		/*
		 * New contacts choose the single edge that preserves the largest usable area.
		 */
		if (previousObstacle == null) {
			return bestSingleSide(desired, obstacle, COLLIDE_ALL);
		}

		/*
		 * Discontinuous obstacle moves are resolved from current geometry instead of prior direction.
		 */
		if (isDiscontinuousMove(previousObstacle, obstacle)) {
			return bestSingleSide(desired, obstacle, COLLIDE_ALL);
		}

		if (previousDesired != null && !previousDesired.intersects(previousObstacle)) {
			final int previousRight = previousDesired.x + previousDesired.width;
			final int previousBottom = previousDesired.y + previousDesired.height;
			final int previousObstacleRight = previousObstacle.x + previousObstacle.width;
			final int previousObstacleBottom = previousObstacle.y + previousObstacle.height;

			if (previousObstacleRight <= previousDesired.x) {
				collisionMask |= COLLIDE_LEFT;
			}
			if (previousObstacle.x >= previousRight) {
				collisionMask |= COLLIDE_RIGHT;
			}
			if (previousObstacleBottom <= previousDesired.y) {
				collisionMask |= COLLIDE_TOP;
			}
			if (previousObstacle.y >= previousBottom) {
				collisionMask |= COLLIDE_BOTTOM;
			}

			if (collisionMask != 0) {
				return resolveCornerCollision(desired, obstacle, collisionMask);
			}
		}

		final int desiredRight = desired.x + desired.width;
		final int desiredBottom = desired.y + desired.height;
		final int obstacleRight = obstacle.x + obstacle.width;
		final int obstacleBottom = obstacle.y + obstacle.height;

		if (obstacle.x <= desired.x && obstacleRight > desired.x) {
			collisionMask |= COLLIDE_LEFT;
		}
		if (obstacle.x < desiredRight && obstacleRight >= desiredRight) {
			collisionMask |= COLLIDE_RIGHT;
		}
		if (obstacle.y <= desired.y && obstacleBottom > desired.y) {
			collisionMask |= COLLIDE_TOP;
		}
		if (obstacle.y < desiredBottom && obstacleBottom >= desiredBottom) {
			collisionMask |= COLLIDE_BOTTOM;
		}

		if (collisionMask != 0) {
			return resolveCornerCollision(desired, obstacle, collisionMask);
		}

		return bestSingleSide(desired, obstacle, COLLIDE_ALL);
	}

	private static boolean isDiscontinuousMove(Rectangle previous, Rectangle current) {
		if (previous == null || current == null) {
			return false;
		}

		final int horizontalThreshold = Math.max(1, Math.max(previous.width, current.width));
		final int verticalThreshold = Math.max(1, Math.max(previous.height, current.height));
		return Math.abs(current.x - previous.x) > horizontalThreshold || Math.abs(current.y - previous.y) > verticalThreshold;
	}

	private static int resolveCornerCollision(Rectangle desired, Rectangle obstacle, int collisionMask) {
		final boolean horizontal = (collisionMask & COLLIDE_HORIZONTAL) != 0;
		final boolean vertical = (collisionMask & COLLIDE_VERTICAL) != 0;
		return horizontal && vertical ? bestSingleSide(desired, obstacle, collisionMask) : collisionMask;
	}

	private static int bestSingleSide(Rectangle desired, Rectangle obstacle, int candidates) {
		int bestSide = 0;
		boolean bestValid = false;
		long bestArea = -1L;
		int bestLoss = Integer.MAX_VALUE;

		final int[] sides = {COLLIDE_LEFT, COLLIDE_RIGHT, COLLIDE_TOP, COLLIDE_BOTTOM};
		for (int side : sides) {
			if ((candidates & side) == 0) {
				continue;
			}

			final int remaining = remainingSize(desired, obstacle, side);
			final boolean horizontal = (side & COLLIDE_HORIZONTAL) != 0;
			final int desiredSize = horizontal ? desired.width : desired.height;
			final int minimum = horizontal ? MIN_WIDTH : MIN_HEIGHT;
			final boolean valid = remaining >= minimum;
			final long remainingArea = horizontal ? (long) remaining * desired.height : (long) desired.width * remaining;
			final int loss = Math.max(0, desiredSize - remaining);

			if (bestSide == 0 || valid && !bestValid || valid == bestValid && remainingArea > bestArea
					|| valid == bestValid && remainingArea == bestArea && loss < bestLoss) {
				bestSide = side;
				bestValid = valid;
				bestArea = remainingArea;
				bestLoss = loss;
			}
		}

		return bestSide != 0 ? bestSide : COLLIDE_LEFT;
	}

	private static int remainingSize(Rectangle desired, Rectangle obstacle, int side) {
		final int desiredRight = desired.x + desired.width;
		final int desiredBottom = desired.y + desired.height;
		final int obstacleRight = obstacle.x + obstacle.width;
		final int obstacleBottom = obstacle.y + obstacle.height;

		if (side == COLLIDE_LEFT) {
			return clamp(desiredRight - obstacleRight, 0, desired.width);
		}
		if (side == COLLIDE_RIGHT) {
			return clamp(obstacle.x - desired.x, 0, desired.width);
		}
		if (side == COLLIDE_TOP) {
			return clamp(desiredBottom - obstacleBottom, 0, desired.height);
		}

		return clamp(obstacle.y - desired.y, 0, desired.height);
	}

	private static int clamp(int value, int minimum, int maximum) {
		return Math.max(minimum, Math.min(value, maximum));
	}

	private static Axis enforceMinimum(int desiredStart, int desiredEnd, int constrainedStart, int constrainedEnd,
			int minimum, int collisionMask, int startCollision, int endCollision) {
		if (constrainedEnd - constrainedStart >= minimum) {
			return new Axis(constrainedStart, constrainedEnd);
		}

		if (collisionMask == startCollision) {
			return new Axis(constrainedEnd - minimum, constrainedEnd);
		}

		if (collisionMask == endCollision) {
			return new Axis(constrainedStart, constrainedStart + minimum);
		}

		final int desiredCenter = desiredStart + (desiredEnd - desiredStart) / 2;
		int start = desiredCenter - minimum / 2;
		int end = start + minimum;
		if (start < desiredStart) {
			start = desiredStart;
			end = start + minimum;
		}
		if (end > desiredEnd) {
			end = desiredEnd;
			start = end - minimum;
		}

		return new Axis(start, end);
	}

	/**
	 * ================================================================
	 * STATE TYPES
	 * ================================================================
	 */
	private static final class Contact {
		private Rectangle previousBounds;
		private int collisionMask;
	}

	private static final class Resolution {
		private final Rectangle bounds;
		private final int collisionMask;

		private Resolution(Rectangle bounds, int collisionMask) {
			this.bounds = bounds;
			this.collisionMask = collisionMask;
		}
	}

	private static final class Axis {
		private final int start;
		private final int end;

		private Axis(int start, int end) {
			this.start = start;
			this.end = end;
		}
	}

	public static final class Result {
		private final Rectangle desiredBounds;
		private final Rectangle effectiveBounds;
		private final boolean foregroundOverlap;

		private Result(Rectangle desiredBounds, Rectangle effectiveBounds, boolean foregroundOverlap) {
			this.desiredBounds = new Rectangle(desiredBounds);
			this.effectiveBounds = new Rectangle(effectiveBounds);
			this.foregroundOverlap = foregroundOverlap;
		}

		private static Result unbounded(int width, int height) {
			final Rectangle bounds = new Rectangle(0, 0, width, height);
			return new Result(bounds, bounds, false);
		}

		public int getWidth() {
			return effectiveBounds.width;
		}

		public int getHeight() {
			return effectiveBounds.height;
		}

		public Rectangle getDesiredBounds() {
			return new Rectangle(desiredBounds);
		}

		public Rectangle getEffectiveBounds() {
			return new Rectangle(effectiveBounds);
		}

		public boolean isForegroundOverlap() {
			return foregroundOverlap;
		}
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;

/**
 * Resolves Modern side-row collision direction without mutating layout state.
 */
public final class CollisionManager {
	private final Client client;

	public CollisionManager(Client client) {
		this.client = client;
	}

	/*
	 * Determines whether the connected Modern tab strip must split and which side is obstructed.
	 */
	public Result resolveSideRows(Rectangle chatboxBounds, Rectangle staticRow, Rectangle movableRow, Side currentSide) {
		if (client == null || client.getTopLevelInterfaceId() != InterfaceID.TOPLEVEL_PRE_EOC || staticRow == null || movableRow == null) {
			return Result.NONE;
		}

		final Rectangle strip = new Rectangle(staticRow);
		strip.add(movableRow);
		if (strip.isEmpty()) {
			return Result.NONE;
		}

		Candidate best = candidate(Source.CHATBOX, chatboxBounds, staticRow, movableRow, strip, currentSide);
		final InterfaceBounds interfaces = InterfaceBounds.capture(client);
		for (InterfaceBounds.Obstacle obstacle : interfaces.getIdentifiedObstacles()) {
			final Source source = sourceFor(obstacle.getKey());
			if (source == Source.NONE) {
				continue;
			}

			best = prefer(best, candidate(source, obstacle.getBounds(), staticRow, movableRow, strip, currentSide), currentSide);
		}

		return best != null
				? new Result(best.side, best.source)
				: Result.NONE;
	}

	private static Candidate candidate(Source source, Rectangle bounds, Rectangle staticRow, Rectangle movableRow, Rectangle strip, Side currentSide) {
		if (bounds == null || bounds.isEmpty() || !bounds.intersects(strip)) {
			return null;
		}

		final long staticArea = intersectionArea(bounds, staticRow);
		final long movableArea = intersectionArea(bounds, movableRow);
		final Side side;

		if (staticArea > 0L && movableArea == 0L) {
			side = Side.RIGHT;
		} else if (movableArea > 0L && staticArea == 0L) {
			side = Side.LEFT;
		} else if (staticArea != movableArea) {
			side = staticArea > movableArea
					? Side.RIGHT
					: Side.LEFT;
		} else if (currentSide != null && currentSide != Side.NONE) {
			/*
			 * Balanced overlap preserves the current split side.
			 */
			side = currentSide;
		} else {
			final long boundsCenter2 = (long) bounds.x * 2L + bounds.width;
			final long stripCenter2 = (long) strip.x * 2L + strip.width;
			side = boundsCenter2 >= stripCenter2
					? Side.RIGHT
					: Side.LEFT;
		}

		return new Candidate(side, source, intersectionArea(bounds, strip));
	}

	private static Candidate prefer(Candidate current, Candidate next, Side currentSide) {
		if (next == null) {
			return current;
		}

		if (current == null) {
			return next;
		}

		/*
		 * The current split side wins when multiple collisions compete.
		 */
		if (currentSide != null && currentSide != Side.NONE) {
			final boolean currentMatches = current.side == currentSide;
			final boolean nextMatches = next.side == currentSide;
			if (currentMatches != nextMatches) {
				return nextMatches
						? next
						: current;
			}
		}

		if (next.score != current.score) {
			return next.score > current.score
					? next
					: current;
		}

		return next.source.priority < current.source.priority
				? next
				: current;
	}

	private static long intersectionArea(Rectangle first, Rectangle second) {
		if (first == null || second == null) {
			return 0L;
		}

		final Rectangle intersection = first.intersection(second);
		return intersection.isEmpty()
				? 0L
				: (long) intersection.width * intersection.height;
	}

	private static Source sourceFor(InterfaceBounds.ObstacleKey key) {
		if (key == null) {
			return Source.NONE;
		}

		/*
		 * Only map and orb geometry can trigger an interface-driven row split.
		 */
		switch (key) {
			case MODERN_MAP:
				return Source.MAP;
			case MODERN_ORBS:
				return Source.ORBS;
			default:
				return Source.NONE;
		}
	}

	public enum Side {
		NONE,
		LEFT,
		RIGHT
	}

	public enum Source {
		NONE(99),
		CHATBOX(0),
		MAP(1),
		ORBS(2);

		private final int priority;

		Source(int priority) {
			this.priority = priority;
		}
	}

	public static final class Result {
		private static final Result NONE = new Result(Side.NONE, Source.NONE);

		private final Side side;
		private final Source source;

		private Result(Side side, Source source) {
			this.side = side != null ? side : Side.NONE;
			this.source = source != null ? source : Source.NONE;
		}

		public Side getSide() {
			return side;
		}

		public Source getSource() {
			return source;
		}

		public boolean needsTwoRows() {
			return side != Side.NONE;
		}
	}

	private static final class Candidate {
		private final Side side;
		private final Source source;
		private final long score;

		private Candidate(Side side, Source source, long score) {
			this.side = side;
			this.source = source;
			this.score = score;
		}
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * Snapshots visible interface geometry used by chatbox and side-row collision handling.
 */
public final class InterfaceBounds {
	private final Rectangle canvas;
	private final List<Rectangle> obstacles;
	private final List<Obstacle> identifiedObstacles;
	private final List<Rectangle> foregrounds;

	private InterfaceBounds(Rectangle canvas, List<Rectangle> obstacles, List<Obstacle> identifiedObstacles, List<Rectangle> foregrounds) {
		this.canvas = canvas;
		this.obstacles = Collections.unmodifiableList(obstacles);
		this.identifiedObstacles = Collections.unmodifiableList(identifiedObstacles);
		this.foregrounds = Collections.unmodifiableList(foregrounds);
	}

	/**
	 * ================================================================
	 * CAPTURE
	 * ================================================================
	 */
	static InterfaceBounds capture(Client client) {
		return capture(client, null);
	}

	static InterfaceBounds capture(Client client, Overrides overrides) {
		final Rectangle canvas = new Rectangle(0, 0, Math.max(0, client.getCanvasWidth()), Math.max(0, client.getCanvasHeight()));
		final List<Rectangle> obstacles = new ArrayList<>(8);
		final List<Obstacle> identifiedObstacles = new ArrayList<>(8);
		final List<Rectangle> foregrounds = new ArrayList<>(2);

		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.CLASSIC_SIDE_MENU, canvas,
					client.getWidget(InterfaceID.ToplevelOsrsStretch.SIDE_MENU));
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.CLASSIC_MAP, canvas,
					client.getWidget(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER));
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.CLASSIC_ORBS, canvas,
					client.getWidget(InterfaceID.ToplevelOsrsStretch.ORBS));
			addMountedObstacle(client, identifiedObstacles, foregrounds, ObstacleKey.CLASSIC_MAINMODAL, canvas,
					InterfaceID.ToplevelOsrsStretch.MAINMODAL);
			addMountedObstacle(client, identifiedObstacles, foregrounds, ObstacleKey.CLASSIC_FLOATER, canvas,
					InterfaceID.ToplevelOsrsStretch.FLOATER);
		} else if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.MODERN_SIDE_BACKGROUND, canvas,
					client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND));
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.MODERN_SIDE_STATIC, canvas,
					client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER),
					overrides != null ? overrides.modernSideStatic : null);
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.MODERN_SIDE_MOVABLE, canvas,
					client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER),
					overrides != null ? overrides.modernSideMovable : null);
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.MODERN_SIDE_CONTAINER, canvas,
					client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER),
					overrides != null ? overrides.modernSideContainer : null);
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.MODERN_MAP, canvas,
					client.getWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER));
			addObstacle(obstacles, identifiedObstacles, ObstacleKey.MODERN_ORBS, canvas,
					client.getWidget(InterfaceID.ToplevelPreEoc.ORBS));
			addMountedObstacle(client, identifiedObstacles, foregrounds, ObstacleKey.MODERN_MAINMODAL, canvas,
					InterfaceID.ToplevelPreEoc.MAINMODAL);
			addMountedObstacle(client, identifiedObstacles, foregrounds, ObstacleKey.MODERN_FLOATER, canvas,
					InterfaceID.ToplevelPreEoc.FLOATER);
		}

		return new InterfaceBounds(canvas, obstacles, identifiedObstacles, foregrounds);
	}

	Rectangle getCanvas() {
		return canvas;
	}

	List<Rectangle> getObstacles() {
		return obstacles;
	}

	List<Obstacle> getIdentifiedObstacles() {
		return identifiedObstacles;
	}

	boolean intersectsForeground(Rectangle bounds) {
		if (bounds == null || bounds.isEmpty()) {
			return false;
		}

		for (Rectangle foreground : foregrounds) {
			if (bounds.intersects(foreground)) {
				return true;
			}
		}

		return false;
	}

	/**
	 * ================================================================
	 * GEOMETRY HELPERS
	 * ================================================================
	 */
	public static long geometryFingerprint(Client client) {
		if (client == null) {
			return 0L;
		}

		final InterfaceBounds snapshot = capture(client);
		long hash = 17L;
		hash = mix(hash, client.getTopLevelInterfaceId());
		hash = mix(hash, snapshot.canvas);

		for (Obstacle obstacle : snapshot.identifiedObstacles) {
			hash = mix(hash, obstacle.key.ordinal());
			hash = mix(hash, obstacle.bounds);
		}

		return hash;
	}

	private static long mix(long hash, Rectangle bounds) {
		if (bounds == null) {
			return mix(hash, 0);
		}

		hash = mix(hash, bounds.x);
		hash = mix(hash, bounds.y);
		hash = mix(hash, bounds.width);
		return mix(hash, bounds.height);
	}

	private static long mix(long hash, int value) {
		return hash * 31L + value;
	}

	/*
	 * Returns rendered canvas-space widget bounds.
	 */
	public static Rectangle liveBounds(Widget widget) {
		if (widget == null || widget.isHidden()) {
			return null;
		}

		final Rectangle bounds = widget.getBounds();
		return bounds != null && bounds.width > 0 && bounds.height > 0
				? new Rectangle(bounds)
				: null;
	}

	/**
	 * ================================================================
	 * OBSTACLE COLLECTION
	 * ================================================================
	 */
	private static void addMountedObstacle(Client client, List<Obstacle> identifiedObstacles,
			List<Rectangle> foregrounds, ObstacleKey key, Rectangle canvas, int componentId) {
		if (client.getComponentTable() == null || client.getComponentTable().get(componentId) == null) {
			return;
		}

		final Widget mount = client.getWidget(componentId);
		final Rectangle bounds = mountedContentBounds(mount, canvas);
		if (bounds == null || bounds.isEmpty()) {
			return;
		}

		final Rectangle foreground = new Rectangle(bounds);
		foregrounds.add(foreground);
		identifiedObstacles.add(new Obstacle(key, foreground));
	}

	private static Rectangle mountedContentBounds(Widget mount, Rectangle canvas) {
		if (mount == null || mount.isHidden()) {
			return null;
		}

		final Rectangle mountBounds = liveBounds(mount);
		if (mountBounds == null) {
			return null;
		}

		final Rectangle clip = mountBounds.intersection(canvas);
		if (clip.isEmpty()) {
			return null;
		}

		Rectangle bounds = null;
		for (Widget root : mount.getNestedChildren()) {
			bounds = union(bounds, visibleContentBounds(root, clip));
		}

		return bounds;
	}

	private static Rectangle visibleContentBounds(Widget widget, Rectangle clip) {
		if (widget == null || widget.isHidden() || clip == null || clip.isEmpty()) {
			return null;
		}

		final Rectangle widgetBounds = widget.getBounds();
		if (widgetBounds == null || widgetBounds.width <= 0 || widgetBounds.height <= 0) {
			return null;
		}

		final Rectangle visible = widgetBounds.intersection(clip);
		if (visible.isEmpty()) {
			return null;
		}

		Rectangle bounds = widget.getType() != WidgetType.LAYER && widget.getOpacity() != 255
				? new Rectangle(visible)
				: null;

		for (Widget child : widget.getStaticChildren()) {
			bounds = union(bounds, visibleContentBounds(child, visible));
		}

		for (Widget child : widget.getDynamicChildren()) {
			bounds = union(bounds, visibleContentBounds(child, visible));
		}

		for (Widget child : widget.getNestedChildren()) {
			bounds = union(bounds, visibleContentBounds(child, visible));
		}

		return bounds;
	}

	private static Rectangle union(Rectangle first, Rectangle second) {
		if (second == null || second.isEmpty()) {
			return first;
		}

		if (first == null) {
			return new Rectangle(second);
		}

		first.add(second);
		return first;
	}

	private static void addObstacle(List<Rectangle> obstacles, List<Obstacle> identifiedObstacles,
			ObstacleKey key, Rectangle canvas, Widget widget) {
		addObstacle(obstacles, identifiedObstacles, key, canvas, widget, null);
	}

	private static void addObstacle(List<Rectangle> obstacles, List<Obstacle> identifiedObstacles, ObstacleKey key,
			Rectangle canvas, Widget widget, Rectangle overrideBounds) {
		final Rectangle bounds = overrideBounds != null
				? new Rectangle(overrideBounds)
				: liveBounds(widget);
		if (bounds == null || !bounds.intersects(canvas)) {
			return;
		}

		final Rectangle captured = new Rectangle(bounds);
		obstacles.add(captured);
		identifiedObstacles.add(new Obstacle(key, captured));
	}

	/**
	 * ================================================================
	 * STATE TYPES
	 * ================================================================
	 */
	public static final class Overrides {
		private final Rectangle modernSideStatic;
		private final Rectangle modernSideMovable;
		private final Rectangle modernSideContainer;

		public Overrides(Rectangle modernSideStatic, Rectangle modernSideMovable, Rectangle modernSideContainer) {
			this.modernSideStatic = copy(modernSideStatic);
			this.modernSideMovable = copy(modernSideMovable);
			this.modernSideContainer = copy(modernSideContainer);
		}

		private static Rectangle copy(Rectangle bounds) {
			return bounds != null ? new Rectangle(bounds) : null;
		}
	}

	enum ObstacleKey {
		CLASSIC_SIDE_MENU,
		CLASSIC_MAP,
		CLASSIC_ORBS,
		CLASSIC_MAINMODAL,
		CLASSIC_FLOATER,
		MODERN_SIDE_BACKGROUND,
		MODERN_SIDE_STATIC,
		MODERN_SIDE_MOVABLE,
		MODERN_SIDE_CONTAINER,
		MODERN_MAP,
		MODERN_ORBS,
		MODERN_MAINMODAL,
		MODERN_FLOATER
	}

	static final class Obstacle {
		private final ObstacleKey key;
		private final Rectangle bounds;

		private Obstacle(ObstacleKey key, Rectangle bounds) {
			this.key = key;
			this.bounds = new Rectangle(bounds);
		}

		ObstacleKey getKey() {
			return key;
		}

		Rectangle getBounds() {
			return new Rectangle(bounds);
		}
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;

import net.runelite.api.Client;

/*
 * Resolves split-PM width against the interfaces that overlap its own
 * screen position. The configured/inherited width remains the maximum.
 */
final class PrivateChatBounds {
	private static final int MIN_WIDTH = 200;

	private PrivateChatBounds() {
		/*
		 * PRIVATE CHAT BOUNDS
		 */
	}

	static int resolveWidth(Client client, Rectangle surfaceBounds, int desiredWidth) {
		if (client == null || surfaceBounds == null || desiredWidth <= 0) {
			return Math.max(MIN_WIDTH, desiredWidth);
		}

		final InterfaceBounds interfaces = InterfaceBounds.capture(client);
		final Rectangle canvas = interfaces.getCanvas();
		final int anchorX = surfaceBounds.x;
		final int availableWidth = canvas.x + canvas.width - anchorX;
		int effectiveWidth = constrain(desiredWidth, availableWidth);

		/*
		 * Preserves the PM surface's left edge and constrains only against interfaces to its right.
		 */
		for (Rectangle obstacle : interfaces.getObstacles()) {
			if (!intersectsVertically(surfaceBounds, obstacle) || obstacle.x <= anchorX || obstacle.x >= anchorX + effectiveWidth) {
				continue;
			}

			effectiveWidth = Math.max(MIN_WIDTH, obstacle.x - anchorX);
		}

		return effectiveWidth;
	}

	private static boolean intersectsVertically(Rectangle surfaceBounds, Rectangle obstacle) {
		final int surfaceHeight = Math.max(1, surfaceBounds.height);
		final int surfaceBottom = surfaceBounds.y + surfaceHeight;
		final int obstacleBottom = obstacle.y + obstacle.height;
		return surfaceBounds.y < obstacleBottom && surfaceBottom > obstacle.y;
	}

	private static int constrain(int desiredWidth, int availableWidth) {
		if (availableWidth <= 0) {
			return Math.max(MIN_WIDTH, desiredWidth);
		}

		return Math.max(MIN_WIDTH, Math.min(desiredWidth, availableWidth));
	}
}

package com.bigboldchat.layout;

import com.bigboldchat.Configurations;

import java.awt.Rectangle;

import com.bigboldchat.overlay.PrivateChatOverlay;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.client.ui.overlay.OverlayPosition;

/*
 * Owns split-PM external placement and width without replacing RuneScape's
 * font-dependent row construction.
 */
public final class PrivateChatLayout {
	private static final String CONFIG_GROUP = "bigboldchat";

	private static final String WIDTH_KEY = "splitPmWidth";
	private static final String WIDTH_OVERRIDE_KEY = "splitPmWidthOverride";
	private static final String CHATBOX_WIDTH_KEY = "chatboxWidth";

	private static final int MIN_WIDTH = 200;
	private static final int SURFACE_TOP_PADDING = 4;
	private static final int SURFACE_BOTTOM_PADDING = 2;

	/*
	 * RuneLite currently exposes no ScriptID constants for the native top-level
	 * relayout or chat_onchattransmit scripts. Observe them only; ChatXL never
	 * executes either script directly.
	 */
	private static final int TOPLEVEL_LAYOUT_SCRIPT = 1972;
	private static final int CHAT_ON_CHAT_TRANSMIT_SCRIPT = 663;

	private final Client client;
	private final Configurations config;
	private final ConfigManager configManager;
	private final PrivateChatOverlay overlay;

	private Widget forcedHost;
	private Widget shiftedContent;
	private int nativeContentScrollY;
	private int appliedContentShiftY;
	private Widget sizedHost;
	private int nativeOriginalWidth;
	private int appliedOriginalWidth;
	private boolean nativeWidthCaptured;

	/*
	 * Split-PM width inheritance is explicit state rather than inferred from the
	 * visible numeric value. This lets an inherited value mirror Chatbox Width
	 * while a user-entered value remains independent until Split-PM Width is reset.
	 */
	private boolean widthOverrideInitialized;
	private boolean widthOverridden;

	/*
	 * Width rewrapping changes the visible PM block height.
	 */
	private int stableCollisionHeight;
	private int stableDesiredWidth;
	private boolean nativeLayoutDirty;

	public PrivateChatLayout(
			Client client,
			Configurations config,
			ConfigManager configManager,
			PrivateChatOverlay overlay) {
		this.client = client;
		this.config = config;
		this.configManager = configManager;
		this.overlay = overlay;
	}

	public Result sync() {
		ensureWidthOverrideInitialized();

		final Widget pmHost = activePmHost();
		final Widget chatSlot = activeChatSlot();
		if (pmHost == null || chatSlot == null) {
			overlay.setNaturalBounds(null);
			restoreNative();
			return Result.NO_CHANGE;
		}

		if (forcedHost != null && forcedHost != pmHost) {
			restoreForcedHost();
		}
		if (sizedHost != null && sizedHost != pmHost) {
			restoreSizedHost();
		}

		final Widget pmChat = client.getWidget(InterfaceID.PM_CHAT, 0);
		if (shiftedContent != null && shiftedContent != pmChat) {
			restoreContentShift();
		}

		final Rectangle contentBounds = visiblePmBounds();
		if (contentBounds == null) {
			overlay.setNaturalBounds(null);
			restoreContentShift();
			restoreForcedHost();
			restoreSizedHost();
			stableCollisionHeight = 0;
			stableDesiredWidth = 0;
			return Result.NO_CHANGE;
		}

		final int currentOffsetX = pmHost.getRelativeX() - pmHost.getOriginalX();
		final int currentOffsetY = pmHost.getRelativeY() - pmHost.getOriginalY();
		final int currentContentShiftY = shiftedContent == pmChat
				? appliedContentShiftY
				: 0;
		final Rectangle baseContentBounds = contentBounds == null
				? null
				: translated(
						contentBounds,
						-currentOffsetX,
						-currentOffsetY - currentContentShiftY);

		/*
		 * RuneLite's BOTTOM_LEFT snap corner is the green anchor above the
		 * chatbox. When split PM is snapped there, follow the chatbox translation
		 * directly rather than deriving Y from a reflowing overlay rectangle.
		 */
		final boolean chatboxAnchored = overlay.getPreferredPosition() == OverlayPosition.BOTTOM_LEFT;
		final Offset target = overlay.isManuallyPositioned()
				&& !chatboxAnchored
				&& baseContentBounds != null
				? manualOffset(baseContentBounds)
				: chatboxOffset(chatSlot);

		final Rectangle expectedContentBounds = baseContentBounds == null
				? null
				: translated(baseContentBounds, target.x, target.y);
		final int desiredWidth = desiredWidth(chatSlot);
		final Rectangle collisionBounds = stableCollisionBounds(pmHost, expectedContentBounds, desiredWidth);
		final int effectiveWidth = collisionBounds == null
				? desiredWidth
				: PrivateChatBounds.resolveWidth(client, collisionBounds, desiredWidth);
		final boolean widthChanged = setEffectiveWidth(pmHost, effectiveWidth);

		if (expectedContentBounds != null && effectiveWidth >= desiredWidth) {
			stableCollisionHeight = Math.max(1, expectedContentBounds.height);
			stableDesiredWidth = desiredWidth;
		}

		if (widthChanged && pmChat != null) {
			pmChat.revalidate();
		}

		/*
		 * Native split-PM rows are built upward from PM_CHAT and can therefore occupy
		 * negative Y coordinates relative to PM_CHAT. That works while the native
		 * clipping hierarchy remains above them, but a detached PM_CONTAINER can be
		 * moved below those rows after a top-level canvas relayout. The RuneLite
		 * overlay then remains visible while the game clips the actual PM text.
		 *
		 * Keep PM_CHAT at its native geometry. Move PM_CONTAINER upward only enough
		 * to contain the requested visible row surface, then compensate the children
		 * with a negative PM_CHAT scroll value. The rows stay at the overlay location
		 * while both native clipping containers begin at or above the visible text.
		 */
		applyClippingSafePlacement(pmHost, pmChat, target, expectedContentBounds);

		/*
		 * Width rewraps and newly-arrived PMs can change the real row union after
		 * the first placement calculation. Reconcile once against those live rows
		 * so a newly-grown top line cannot escape either native clipping envelope.
		 * The second pass is idempotent when the first placement already contains
		 * the complete visible row surface.
		 */
		Rectangle finalContentBounds = visiblePmBounds();
		if (finalContentBounds != null) {
			applyClippingSafePlacement(pmHost, pmChat, target, finalContentBounds);
			finalContentBounds = visiblePmBounds();
		}

		/*
		 * The RuneLite drag surface should match the actual visible PM stack, not a
		 * fixed or predicted height. Keep its width constrained to effectiveWidth so
		 * an unbreakable native word cannot create an oversized horizontal handle.
		 */
		final Rectangle overlayBounds = surfaceBounds(finalContentBounds, effectiveWidth);
		overlay.setNaturalBounds(overlayBounds);

		return widthChanged
				? Result.WIDTH_CHANGED
				: Result.NO_CHANGE;
	}

	public void onScriptPostFired(ScriptPostFired event) {
		if (event == null) {
			return;
		}

		final int scriptId = event.getScriptId();
		if (scriptId == TOPLEVEL_LAYOUT_SCRIPT
				|| scriptId == CHAT_ON_CHAT_TRANSMIT_SCRIPT
				|| scriptId == ScriptID.SPLITPM_CHANGED) {
			nativeLayoutDirty = true;
		}
	}

	public void reconcileAfterClientTick() {
		if (!nativeLayoutDirty) {
			return;
		}

		nativeLayoutDirty = false;

		final Widget pmHost = activePmHost();
		final Widget pmChat = client.getWidget(InterfaceID.PM_CHAT, 0);
		final Rectangle contentBounds = visiblePmBounds();
		final Rectangle overlayBounds = overlay.getBounds();
		if (pmHost == null
				|| pmChat == null
				|| contentBounds == null
				|| overlayBounds == null
				|| overlayBounds.isEmpty()) {
			return;
		}

		/*
		 * ClientTick runs client scripts before PostClientTick. Top-level relayout
		 * can therefore fire 1972 several times and expose multiple intermediate PM
		 * geometries during one cycle. Only reconcile here, after that whole native
		 * script batch has completed, so ChatXL never fights a transient 1972 state.
		 *
		 * Recover the rows' native vertical offset from the final geometry, then
		 * reassert the existing movable-overlay placement before the next frame.
		 */
		final int nativeRowOffsetY = contentBounds.y
				- pmHost.getRelativeY()
				+ pmChat.getScrollY()
				- nativeContentScrollY;
		final int desiredContentY = overlayBounds.y + SURFACE_TOP_PADDING;
		final int contentShiftY = Math.max(
				0,
				SURFACE_TOP_PADDING - nativeRowOffsetY);
		final int targetHostY = desiredContentY
				- nativeRowOffsetY
				- contentShiftY;

		/*
		 * Horizontal PM rows do not use the vertical scroll compensation. Preserve
		 * their final native offset while translating the host so the row union
		 * remains aligned with the movable overlay.
		 */
		final int targetHostX = pmHost.getRelativeX()
				+ overlayBounds.x
				- contentBounds.x;

		applyContentShift(pmChat, contentShiftY);
		applyOffset(
				pmHost,
				targetHostX - pmHost.getOriginalX(),
				targetHostY - pmHost.getOriginalY());

		final Rectangle finalContentBounds = visiblePmBounds();
		if (finalContentBounds != null) {
			overlay.setNaturalBounds(surfaceBounds(
					finalContentBounds,
					Math.min(pmHost.getWidth(), finalContentBounds.width)));
		}
	}

	public void restoreNative() {
		restoreContentShift();
		restoreForcedHost();
		restoreSizedHost();
		stableCollisionHeight = 0;
		stableDesiredWidth = 0;
		nativeLayoutDirty = false;
	}

	public void onConfigChanged(ConfigChanged event) {
		if (event == null || !CONFIG_GROUP.equals(event.getGroup())) {
			return;
		}

		ensureWidthOverrideInitialized();

		if (CHATBOX_WIDTH_KEY.equals(event.getKey())) {
			if (!widthOverridden) {
				syncInheritedWidthConfiguration();
			}
			return;
		}

		if (!WIDTH_KEY.equals(event.getKey())) {
			return;
		}

		final String storedWidth = configManager.getConfiguration(CONFIG_GROUP, WIDTH_KEY);
		if (storedWidth == null) {
			setWidthOverridden(false);
			syncInheritedWidthConfiguration();
			return;
		}

		/*
		 * Programmatic mirroring writes the same configured width as Chatbox Width
		 * and must not turn inheritance into an override. Once an override is
		 * already active, even matching Chatbox Width remains intentionally manual.
		 */
		if (!widthOverridden && parseWidth(storedWidth) == config.chatboxWidth()) {
			return;
		}

		setWidthOverridden(true);
	}

	private int desiredWidth(Widget chatSlot) {
		if (widthOverridden) {
			return Math.max(MIN_WIDTH, config.splitPmWidth());
		}

		/*
		 * Inherited mode mirrors the chatbox's live effective width, not merely the
		 * configured maximum. This keeps an anchored PM surface synchronized when
		 * the chatbox itself is temporarily narrowed by interface collision.
		 */
		return Math.max(MIN_WIDTH, chatSlot.getWidth());
	}

	private void ensureWidthOverrideInitialized() {
		if (widthOverrideInitialized) {
			return;
		}

		final String storedOverride = configManager.getConfiguration(CONFIG_GROUP, WIDTH_OVERRIDE_KEY);
		widthOverridden = storedOverride != null && Boolean.parseBoolean(storedOverride);
		widthOverrideInitialized = true;

		/*
		 * Treat this state as inherited and mirror the configured Chatbox Width.
		 */
		if (storedOverride == null) {
			setWidthOverridden(false);
			syncInheritedWidthConfiguration();
		}
	}

	private void setWidthOverridden(boolean overridden) {
		widthOverridden = overridden;
		configManager.setConfiguration(CONFIG_GROUP, WIDTH_OVERRIDE_KEY, overridden);
	}

	private void syncInheritedWidthConfiguration() {
		final int chatboxWidth = config.chatboxWidth();
		final String storedWidth = configManager.getConfiguration(CONFIG_GROUP, WIDTH_KEY);
		if (parseWidth(storedWidth) == chatboxWidth) {
			return;
		}

		configManager.setConfiguration(CONFIG_GROUP, WIDTH_KEY, chatboxWidth);
	}

	private static int parseWidth(String value) {
		if (value == null || value.isEmpty()) {
			return -1;
		}

		try {
			return Integer.parseInt(value);
		} catch (NumberFormatException ignored) {
			return -1;
		}
	}

	private Rectangle stableCollisionBounds(
			Widget pmHost,
			Rectangle expectedContentBounds,
			int desiredWidth) {
		if (pmHost == null || expectedContentBounds == null) {
			return null;
		}

		final int currentHeight = Math.max(1, expectedContentBounds.height);
		if (stableCollisionHeight <= 0
				|| stableDesiredWidth != desiredWidth
				|| pmHost.getWidth() >= desiredWidth) {
			stableCollisionHeight = currentHeight;
			stableDesiredWidth = desiredWidth;
		}

		/*
		 * Width wrapping may make the visible PM block taller. Use the last
		 * unconstrained height while solving collision so our own rewrap cannot
		 * make an obstacle disappear on the next frame and create a width/position
		 * oscillation. Bottom-left chatbox anchoring preserves the PM's lower edge;
		 * freely detached overlays preserve their top edge.
		 */
		final boolean bottomAnchored = !overlay.isManuallyPositioned()
				|| overlay.getPreferredPosition() == OverlayPosition.BOTTOM_LEFT;
		final int y = bottomAnchored
				? expectedContentBounds.y + expectedContentBounds.height - stableCollisionHeight
				: expectedContentBounds.y;

		return new Rectangle(
				expectedContentBounds.x,
				y,
				desiredWidth,
				stableCollisionHeight);
	}

	private Offset chatboxOffset(Widget chatSlot) {
		final Rectangle bounds = chatSlot.getBounds();
		if (bounds == null) {
			return Offset.ZERO;
		}

		/*
		 * Use the chatbox bottom-left corner to isolate external movement from
		 * ChatXL's temporary width/height changes. A normal resizable chatbox ends
		 * at the canvas bottom-left regardless of its current constrained size.
		 */
		return new Offset(
				bounds.x,
				bounds.y + bounds.height - client.getCanvasHeight());
	}

	private Offset manualOffset(Rectangle baseContentBounds) {
		final Rectangle overlayBounds = overlay.getBounds();
		return new Offset(
				overlayBounds.x - baseContentBounds.x,
				overlayBounds.y + SURFACE_TOP_PADDING - baseContentBounds.y);
	}

	private void applyClippingSafePlacement(
			Widget pmHost,
			Widget pmChat,
			Offset target,
			Rectangle expectedContentBounds) {
		if (pmChat == null || expectedContentBounds == null) {
			restoreContentShift();
			applyOffset(pmHost, target.x, target.y);
			return;
		}

		final int requestedHostY = pmHost.getOriginalY() + target.y;

		/*
		 * Width remains owned by PM_CONTAINER and horizontal placement remains
		 * unchanged. The currently-proven failure is vertical: the visible PM rows
		 * can sit above both native clipping containers after the canvas shrinks.
		 */
		final int envelopeY = Math.min(
				requestedHostY,
				expectedContentBounds.y - SURFACE_TOP_PADDING);
		final int contentShiftY = requestedHostY - envelopeY;

		applyContentShift(pmChat, contentShiftY);
		applyOffset(
				pmHost,
				target.x,
				envelopeY - pmHost.getOriginalY());
	}

	private void applyContentShift(Widget pmChat, int shiftY) {
		if (shiftedContent != null && shiftedContent != pmChat) {
			restoreContentShift();
		}

		if (shiftY <= 0) {
			restoreContentShift();
			return;
		}

		if (shiftedContent != pmChat) {
			shiftedContent = pmChat;
			nativeContentScrollY = pmChat.getScrollY();
		}

		final int targetScrollY = nativeContentScrollY - shiftY;
		if (pmChat.getScrollY() != targetScrollY) {
			pmChat.setScrollY(targetScrollY);
		}

		appliedContentShiftY = shiftY;
	}

	private void applyOffset(Widget pmHost, int offsetX, int offsetY) {
		if (forcedHost != null && forcedHost != pmHost) {
			restoreForcedHost();
		}

		if (offsetX == 0 && offsetY == 0 && !overlay.isManuallyPositioned()) {
			restoreForcedHost();
			return;
		}

		final int targetX = pmHost.getOriginalX() + offsetX;
		final int targetY = pmHost.getOriginalY() + offsetY;
		if (forcedHost == pmHost
				&& pmHost.getRelativeX() == targetX
				&& pmHost.getRelativeY() == targetY) {
			return;
		}

		pmHost.setForcedPosition(targetX, targetY);
		forcedHost = pmHost;
	}

	private boolean setEffectiveWidth(Widget pmHost, int width) {
		if (pmHost == null || width <= 0 || pmHost.getWidth() == width) {
			return false;
		}

		captureNativeWidth(pmHost);
		final int targetOriginalWidth;
		switch (pmHost.getWidthMode()) {
			case WidgetSizeMode.ABSOLUTE:
				targetOriginalWidth = width;
				break;
			case WidgetSizeMode.MINUS:
				final Widget parent = pmHost.getParent();
				if (parent == null) {
					return false;
				}

				targetOriginalWidth = Math.max(0, parent.getWidth() - width);
				break;
			case WidgetSizeMode.ABSOLUTE_16384THS:
				final Widget proportionalParent = pmHost.getParent();
				if (proportionalParent == null || proportionalParent.getWidth() <= 0) {
					return false;
				}

				targetOriginalWidth = Math.max(0, Math.min(16384,
						(int) Math.round(width * 16384.0 / proportionalParent.getWidth())));
				break;
			default:
				return false;
		}

		if (pmHost.getOriginalWidth() == targetOriginalWidth) {
			return false;
		}

		if (nativeWidthCaptured && pmHost.getOriginalWidth() != appliedOriginalWidth) {
			nativeOriginalWidth = pmHost.getOriginalWidth();
		}

		pmHost.setOriginalWidth(targetOriginalWidth);
		pmHost.revalidate();
		appliedOriginalWidth = targetOriginalWidth;
		return true;
	}

	private void captureNativeWidth(Widget pmHost) {
		if (sizedHost == pmHost && nativeWidthCaptured) {
			return;
		}

		if (sizedHost != null && sizedHost != pmHost) {
			restoreSizedHost();
		}

		sizedHost = pmHost;
		nativeOriginalWidth = pmHost.getOriginalWidth();
		appliedOriginalWidth = nativeOriginalWidth;
		nativeWidthCaptured = true;
	}

	private void restoreContentShift() {
		if (shiftedContent == null) {
			nativeContentScrollY = 0;
			appliedContentShiftY = 0;
			return;
		}

		if (shiftedContent.getScrollY() != nativeContentScrollY) {
			shiftedContent.setScrollY(nativeContentScrollY);
		}

		shiftedContent = null;
		nativeContentScrollY = 0;
		appliedContentShiftY = 0;
	}

	private void restoreForcedHost() {
		if (forcedHost == null) {
			return;
		}

		forcedHost.setForcedPosition(-1, -1);
		forcedHost.revalidate();
		forcedHost = null;
	}

	private void restoreSizedHost() {
		if (sizedHost == null || !nativeWidthCaptured) {
			return;
		}

		if (sizedHost.getOriginalWidth() == appliedOriginalWidth
				&& sizedHost.getOriginalWidth() != nativeOriginalWidth) {
			sizedHost.setOriginalWidth(nativeOriginalWidth);
			sizedHost.revalidate();
		}

		sizedHost = null;
		nativeOriginalWidth = 0;
		appliedOriginalWidth = 0;
		nativeWidthCaptured = false;
	}

	private Rectangle visiblePmBounds() {
		final Widget pmChat = client.getWidget(InterfaceID.PM_CHAT, 0);
		if (pmChat == null || pmChat.isHidden()) {
			return null;
		}

		Rectangle bounds = null;
		for (Widget child : pmChat.getDynamicChildren()) {
			bounds = union(bounds, visibleLiveBounds(child));
		}

		bounds = union(bounds, visibleLiveBounds(client.getWidget(InterfaceID.PmChat.PM1)));
		bounds = union(bounds, visibleLiveBounds(client.getWidget(InterfaceID.PmChat.PM2)));
		bounds = union(bounds, visibleLiveBounds(client.getWidget(InterfaceID.PmChat.PM3)));
		bounds = union(bounds, visibleLiveBounds(client.getWidget(InterfaceID.PmChat.PM4)));
		bounds = union(bounds, visibleLiveBounds(client.getWidget(InterfaceID.PmChat.PM5)));
		return bounds;
	}

	private Widget activeChatSlot() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.CHAT_CONTAINER);
		}
		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return client.getWidget(InterfaceID.ToplevelPreEoc.CHAT_CONTAINER);
		}
		return null;
	}

	private Widget activePmHost() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.PM_CONTAINER);
		}
		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return client.getWidget(InterfaceID.ToplevelPreEoc.PM_CONTAINER);
		}
		return null;
	}

	private static Rectangle visibleLiveBounds(Widget widget) {
		if (widget == null || widget.isHidden() || widget.getWidth() <= 0 || widget.getHeight() <= 0) {
			return null;
		}

		/*
		 * getBounds() can retain the previous on-canvas PM coordinates after the
		 * externally-forced host has moved. Detached placement derives a native
		 * content origin by subtracting the host offset, so mixing those stale
		 * bounds with the live host offset compounds the translation every frame.
		 * Build the current canvas position from resolved relative coordinates and
		 * parent scroll offsets instead so both sides use the same geometry state.
		 */
		int x = widget.getRelativeX();
		int y = widget.getRelativeY();
		for (Widget parent = widget.getParent(); parent != null; parent = parent.getParent()) {
			x += parent.getRelativeX() - parent.getScrollX();
			y += parent.getRelativeY() - parent.getScrollY();
		}

		return new Rectangle(x, y, widget.getWidth(), widget.getHeight());
	}

	private static Rectangle union(Rectangle first, Rectangle second) {
		if (second == null || second.isEmpty()) {
			return first;
		}
		if (first == null) {
			return new Rectangle(second);
		}

		first.add(second);
		return first;
	}

	private static Rectangle surfaceBounds(Rectangle contentBounds, int width) {
		if (contentBounds == null || contentBounds.isEmpty() || width <= 0) {
			return null;
		}

		return new Rectangle(
				contentBounds.x,
				contentBounds.y - SURFACE_TOP_PADDING,
				width,
				contentBounds.height + SURFACE_TOP_PADDING + SURFACE_BOTTOM_PADDING);
	}

	private static Rectangle translated(Rectangle bounds, int x, int y) {
		final Rectangle translated = new Rectangle(bounds);
		translated.translate(x, y);
		return translated;
	}

	public static final class Result {
		private static final Result NO_CHANGE = new Result(false);
		private static final Result WIDTH_CHANGED = new Result(true);

		private final boolean widthChanged;

		private Result(boolean widthChanged) {
			this.widthChanged = widthChanged;
		}

		public boolean isWidthChanged() {
			return widthChanged;
		}
	}

	private static final class Offset {
		private static final Offset ZERO = new Offset(0, 0);
		private final int x;
		private final int y;

		private Offset(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
}

package com.bigboldchat.layout;

import java.awt.Point;
import java.awt.Rectangle;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Owns plugin-managed layout changes to the Modern side container.
 */
public final class SideContainerLayout {
	private static final String STATIC_TABS_OVERLAY = "RESIZABLE_VIEWPORT_BOTTOM_LINE_TABS1";
	private static final String MOVABLE_TABS_OVERLAY = "RESIZABLE_VIEWPORT_BOTTOM_LINE_TABS2";
	private static final String INVENTORY_OVERLAY = "RESIZABLE_VIEWPORT_BOTTOM_LINE_INVENTORY_PARENT";
	private static final int MIN_ONE_ROW_OVERLAP = 1;
	private static final int MAX_ONE_ROW_OVERLAP = 37;
	private static final int INVENTORY_EDGE_TOLERANCE = 5;
	private static final int INVENTORY_HORIZONTAL_TOLERANCE = 5;
	private static final int CANVAS_EDGE_TOLERANCE = 5;

	private final Client client;
	private final OverlayManager overlayManager;
	private final CollisionManager collisionManager;

	private boolean nativeLayoutRunning;
	private boolean gameStateSuspended;
	private boolean canvasResizeInProgress;
	private volatile boolean pluginTwoRows;
	private volatile boolean staticRowOwned;
	private volatile boolean movableRowOwned;
	private boolean oneRowKnown;
	private int staticRowX;
	private int staticRowY;
	private int movableRowX;
	private int movableRowY;
	private Rectangle staticRowBounds;
	private Rectangle movableRowBounds;
	private Rectangle containerRowBounds;
	private volatile InventoryAttachment rowInventoryAttachment = InventoryAttachment.NONE;
	private int rowCanvasWidth;
	private int rowCanvasHeight;
	private boolean canvasRebasePending;
	private CollisionManager.Side splitSide = CollisionManager.Side.NONE;
	private volatile VerticalSplit verticalSplit = VerticalSplit.UP;
	private CollisionManager.Source collisionSource = CollisionManager.Source.NONE;
	private OverlayState staticOverlayState;
	private OverlayState movableOverlayState;
	private volatile OverlayState inventoryOverlayState;
	private boolean inventoryForcedPosition;
	private volatile boolean inventoryUserOverride;
	private volatile Point inventoryOwnedTarget;
	private volatile Point inventoryGuardLocation;

	public SideContainerLayout(Client client) {
		this(client, null);
	}

	public SideContainerLayout(Client client, OverlayManager overlayManager) {
		this(client, overlayManager, new CollisionManager(client));
	}

	SideContainerLayout(Client client, OverlayManager overlayManager, CollisionManager collisionManager) {
		this.client = client;
		this.overlayManager = overlayManager;
		this.collisionManager = collisionManager;
	}

	/**
	 * ================================================================
	 * LAYOUT LIFECYCLE
	 * ================================================================
	 */
	public void suspendForGameState() {
		if (!gameStateSuspended) {
			restoreNative();
		}

		gameStateSuspended = true;
		nativeLayoutRunning = false;
	}

	/*
	 * Starts a logged-in interface lifecycle from native side-row geometry.
	 */
	public void resumeForGameState() {
		restoreOverlays();
		gameStateSuspended = false;
		nativeLayoutRunning = false;
		pluginTwoRows = false;
		staticRowOwned = false;
		movableRowOwned = false;
		canvasResizeInProgress = false;
		splitSide = CollisionManager.Side.NONE;
		verticalSplit = VerticalSplit.UP;
		collisionSource = CollisionManager.Source.NONE;
		clearOneRow();
	}

	/*
	 * Suspends row-policy decisions while native interface layout is running.
	 */
	public void beginNativeLayout() {
		if (gameStateSuspended) {
			return;
		}

		if (!isModernLayout()) {
			reset();
			return;
		}

		final Widgets widgets = getWidgets();
		if (widgets != null && pluginTwoRows) {
			reconcileRowDrags(widgets);
		}

		if (pluginTwoRows && oneRowKnown) {
			canvasRebasePending = rebaseCanvasRows();
		}

		if (!pluginTwoRows && widgets != null) {
			if (canCaptureRow(widgets)) {
				captureOneRow(widgets);
			} else {
				clearOneRow();
			}
		}

		nativeLayoutRunning = true;
	}

	/*
	 * Reconciles captured side-row geometry after native interface layout completes.
	 */
	public Result endNativeLayout() {
		if (gameStateSuspended) {
			return Result.NONE;
		}

		nativeLayoutRunning = false;

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			canvasRebasePending = false;
			return Result.NONE;
		}

		if (canvasRebasePending && pluginTwoRows) {
			captureRowOriginals(widgets);
		}
		canvasRebasePending = false;

		if (pluginTwoRows) {
			reconcileRowDrags(widgets);
			return pluginTwoRows
					? reassertOwnedRows(widgets, splitSide, collisionSource)
					: Result.NONE;
		}

		if (canCaptureRow(widgets)) {
			captureOneRow(widgets);
		} else {
			clearOneRow();
		}

		return Result.NONE;
	}

	/*
	 * Reapplies owned two-row geometry without reevaluating collisions.
	 */
	public Result reassertOwnedLayout() {
		if (gameStateSuspended || nativeLayoutRunning || !pluginTwoRows || splitSide == CollisionManager.Side.NONE) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			return Result.NONE;
		}

		reconcileRowDrags(widgets);
		if (!pluginTwoRows) {
			return Result.NONE;
		}

		if (rebaseCanvasRows()) {
			captureRowOriginals(widgets);
		}

		return reassertOwnedRows(widgets, splitSide, collisionSource);
	}

	/*
	 * Reapplies owned row geometry before rendering without reevaluating collisions.
	 */
	public Result reconcileBeforeRender() {
		if (gameStateSuspended || nativeLayoutRunning || !pluginTwoRows || splitSide == CollisionManager.Side.NONE) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			return Result.NONE;
		}

		reconcileRowDrags(widgets);
		if (!pluginTwoRows) {
			return Result.NONE;
		}

		if (rebaseCanvasRows()) {
			captureRowOriginals(widgets);
		}

		return reassertOwnedRows(widgets, splitSide, collisionSource);
	}

	/*
	 * Reattaches the inventory to the currently owned row layout after an overlay reset.
	 */
	public Result reconcileInventoryReset() {
		if (gameStateSuspended || nativeLayoutRunning || !pluginTwoRows || !inventoryOffsetOwned()
				|| !inventoryUserOverride || splitSide == CollisionManager.Side.NONE) {
			return Result.NONE;
		}

		final boolean guardedReset = adoptInventoryGuard();
		if (!guardedReset && hasManualPlacement(INVENTORY_OVERLAY)) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			return Result.NONE;
		}

		if (!guardedReset && inventoryAttachment(InterfaceBounds.liveBounds(widgets.container),
				staticRowBounds, movableRowBounds) != rowInventoryAttachment) {
			return Result.NONE;
		}

		inventoryUserOverride = false;
		return reassertOwnedRows(widgets, splitSide, collisionSource);
	}

	/*
	 * Preserves the owned inventory position during an overlay reset.
	 */
	public boolean guardInventoryOverlayReset() {
		final OverlayState state = inventoryOverlayState;
		final Point target = inventoryOwnedTarget;
		if (!pluginTwoRows || !inventoryOffsetOwned() || !inventoryUserOverride || state == null || target == null
				|| state.overlay.getPreferredLocation() != null || state.overlay.getPreferredPosition() != null) {
			return false;
		}

		final Point guarded = new Point(target);
		state.overlay.setPreferredPosition(null);
		state.overlay.setPreferredLocation(guarded);
		state.overlay.getBounds().setLocation(guarded);
		inventoryGuardLocation = guarded;
		return true;
	}

	/*
	 * Translates captured side-row geometry to the current canvas.
	 */
	public Result onCanvasSizeChanged() {
		canvasResizeInProgress = true;
		if (gameStateSuspended || !isModernLayout() || !oneRowKnown) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			return Result.NONE;
		}

		if (pluginTwoRows) {
			reconcileRowDrags(widgets);
		}

		if (!rebaseCanvasRows()) {
			return pluginTwoRows
					? reassertOwnedRows(widgets, splitSide, collisionSource)
					: Result.NONE;
		}

		if (pluginTwoRows && splitSide != CollisionManager.Side.NONE) {
			return reassertOwnedRows(widgets, splitSide, collisionSource);
		}

		if (hasManualRows()) {
			return Result.NONE;
		}

		return reassertOneRow(widgets);
	}

	/*
	 * Ends the canvas-resize hold so normal row policy can resume.
	 */
	public void endCanvasResize() {
		canvasResizeInProgress = false;
	}

	/*
	 * Aligns a newly revealed inventory container to its established overlay position
	 * before collision relayout observes transient native geometry.
	 */
	public Result reconcileInventoryReveal() {
		if (gameStateSuspended || !isModernLayout() || overlayManager == null) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null || widgets.container.isSelfHidden()) {
			return Result.NONE;
		}

		final Overlay overlay = findOverlay(INVENTORY_OVERLAY);
		if (overlay == null || overlay.getPreferredLocation() == null && overlay.getPreferredPosition() == null) {
			return Result.NONE;
		}

		final Rectangle overlayBounds = overlay.getBounds();
		if (overlayBounds == null || overlayBounds.x == -1 && overlayBounds.y == -1 || overlayBounds.width != 0 || overlayBounds.height != 0) {
			return Result.NONE;
		}

		if (!forceWidgetPosition(widgets.container, overlayBounds.x, overlayBounds.y)) {
			return Result.NONE;
		}

		inventoryForcedPosition = true;
		widgets.container.revalidate();
		return new Result(1, 1);
	}

	/**
	 * ================================================================
	 * ROW POLICY
	 * ================================================================
	 */
	public Result apply(Widget slot, int configuredWidth, int configuredHeight) {
		if (gameStateSuspended || nativeLayoutRunning) {
			return Result.NONE;
		}

		if (slot == null || !isModernLayout()) {
			reset();
			return Result.NONE;
		}

		final Rectangle chatboxBounds = desiredBounds(slot, configuredWidth, configuredHeight);
		if (chatboxBounds == null || chatboxBounds.isEmpty()) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			return Result.NONE;
		}

		if (pluginTwoRows && rebaseCanvasRows()) {
			captureRowOriginals(widgets);
		}

		if (pluginTwoRows && reconcileRowDrags(widgets)) {
			return pluginTwoRows
					? reassertOwnedRows(widgets, splitSide, collisionSource)
					: Result.NONE;
		}

		if (canvasResizeInProgress) {
			if (pluginTwoRows && splitSide != CollisionManager.Side.NONE) {
				return reassertOwnedRows(widgets, splitSide, collisionSource);
			}

			if (oneRowKnown && !hasManualRows()) {
				return reassertOneRow(widgets);
			}

			return Result.NONE;
		}

		if (pluginTwoRows && hasPartialOwnership()) {
			return reassertOwnedRows(widgets, splitSide, collisionSource);
		}

		if (!pluginTwoRows) {
			if (!canCaptureRow(widgets)) {
				clearOneRow();
				return Result.NONE;
			}

			captureOneRow(widgets);
		}

		if (!oneRowKnown || staticRowBounds == null || movableRowBounds == null) {
			return Result.NONE;
		}

		final CollisionManager.Result collision =
				collisionManager.resolveSideRows(chatboxBounds, staticRowBounds, movableRowBounds, splitSide);

		if (!collision.needsTwoRows()) {
			return pluginTwoRows
					? applyOneRow(widgets)
					: Result.NONE;
		}

		return applyTwoRows(widgets, collision.getSide(), collision.getSource());
	}

	public Result restoreNative() {
		final Widgets widgets = getWidgets();
		if (pluginTwoRows && widgets != null) {
			reconcileRowDrags(widgets);
		}

		Result result = Result.NONE;
		if (pluginTwoRows && hasFullOwnership() && oneRowKnown && widgets != null) {
			result = applyOneRow(widgets);
		} else {
			final int overlayMutations = restoreOverlays();
			if (overlayMutations > 0) {
				result = new Result(overlayMutations, 0);
			}
		}

		clearPluginState();
		return result;
	}

	public void reset() {
		restoreNative();
	}

	private void clearPluginState() {
		nativeLayoutRunning = false;
		canvasResizeInProgress = false;
		canvasRebasePending = false;
		pluginTwoRows = false;
		staticRowOwned = false;
		movableRowOwned = false;
		splitSide = CollisionManager.Side.NONE;
		verticalSplit = VerticalSplit.UP;
		collisionSource = CollisionManager.Source.NONE;
		inventoryOwnedTarget = null;
		inventoryGuardLocation = null;
		clearOneRow();
	}

	private boolean reconcileRowDrags(Widgets widgets) {
		if (!pluginTwoRows || widgets == null) {
			return false;
		}

		final boolean staticUserDrag = staticRowOwned && hasUserDrag(staticOverlayState);
		final boolean movableUserDrag = movableRowOwned && hasUserDrag(movableOverlayState);
		if (!staticUserDrag && !movableUserDrag) {
			return false;
		}

		if (staticUserDrag) {
			releaseOverlay(true, true);
			staticRowOwned = false;
		}

		if (movableUserDrag) {
			releaseOverlay(false, true);
			movableRowOwned = false;
		}

		if (!inventoryOffsetOwned()) {
			restoreInventoryOverlay();
			inventoryOwnedTarget = null;
			inventoryGuardLocation = null;
		}

		if (!staticRowOwned && !movableRowOwned) {
			pluginTwoRows = false;
			splitSide = CollisionManager.Side.NONE;
			collisionSource = CollisionManager.Source.NONE;
			canvasRebasePending = false;
			clearOneRow();
		}

		return true;
	}

	private boolean hasFullOwnership() {
		return pluginTwoRows && staticRowOwned && movableRowOwned;
	}

	private boolean hasPartialOwnership() {
		return pluginTwoRows && staticRowOwned != movableRowOwned;
	}

	private static boolean hasUserDrag(OverlayState state) {
		if (state == null || state.temporaryLocation == null) {
			return false;
		}

		return !samePoint(state.overlay.getPreferredLocation(), state.temporaryLocation)
				|| state.overlay.getPreferredPosition() != null;
	}

	/**
	 * ================================================================
	 * ROW LAYOUT
	 * ================================================================
	 */
	private Result applyTwoRows(Widgets widgets, CollisionManager.Side side, CollisionManager.Source source) {
		if (!oneRowKnown || staticRowBounds == null || movableRowBounds == null || side == null || side == CollisionManager.Side.NONE) {
			return Result.NONE;
		}

		staticRowOwned = true;
		movableRowOwned = true;
		pluginTwoRows = true;
		final int rowHeight = Math.max(1, Math.max(staticRowBounds.height, movableRowBounds.height));
		verticalSplit = chooseVerticalSplit(rowHeight);
		splitSide = side;
		collisionSource = source != null
				? source
				: CollisionManager.Source.NONE;
		return reassertOwnedRows(widgets, splitSide, collisionSource);
	}

	private Result reassertOwnedRows(Widgets widgets, CollisionManager.Side side, CollisionManager.Source source) {
		if (!pluginTwoRows || !oneRowKnown || staticRowBounds == null || movableRowBounds == null
				|| side == null || side == CollisionManager.Side.NONE) {
			return Result.NONE;
		}

		final int rowHeight = Math.max(1, Math.max(staticRowBounds.height, movableRowBounds.height));
		final int leftX = Math.min(staticRowBounds.x, movableRowBounds.x);
		final int rightX = Math.max(staticRowBounds.x, movableRowBounds.x);
		final int anchorX = side == CollisionManager.Side.RIGHT
				? leftX
				: rightX;
		final int upperRowY;
		final int lowerRowY;
		if (verticalSplit == VerticalSplit.DOWN) {
			upperRowY = movableRowBounds.y;
			lowerRowY = upperRowY + rowHeight;
		} else {
			lowerRowY = staticRowBounds.y;
			upperRowY = lowerRowY - rowHeight;
		}
		int mutations = 0;
		int revalidates = 0;

		/*
		 * TABS2 is always the upper row and TABS1 is always the lower row.
		 */
		if (movableRowOwned) {
			if (applyOverlay(MOVABLE_TABS_OVERLAY, widgets.movableLayer, anchorX, upperRowY, false)) {
				mutations++;
			} else if (forceWidgetPosition(widgets.movableLayer, anchorX, upperRowY)) {
				mutations++;
				widgets.movableLayer.revalidate();
				revalidates++;
			}
		}

		if (staticRowOwned) {
			if (applyOverlay(STATIC_TABS_OVERLAY, widgets.staticLayer, anchorX, lowerRowY, true)) {
				mutations++;
			} else if (forceWidgetPosition(widgets.staticLayer, anchorX, lowerRowY)) {
				mutations++;
				widgets.staticLayer.revalidate();
				revalidates++;
			}
		}

		if (adoptInventoryGuard()) {
			inventoryUserOverride = false;
		}

		final boolean inventoryDragDetected = hasInventoryDrag();
		if (inventoryDragDetected && !inventoryUserOverride) {
			if (inventoryOverlayState != null) {
				inventoryOverlayState.temporaryLocation = null;
			}
			inventoryForcedPosition = false;
			inventoryUserOverride = true;
			widgets.container.setForcedPosition(-1, -1);
			widgets.container.revalidate();
			mutations++;
			revalidates++;
		}

		if (!inventoryDragDetected && inventoryUserOverride && !hasManualPlacement(INVENTORY_OVERLAY)
				&& inventoryAttachment(InterfaceBounds.liveBounds(widgets.container),
				staticRowBounds, movableRowBounds) == rowInventoryAttachment) {
			inventoryUserOverride = false;
		}

		Rectangle targetContainerBounds = null;
		if (inventoryOffsetOwned() && containerRowBounds != null) {
			final int inventoryY = rowInventoryAttachment == InventoryAttachment.BELOW
					? containerRowBounds.y + rowHeight
					: containerRowBounds.y - rowHeight;
			final Rectangle ownedContainerBounds = new Rectangle(
					containerRowBounds.x,
					inventoryY,
					containerRowBounds.width,
					containerRowBounds.height);
			inventoryOwnedTarget = new Point(ownedContainerBounds.x, ownedContainerBounds.y);
			if (!inventoryUserOverride) {
				targetContainerBounds = ownedContainerBounds;
				if (applyInventoryPosition(widgets.container, ownedContainerBounds.x, ownedContainerBounds.y)) {
					mutations++;
				}
			}
		} else {
			inventoryOwnedTarget = null;
			inventoryGuardLocation = null;
		}

		splitSide = side;
		collisionSource = source != null
				? source
				: CollisionManager.Source.NONE;

		final Rectangle staticOverride = staticRowOwned
				? new Rectangle(anchorX, lowerRowY, staticRowBounds.width, staticRowBounds.height)
				: null;
		final Rectangle movableOverride = movableRowOwned
				? new Rectangle(anchorX, upperRowY, movableRowBounds.width, movableRowBounds.height)
				: null;
		final InterfaceBounds.Overrides overrides = new InterfaceBounds.Overrides(
				staticOverride, movableOverride, targetContainerBounds);
		return new Result(mutations, revalidates, overrides);
	}

	private Result applyOneRow(Widgets widgets) {
		int mutations = restoreOverlays();
		int revalidates = 0;

		boolean staticChanged = false;
		if (widgets.staticLayer.getOriginalX() != staticRowX || widgets.staticLayer.getOriginalY() != staticRowY) {
			widgets.staticLayer.setOriginalX(staticRowX);
			widgets.staticLayer.setOriginalY(staticRowY);
			mutations++;
			staticChanged = true;
		}

		if (staticRowBounds != null && forceWidgetPosition(widgets.staticLayer, staticRowBounds.x, staticRowBounds.y)) {
			mutations++;
			staticChanged = true;
		}

		if (staticChanged) {
			widgets.staticLayer.revalidate();
			revalidates++;
		}

		boolean movableChanged = false;
		if (widgets.movableLayer.getOriginalX() != movableRowX || widgets.movableLayer.getOriginalY() != movableRowY) {
			widgets.movableLayer.setOriginalX(movableRowX);
			widgets.movableLayer.setOriginalY(movableRowY);
			mutations++;
			movableChanged = true;
		}

		if (movableRowBounds != null && forceWidgetPosition(widgets.movableLayer, movableRowBounds.x, movableRowBounds.y)) {
			mutations++;
			movableChanged = true;
		}

		if (movableChanged) {
			widgets.movableLayer.revalidate();
			revalidates++;
		}

		inventoryUserOverride = false;
		inventoryOwnedTarget = null;
		inventoryGuardLocation = null;
		pluginTwoRows = false;
		staticRowOwned = false;
		movableRowOwned = false;
		splitSide = CollisionManager.Side.NONE;
		verticalSplit = VerticalSplit.UP;
		collisionSource = CollisionManager.Source.NONE;

		final InterfaceBounds.Overrides overrides = new InterfaceBounds.Overrides(staticRowBounds, movableRowBounds, containerRowBounds);
		return new Result(mutations, revalidates, overrides);
	}

	private void captureOneRow(Widgets widgets) {
		if (pluginTwoRows) {
			return;
		}

		final Rectangle staticBounds = rowBounds(widgets.staticLayer, STATIC_TABS_OVERLAY);
		final Rectangle movableBounds = rowBounds(widgets.movableLayer, MOVABLE_TABS_OVERLAY);
		final Rectangle containerBounds = InterfaceBounds.liveBounds(widgets.container);
		if (!isOneRow(staticBounds, movableBounds)) {
			clearOneRow();
			return;
		}

		captureRowOriginals(widgets);
		staticRowBounds = new Rectangle(staticBounds);
		movableRowBounds = new Rectangle(movableBounds);
		containerRowBounds = containerBounds != null && !containerBounds.isEmpty()
				? new Rectangle(containerBounds)
				: null;
		rowInventoryAttachment = inventoryAttachment(containerRowBounds, staticRowBounds, movableRowBounds);
		rowCanvasWidth = Math.max(0, client.getCanvasWidth());
		rowCanvasHeight = Math.max(0, client.getCanvasHeight());
		canvasRebasePending = false;
		oneRowKnown = true;
	}

	private void clearOneRow() {
		oneRowKnown = false;
		staticRowBounds = null;
		movableRowBounds = null;
		containerRowBounds = null;
		rowInventoryAttachment = InventoryAttachment.NONE;
		verticalSplit = VerticalSplit.UP;
		rowCanvasWidth = 0;
		rowCanvasHeight = 0;
		canvasRebasePending = false;
		inventoryUserOverride = false;
		inventoryOwnedTarget = null;
		inventoryGuardLocation = null;
	}

	private void captureRowOriginals(Widgets widgets) {
		if (widgets == null) {
			return;
		}

		staticRowX = widgets.staticLayer.getOriginalX();
		staticRowY = widgets.staticLayer.getOriginalY();
		movableRowX = widgets.movableLayer.getOriginalX();
		movableRowY = widgets.movableLayer.getOriginalY();
	}

	private boolean rebaseCanvasRows() {
		if (!oneRowKnown || staticRowBounds == null || movableRowBounds == null) {
			return false;
		}

		final int canvasWidth = Math.max(0, client.getCanvasWidth());
		final int canvasHeight = Math.max(0, client.getCanvasHeight());
		if (canvasWidth <= 0 || canvasHeight <= 0) {
			return false;
		}

		if (rowCanvasWidth <= 0 || rowCanvasHeight <= 0) {
			rowCanvasWidth = canvasWidth;
			rowCanvasHeight = canvasHeight;
			return false;
		}

		final int canvasDeltaX = canvasWidth - rowCanvasWidth;
		final int canvasDeltaY = canvasHeight - rowCanvasHeight;
		if (canvasDeltaX == 0 && canvasDeltaY == 0) {
			return false;
		}

		/*
		 * Resolves canvas growth caused by the Swing side panel.
		 */
		final int rowRight = Math.max(staticRowBounds.x + staticRowBounds.width, movableRowBounds.x + movableRowBounds.width);
		final int rowBottom = Math.max(staticRowBounds.y + staticRowBounds.height, movableRowBounds.y + movableRowBounds.height);
		final boolean rightAnchored = Math.abs(rowCanvasWidth - rowRight) <= CANVAS_EDGE_TOLERANCE;
		final boolean bottomAnchored = Math.abs(rowCanvasHeight - rowBottom) <= CANVAS_EDGE_TOLERANCE;
		final int deltaX = rightAnchored ? canvasDeltaX : 0;
		final int deltaY = bottomAnchored ? canvasDeltaY : 0;

		rowCanvasWidth = canvasWidth;
		rowCanvasHeight = canvasHeight;
		if (deltaX == 0 && deltaY == 0) {
			return false;
		}

		staticRowBounds.translate(deltaX, deltaY);
		movableRowBounds.translate(deltaX, deltaY);
		if (containerRowBounds != null) {
			containerRowBounds.translate(deltaX, deltaY);
		}

		translateOverlayState(staticOverlayState, deltaX, deltaY);
		translateOverlayState(movableOverlayState, deltaX, deltaY);
		translateOverlayState(inventoryOverlayState, deltaX, deltaY);
		return true;
	}

	private static void translateOverlayState(OverlayState state, int deltaX, int deltaY) {
		if (state == null) {
			return;
		}

		state.originalBounds.translate(deltaX, deltaY);
	}

	private boolean canCaptureRow(Widgets widgets) {
		if (widgets == null) {
			return false;
		}

		return isOneRow(rowBounds(widgets.staticLayer, STATIC_TABS_OVERLAY), rowBounds(widgets.movableLayer, MOVABLE_TABS_OVERLAY));
	}

	private Rectangle rowBounds(Widget widget, String overlayName) {
		if (widget == null) {
			return null;
		}

		if (overlayManager != null) {
			final Overlay overlay = findOverlay(overlayName);
			if (overlay != null && (overlay.getPreferredLocation() != null || overlay.getPreferredPosition() != null)) {
				final Rectangle overlayBounds = overlay.getBounds();
				if (overlayBounds != null && !overlayBounds.isEmpty()) {
					return new Rectangle(overlayBounds);
				}
			}
		}

		return InterfaceBounds.liveBounds(widget);
	}

	private boolean hasManualRows() {
		return hasManualPlacement(STATIC_TABS_OVERLAY) || hasManualPlacement(MOVABLE_TABS_OVERLAY);
	}

	private boolean hasManualPlacement(String overlayName) {
		if (overlayManager == null) {
			return false;
		}

		final Overlay overlay = findOverlay(overlayName);
		return overlay != null && (overlay.getPreferredLocation() != null || overlay.getPreferredPosition() != null);
	}

	/**
	 * ================================================================
	 * OVERLAY MANAGEMENT
	 * ================================================================
	 */
	private boolean applyInventoryPosition(Widget widget, int targetX, int targetY) {
		if (widget == null) {
			return false;
		}

		final Overlay overlay = overlayManager != null
				? findOverlay(INVENTORY_OVERLAY)
				: null;
		if (overlay != null) {
			if (inventoryOverlayState != null && inventoryOverlayState.overlay != overlay) {
				restoreInventoryOverlay();
			}

			if (inventoryOverlayState == null) {
				final Rectangle currentBounds = InterfaceBounds.liveBounds(widget);
				if (currentBounds == null || currentBounds.isEmpty()) {
					return false;
				}

				inventoryOverlayState = new OverlayState(overlay, widget, copy(overlay.getPreferredLocation()),
						overlay.getPreferredPosition(), new Rectangle(currentBounds));
			}

			return applyOverlayState(inventoryOverlayState, targetX, targetY);
		}

		if (!forceWidgetPosition(widget, targetX, targetY)) {
			return false;
		}

		inventoryForcedPosition = true;
		return true;
	}

	private Result reassertOneRow(Widgets widgets) {
		if (!oneRowKnown || staticRowBounds == null || movableRowBounds == null) {
			return Result.NONE;
		}

		int mutations = 0;
		int revalidates = 0;
		if (forceWidgetPosition(widgets.staticLayer, staticRowBounds.x, staticRowBounds.y)) {
			mutations++;
			widgets.staticLayer.revalidate();
			revalidates++;
		}

		if (forceWidgetPosition(widgets.movableLayer, movableRowBounds.x, movableRowBounds.y)) {
			mutations++;
			widgets.movableLayer.revalidate();
			revalidates++;
		}

		if (rowInventoryAttachment != InventoryAttachment.NONE && containerRowBounds != null
				&& forceWidgetPosition(widgets.container, containerRowBounds.x, containerRowBounds.y)) {
			mutations++;
			widgets.container.revalidate();
			revalidates++;
		}

		final InterfaceBounds.Overrides overrides = new InterfaceBounds.Overrides(staticRowBounds, movableRowBounds, containerRowBounds);
		return new Result(mutations, revalidates, overrides);
	}

	private void releaseOverlay(boolean staticOverlay, boolean userDragged) {
		final OverlayState state = staticOverlay
				? staticOverlayState
				: movableOverlayState;
		if (state == null) {
			return;
		}

		if (!userDragged) {
			restoreOverlay(staticOverlay);
			state.widget.revalidate();
			return;
		}

		if (staticOverlay) {
			staticOverlayState = null;
		} else {
			movableOverlayState = null;
		}

		final Rectangle overlayBounds = state.overlay.getBounds();
		if (overlayBounds != null && !overlayBounds.isEmpty() && forceWidgetPosition(state.widget, overlayBounds.x, overlayBounds.y)) {
			state.widget.revalidate();
		}
	}

	private boolean applyOverlayState(OverlayState state, int targetX, int targetY) {
		final int deltaX = targetX - state.originalBounds.x;
		final int deltaY = targetY - state.originalBounds.y;
		final Point temporaryLocation = state.preferredLocation != null
				? new Point(state.preferredLocation.x + deltaX, state.preferredLocation.y + deltaY)
				: new Point(targetX, targetY);

		final boolean alreadyApplied = samePoint(state.overlay.getPreferredLocation(), temporaryLocation)
				&& state.overlay.getPreferredPosition() == null && state.overlay.getBounds().x == targetX
				&& state.overlay.getBounds().y == targetY;
		state.temporaryLocation = new Point(temporaryLocation);
		if (alreadyApplied) {
			forceWidgetPosition(state.widget, targetX, targetY);
			return false;
		}

		state.overlay.setPreferredPosition(null);
		state.overlay.setPreferredLocation(temporaryLocation);
		state.overlay.getBounds().setLocation(targetX, targetY);
		forceWidgetPosition(state.widget, targetX, targetY);
		inventoryForcedPosition = true;
		return true;
	}

	private boolean hasInventoryDrag() {
		final OverlayState state = inventoryOverlayState;
		if (state == null) {
			return false;
		}

		if (state.temporaryLocation != null) {
			return hasUserDrag(state);
		}

		return !samePoint(state.overlay.getPreferredLocation(), state.preferredLocation)
				|| state.overlay.getPreferredPosition() != state.preferredPosition;
	}

	private boolean adoptInventoryGuard() {
		final Point guarded = inventoryGuardLocation;
		final OverlayState state = inventoryOverlayState;
		if (guarded == null || state == null || !samePoint(state.overlay.getPreferredLocation(), guarded)
				|| state.overlay.getPreferredPosition() != null) {
			return false;
		}

		state.temporaryLocation = new Point(guarded);
		inventoryGuardLocation = null;
		return true;
	}

	private boolean applyOverlay(String overlayName, Widget widget, int targetX, int targetY, boolean staticOverlay) {
		if (overlayManager == null || widget == null) {
			return false;
		}

		final Overlay overlay = findOverlay(overlayName);
		if (overlay == null) {
			return false;
		}

		OverlayState state = staticOverlay
				? staticOverlayState
				: movableOverlayState;
		if (state != null && state.overlay != overlay) {
			restoreOverlay(staticOverlay);
			state = null;
		}

		if (state == null) {
			final Rectangle currentBounds = InterfaceBounds.liveBounds(widget);
			if (currentBounds == null || currentBounds.isEmpty()) {
				return false;
			}

			final Point preferredLocation = copy(overlay.getPreferredLocation());
			final OverlayPosition preferredPosition = overlay.getPreferredPosition();

			state = new OverlayState(overlay, widget, preferredLocation, preferredPosition, new Rectangle(currentBounds));

			if (staticOverlay) {
				staticOverlayState = state;
			} else {
				movableOverlayState = state;
			}
		}

		/*
		 * Calculates temporary overlay offsets from the captured one-row bounds.
		 */
		final int deltaX = targetX - state.originalBounds.x;
		final int deltaY = targetY - state.originalBounds.y;
		final Point temporaryLocation = state.preferredLocation != null
				? new Point(state.preferredLocation.x + deltaX, state.preferredLocation.y + deltaY)
				: new Point(targetX, targetY);

		final boolean alreadyApplied = samePoint(state.overlay.getPreferredLocation(), temporaryLocation)
				&& state.overlay.getPreferredPosition() == null && state.overlay.getBounds().x == targetX
				&& state.overlay.getBounds().y == targetY;
		state.temporaryLocation = new Point(temporaryLocation);
		if (alreadyApplied) {
			forceWidgetPosition(widget, targetX, targetY);
			return false;
		}

		state.overlay.setPreferredPosition(null);
		state.overlay.setPreferredLocation(temporaryLocation);
		state.overlay.getBounds().setLocation(targetX, targetY);
		forceWidgetPosition(widget, targetX, targetY);
		return true;
	}

	private int restoreOverlays() {
		int mutations = 0;
		if (restoreInventoryOverlay()) {
			mutations++;
		}

		if (restoreOverlay(false)) {
			mutations++;
		}

		if (restoreOverlay(true)) {
			mutations++;
		}

		return mutations;
	}

	private boolean restoreInventoryOverlay() {
		final OverlayState state = inventoryOverlayState;
		inventoryOverlayState = null;

		if (state == null) {
			if (!inventoryForcedPosition) {
				return false;
			}

			final Widgets widgets = getWidgets();
			inventoryForcedPosition = false;
			if (widgets == null) {
				return false;
			}

			widgets.container.setForcedPosition(-1, -1);
			widgets.container.revalidate();
			return true;
		}

		if (state.temporaryLocation != null) {
			final Point currentLocation = state.overlay.getPreferredLocation();
			final boolean temporaryStillOwned = samePoint(currentLocation, state.temporaryLocation) && state.overlay.getPreferredPosition() == null;
			if (!temporaryStillOwned) {
				inventoryForcedPosition = false;
				return false;
			}

			state.overlay.setPreferredLocation(copy(state.preferredLocation));
			state.overlay.setPreferredPosition(state.preferredPosition);
			state.overlay.getBounds().setBounds(state.originalBounds);
			forceWidgetPosition(state.widget, state.originalBounds.x, state.originalBounds.y);
			inventoryForcedPosition = false;
			return true;
		}

		final boolean originalOverlayState = samePoint(state.overlay.getPreferredLocation(), state.preferredLocation)
				&& state.overlay.getPreferredPosition() == state.preferredPosition;
		if (!originalOverlayState) {
			inventoryForcedPosition = false;
			return false;
		}

		state.widget.setForcedPosition(-1, -1);
		state.widget.revalidate();
		state.overlay.getBounds().setBounds(state.originalBounds);
		inventoryForcedPosition = false;
		return true;
	}

	private boolean restoreOverlay(boolean staticOverlay) {
		final OverlayState state = staticOverlay
				? staticOverlayState
				: movableOverlayState;
		if (state == null) {
			return false;
		}

		if (staticOverlay) {
			staticOverlayState = null;
		} else {
			movableOverlayState = null;
		}

		/*
		 * Preserves user placement when ChatXL no longer owns the temporary position.
		 */
		final Point currentLocation = state.overlay.getPreferredLocation();
		final boolean temporaryStillOwned = samePoint(currentLocation, state.temporaryLocation) && state.overlay.getPreferredPosition() == null;
		if (!temporaryStillOwned) {
			return false;
		}

		state.overlay.setPreferredLocation(copy(state.preferredLocation));
		state.overlay.setPreferredPosition(state.preferredPosition);
		state.overlay.getBounds().setBounds(state.originalBounds);
		forceWidgetPosition(state.widget, state.originalBounds.x, state.originalBounds.y);
		return true;
	}

	private boolean forceWidgetPosition(Widget widget, int x, int y) {
		if (widget == null) {
			return false;
		}

		final Rectangle current = InterfaceBounds.liveBounds(widget);
		if (current != null && current.x == x && current.y == y) {
			return false;
		}

		final Widget parent = widget.getParent();
		final Rectangle parentBounds = parent != null ? parent.getBounds() : null;
		if (parentBounds != null) {
			widget.setForcedPosition(x - parentBounds.x, y - parentBounds.y);
		} else {
			widget.setForcedPosition(x, y);
		}

		return true;
	}

	private Overlay findOverlay(String name) {
		final Overlay[] match = new Overlay[1];
		overlayManager.anyMatch(overlay -> {
			if (name.equals(overlay.getName())) {
				match[0] = overlay;
				return true;
			}

			return false;
		});
		return match[0];
	}

	/**
	 * ================================================================
	 * GEOMETRY HELPERS
	 * ================================================================
	 */
	private Rectangle desiredBounds(Widget slot, int configuredWidth, int configuredHeight) {
		final Rectangle slotBounds = InterfaceBounds.liveBounds(slot);
		if (slotBounds == null) {
			return null;
		}

		/*
		 * Uses the live host position with configured dimensions; ChatboxBounds applies temporary constraints.
		 */
		return new Rectangle(slotBounds.x, slotBounds.y, Math.max(1, configuredWidth), Math.max(1, configuredHeight));
	}

	private Widgets getWidgets() {
		if (!isModernLayout()) {
			return null;
		}

		final Widget staticLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER);
		final Widget movableLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER);
		final Widget container = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER);
		if (staticLayer == null || movableLayer == null || container == null || staticLayer.isHidden() || movableLayer.isHidden()) {
			return null;
		}

		return new Widgets(staticLayer, movableLayer, container);
	}

	private boolean isModernLayout() {
		return client.getTopLevelInterfaceId() == InterfaceID.TOPLEVEL_PRE_EOC;
	}

	private static boolean isOneRow(Rectangle staticBounds, Rectangle movableBounds) {
		if (staticBounds == null || movableBounds == null || staticBounds.isEmpty() || movableBounds.isEmpty()) {
			return false;
		}

		final int overlapLeft = Math.max(staticBounds.x, movableBounds.x);
		final int overlapRight = Math.min(staticBounds.x + staticBounds.width, movableBounds.x + movableBounds.width);
		final int horizontalOverlap = Math.max(0, overlapRight - overlapLeft);
		if (horizontalOverlap < MIN_ONE_ROW_OVERLAP || horizontalOverlap > MAX_ONE_ROW_OVERLAP) {
			return false;
		}

		final int rowHeight = Math.max(1, Math.min(staticBounds.height, movableBounds.height));
		return Math.abs(staticBounds.y - movableBounds.y) < Math.max(1, rowHeight / 2);
	}

	private static InventoryAttachment inventoryAttachment(Rectangle containerBounds, Rectangle staticBounds, Rectangle movableBounds) {
		if (containerBounds == null || staticBounds == null || movableBounds == null
				|| containerBounds.isEmpty() || staticBounds.isEmpty() || movableBounds.isEmpty()) {
			return InventoryAttachment.NONE;
		}

		final Rectangle stripBounds = new Rectangle(staticBounds);
		stripBounds.add(movableBounds);
		final int containerRight = containerBounds.x + containerBounds.width;
		final int stripRight = stripBounds.x + stripBounds.width;
		final boolean horizontallyNear = containerBounds.x <= stripRight + INVENTORY_HORIZONTAL_TOLERANCE
				&& containerRight >= stripBounds.x - INVENTORY_HORIZONTAL_TOLERANCE;
		if (!horizontallyNear) {
			return InventoryAttachment.NONE;
		}

		final int rowHeight = Math.max(1, Math.max(staticBounds.height, movableBounds.height));
		final int containerBottom = containerBounds.y + containerBounds.height;
		final int stripBottom = stripBounds.y + stripBounds.height;
		final int aboveGap = stripBounds.y - containerBottom;
		final int belowGap = containerBounds.y - stripBottom;
		final boolean above = aboveGap >= -INVENTORY_EDGE_TOLERANCE && aboveGap <= rowHeight;
		final boolean below = belowGap >= -INVENTORY_EDGE_TOLERANCE && belowGap <= rowHeight;

		if (above && below) {
			return Math.abs(aboveGap) <= Math.abs(belowGap)
					? InventoryAttachment.ABOVE
					: InventoryAttachment.BELOW;
		}

		if (above) {
			return InventoryAttachment.ABOVE;
		}

		return below
				? InventoryAttachment.BELOW
				: InventoryAttachment.NONE;
	}

	private boolean inventoryOffsetOwned() {
		return rowInventoryAttachment == InventoryAttachment.ABOVE && verticalSplit == VerticalSplit.UP && movableRowOwned
				|| rowInventoryAttachment == InventoryAttachment.BELOW && verticalSplit == VerticalSplit.DOWN && staticRowOwned;
	}

	private VerticalSplit chooseVerticalSplit(int rowHeight) {
		final int canvasHeight = Math.max(0, client.getCanvasHeight());
		final int upperCandidateY = staticRowBounds.y - rowHeight;
		final int lowerCandidateY = movableRowBounds.y + rowHeight;
		final int lowerCandidateBottom = lowerCandidateY + staticRowBounds.height;
		final boolean upFits = upperCandidateY >= 0;
		final boolean downFits = canvasHeight <= 0 || lowerCandidateBottom <= canvasHeight;

		if (rowInventoryAttachment == InventoryAttachment.ABOVE) {
			if (upFits || !downFits) {
				return VerticalSplit.UP;
			}
			return VerticalSplit.DOWN;
		}

		if (rowInventoryAttachment == InventoryAttachment.BELOW) {
			if (downFits || !upFits) {
				return VerticalSplit.DOWN;
			}
			return VerticalSplit.UP;
		}

		if (upFits) {
			return VerticalSplit.UP;
		}

		if (downFits) {
			return VerticalSplit.DOWN;
		}

		final int rowTop = Math.min(staticRowBounds.y, movableRowBounds.y);
		final int rowBottom = Math.max(staticRowBounds.y + staticRowBounds.height, movableRowBounds.y + movableRowBounds.height);
		final int spaceAbove = Math.max(0, rowTop);
		final int spaceBelow = canvasHeight > 0
				? Math.max(0, canvasHeight - rowBottom)
				: 0;
		return spaceBelow > spaceAbove
				? VerticalSplit.DOWN
				: VerticalSplit.UP;
	}

	private static Point copy(Point point) {
		return point != null ? new Point(point) : null;
	}

	private static boolean samePoint(Point first, Point second) {
		return first == second || first != null && first.equals(second);
	}

	/**
	 * ================================================================
	 * STATE TYPES
	 * ================================================================
	 */
	private enum InventoryAttachment {
		NONE,
		ABOVE,
		BELOW
	}

	private enum VerticalSplit {
		UP,
		DOWN
	}

	private static final class Widgets {
		private final Widget staticLayer;
		private final Widget movableLayer;
		private final Widget container;

		private Widgets(Widget staticLayer, Widget movableLayer, Widget container) {
			this.staticLayer = staticLayer;
			this.movableLayer = movableLayer;
			this.container = container;
		}
	}

	private static final class OverlayState {
		private final Overlay overlay;
		private final Widget widget;
		private final Point preferredLocation;
		private final OverlayPosition preferredPosition;
		private final Rectangle originalBounds;
		private Point temporaryLocation;

		private OverlayState(Overlay overlay, Widget widget, Point preferredLocation, OverlayPosition preferredPosition, Rectangle originalBounds) {
			this.overlay = overlay;
			this.widget = widget;
			this.preferredLocation = preferredLocation;
			this.preferredPosition = preferredPosition;
			this.originalBounds = originalBounds;
		}
	}

	public static final class Result {
		private static final Result NONE = new Result(0, 0, null);

		private final int mutations;
		private final int revalidates;
		private final InterfaceBounds.Overrides interfaceOverrides;

		private Result(int mutations, int revalidates) {
			this(mutations, revalidates, null);
		}

		private Result(int mutations, int revalidates, InterfaceBounds.Overrides interfaceOverrides) {
			this.mutations = mutations;
			this.revalidates = revalidates;
			this.interfaceOverrides = interfaceOverrides;
		}

		public int getMutations() {
			return mutations;
		}

		public int getRevalidates() {
			return revalidates;
		}

		public InterfaceBounds.Overrides getInterfaceOverrides() {
			return interfaceOverrides;
		}
	}
}

package com.bigboldchat.overlay;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/*
 * Transparent RuneLite overlay used as the movable handle for split private chat.
 */
public final class PrivateChatOverlay extends Overlay {
	private Rectangle naturalBounds;

	public PrivateChatOverlay() {
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(true);
		setSnappable(true);
	}

	@Override
	public String getName() {
		return "CHATXL_SPLIT_PM";
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (naturalBounds == null || naturalBounds.isEmpty()) {
			return null;
		}

		/*
		 * The drag surface represents the PM layout rectangle, not the union of
		 * text-widget widths. This keeps horizontal Alt-drag usable even when a
		 * stale or malformed row temporarily extends beyond the effective width.
		 */
		if (!isManuallyPositioned()) {
			getBounds().setLocation(naturalBounds.x, naturalBounds.y);
		}

		return new Dimension(naturalBounds.width, naturalBounds.height);
	}

	public boolean isManuallyPositioned() {
		return getPreferredLocation() != null || getPreferredPosition() != null;
	}

	public void setNaturalBounds(Rectangle bounds) {
		naturalBounds = bounds == null
				? null
				: new Rectangle(bounds);
	}
}

